IF OBJECT_ID(N'dbo.QL_BenhNhan', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.QL_BenhNhan
    (
        ID BIGINT IDENTITY(1,1) NOT NULL,
        IDCSKCB BIGINT NOT NULL,
        MaBN NVARCHAR(30) NOT NULL,
        HoTen NVARCHAR(200) NOT NULL,
        NgaySinh DATE NULL,
        Tuoi INT NULL,
        IDGioiTinh TINYINT NULL,
        SoCCCD NVARCHAR(20) NULL,
        DienThoai NVARCHAR(20) NULL,
        SoNhaTenDuong NVARCHAR(300) NULL,
        IDPhuongXa BIGINT NULL,
        IDTinhThanh BIGINT NULL,
        DiaChi NVARCHAR(500) NULL,
        IDDanToc BIGINT NULL,
        QuocTich NVARCHAR(100) NULL,
        NgheNghiep NVARCHAR(150) NULL,
        GiamHo_MoiQuanHe NVARCHAR(50) NULL,
        GiamHo_HoTen NVARCHAR(150) NULL,
        GiamHo_DienThoai NVARCHAR(20) NULL,
        GiamHo_SoCCCD NVARCHAR(20) NULL,
        GhiChu NVARCHAR(1000) NULL,
        Active BIT NOT NULL CONSTRAINT DF_QL_BenhNhan_Active DEFAULT(1),
        NgayTao DATETIME2(0) NOT NULL CONSTRAINT DF_QL_BenhNhan_NgayTao DEFAULT(SYSDATETIME()),
        NgayCapNhat DATETIME2(0) NULL,
        CONSTRAINT PK_QL_BenhNhan PRIMARY KEY(ID),
        CONSTRAINT FK_QL_BenhNhan_CSKCB FOREIGN KEY(IDCSKCB) REFERENCES dbo.DM_CSKCB(ID),
        CONSTRAINT FK_QL_BenhNhan_Tinh FOREIGN KEY(IDCSKCB,IDTinhThanh) REFERENCES dbo.DM_TinhThanh(IDCSKCB,ID),
        CONSTRAINT FK_QL_BenhNhan_PX FOREIGN KEY(IDCSKCB,IDPhuongXa) REFERENCES dbo.DM_PhuongXa(IDCSKCB,ID),
        CONSTRAINT FK_QL_BenhNhan_DanToc FOREIGN KEY(IDCSKCB,IDDanToc) REFERENCES dbo.DM_DanToc(IDCSKCB,ID),
        CONSTRAINT CK_QL_BenhNhan_GioiTinh CHECK(IDGioiTinh IS NULL OR IDGioiTinh IN(0,1,2)),
        CONSTRAINT UQ_QL_BenhNhan_CSKCB_Ma UNIQUE(IDCSKCB,MaBN),
        CONSTRAINT UQ_QL_BenhNhan_CSKCB_ID UNIQUE(IDCSKCB,ID)
    );
END;
GO

/* Dong bo DB Hieu cu (GioiTinh) voi contract vat ly moi (IDGioiTinh). */
IF COL_LENGTH(N'dbo.QL_BenhNhan', N'IDGioiTinh') IS NULL
   AND COL_LENGTH(N'dbo.QL_BenhNhan', N'GioiTinh') IS NOT NULL
BEGIN
    EXEC sys.sp_rename N'dbo.QL_BenhNhan.GioiTinh', N'IDGioiTinh', N'COLUMN';
END;
GO

IF COL_LENGTH(N'dbo.QL_BenhNhan', N'IDGioiTinh') IS NULL
    THROW 58001, N'QL_BenhNhan thieu cot IDGioiTinh.', 1;
GO

IF OBJECT_ID(N'dbo.QL_VaoVien', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.QL_VaoVien
    (
        ID BIGINT IDENTITY(1,1) NOT NULL,
        IDCSKCB BIGINT NOT NULL,
        MaVaoVien NVARCHAR(30) NOT NULL,
        IDBenhNhan BIGINT NOT NULL,
        Ngay DATE NOT NULL CONSTRAINT DF_QL_VaoVien_Ngay DEFAULT(CONVERT(DATE,SYSDATETIME())),
        NgayGioVaoVien DATETIME2(0) NOT NULL CONSTRAINT DF_QL_VaoVien_NgayGio DEFAULT(SYSDATETIME()),
        SoThuTu INT NULL,
        IDNguoiTiepNhan BIGINT NULL,
        IDBacSiKham BIGINT NULL,
        MaPDGoc NVARCHAR(50) NULL,
        DaChuyenKham BIT NOT NULL CONSTRAINT DF_QL_VaoVien_DaChuyen DEFAULT(0),
        ThoiGianChuyenKham DATETIME2(0) NULL,
        TrangThaiKham TINYINT NOT NULL CONSTRAINT DF_QL_VaoVien_TrangThai DEFAULT(0),
        BatDauKhamLuc DATETIME2(0) NULL,
        KetThucKhamLuc DATETIME2(0) NULL,
        SinhHieu BIT NOT NULL CONSTRAINT DF_QL_VaoVien_SinhHieu DEFAULT(0),
        Kham BIT NOT NULL CONSTRAINT DF_QL_VaoVien_Kham DEFAULT(0),
        KeToa BIT NOT NULL CONSTRAINT DF_QL_VaoVien_KeToa DEFAULT(0),
        TrieuChung NVARCHAR(2000) NULL,
        IDPhacDo BIGINT NULL,
        HuongDieuTri NVARCHAR(2000) NULL,
        NgayTaiKham DATE NULL,
        GhiChu NVARCHAR(1000) NULL,
        Active BIT NOT NULL CONSTRAINT DF_QL_VaoVien_Active DEFAULT(1),
        NgayTao DATETIME2(0) NOT NULL CONSTRAINT DF_QL_VaoVien_NgayTao DEFAULT(SYSDATETIME()),
        NgayCapNhat DATETIME2(0) NULL,
        RowVersion ROWVERSION,
        CONSTRAINT PK_QL_VaoVien PRIMARY KEY(ID),
        CONSTRAINT FK_QL_VaoVien_CSKCB FOREIGN KEY(IDCSKCB) REFERENCES dbo.DM_CSKCB(ID),
        CONSTRAINT FK_QL_VaoVien_BN FOREIGN KEY(IDCSKCB,IDBenhNhan) REFERENCES dbo.QL_BenhNhan(IDCSKCB,ID),
        CONSTRAINT FK_QL_VaoVien_TiepNhan FOREIGN KEY(IDCSKCB,IDNguoiTiepNhan) REFERENCES dbo.DM_NhanVien(IDCSKCB,ID),
        CONSTRAINT FK_QL_VaoVien_BS FOREIGN KEY(IDCSKCB,IDBacSiKham) REFERENCES dbo.DM_NhanVien(IDCSKCB,ID),
        CONSTRAINT FK_QL_VaoVien_PhacDo FOREIGN KEY(IDCSKCB,IDPhacDo) REFERENCES dbo.DM_PhacDo(IDCSKCB,ID),
        CONSTRAINT CK_QL_VaoVien_TrangThai CHECK(TrangThaiKham BETWEEN 0 AND 3),
        CONSTRAINT UQ_QL_VaoVien_CSKCB_Ma UNIQUE(IDCSKCB,MaVaoVien),
        CONSTRAINT UQ_QL_VaoVien_CSKCB_ID UNIQUE(IDCSKCB,ID)
    );
END;
GO

