        IDCSKCB BIGINT NOT NULL,
        IDThuTien BIGINT NOT NULL,
        IDCongKhamCT BIGINT NULL,
        IDChiDinhCT BIGINT NULL,
        IDToaThuocCT BIGINT NULL,
        SoLuong DECIMAL(10,2) NOT NULL CONSTRAINT DF_QL_ThuTienCT_SL DEFAULT(1),
        DonGia DECIMAL(18,2) NOT NULL CONSTRAINT DF_QL_ThuTienCT_DG DEFAULT(0),
        ThanhTien DECIMAL(18,2) NOT NULL CONSTRAINT DF_QL_ThuTienCT_TT DEFAULT(0),
        TienGiam DECIMAL(18,2) NOT NULL CONSTRAINT DF_QL_ThuTienCT_Giam DEFAULT(0),
        ThucThu DECIMAL(18,2) NOT NULL CONSTRAINT DF_QL_ThuTienCT_Thuc DEFAULT(0),
        DaThu BIT NOT NULL CONSTRAINT DF_QL_ThuTienCT_DaThu DEFAULT(0),
        CONSTRAINT PK_QL_ThuTien_CT PRIMARY KEY(ID),
        CONSTRAINT FK_QL_ThuTienCT_CSKCB FOREIGN KEY(IDCSKCB) REFERENCES dbo.DM_CSKCB(ID),
        CONSTRAINT FK_QL_ThuTienCT_Thu FOREIGN KEY(IDCSKCB,IDThuTien) REFERENCES dbo.QL_ThuTien(IDCSKCB,ID),
        CONSTRAINT FK_QL_ThuTienCT_CK FOREIGN KEY(IDCSKCB,IDCongKhamCT) REFERENCES dbo.QL_CongKham_CT(IDCSKCB,ID),
        CONSTRAINT FK_QL_ThuTienCT_CD FOREIGN KEY(IDCSKCB,IDChiDinhCT) REFERENCES dbo.QL_ChiDinh_CT(IDCSKCB,ID),
        CONSTRAINT FK_QL_ThuTienCT_Toa FOREIGN KEY(IDCSKCB,IDToaThuocCT) REFERENCES dbo.QL_ToaThuoc_CT(IDCSKCB,ID),
        CONSTRAINT CK_QL_ThuTienCT_Nguon CHECK
        (
            (CASE WHEN IDCongKhamCT IS NULL THEN 0 ELSE 1 END)+
            (CASE WHEN IDChiDinhCT IS NULL THEN 0 ELSE 1 END)+
            (CASE WHEN IDToaThuocCT IS NULL THEN 0 ELSE 1 END)=1
        ),
        CONSTRAINT CK_QL_ThuTienCT_Tien CHECK(SoLuong>0 AND DonGia>=0 AND ThanhTien>=0 AND TienGiam>=0 AND ThucThu>=0)
    );
END;
