        NgayTao DATETIME2(0) NOT NULL CONSTRAINT DF_QL_CLS_Phieu_NgayTao_H DEFAULT(SYSDATETIME()),
        NgayCapNhat DATETIME2(0) NULL,

        CONSTRAINT FK_QL_CLS_Phieu_CSKCB_H FOREIGN KEY(IDCSKCB) REFERENCES dbo.DM_CSKCB(ID),
        CONSTRAINT FK_QL_CLS_Phieu_VV_H FOREIGN KEY(IDCSKCB,IDVaoVien) REFERENCES dbo.QL_VaoVien(IDCSKCB,ID),
        CONSTRAINT FK_QL_CLS_Phieu_CD_H FOREIGN KEY(IDCSKCB,IDChiDinhCT) REFERENCES dbo.QL_ChiDinh_CT(IDCSKCB,ID),
        CONSTRAINT FK_QL_CLS_Phieu_DV_H FOREIGN KEY(IDCSKCB,IDDichVu) REFERENCES dbo.DM_DichVu(IDCSKCB,ID),
        CONSTRAINT FK_QL_CLS_Phieu_Form_H FOREIGN KEY(IDCSKCB,IDForm) REFERENCES dbo.QL_CLS_FormKQXN(IDCSKCB,ID),
        CONSTRAINT FK_QL_CLS_Phieu_NVTH_H FOREIGN KEY(IDCSKCB,IDNVThucHien) REFERENCES dbo.DM_NhanVien(IDCSKCB,ID),
        CONSTRAINT FK_QL_CLS_Phieu_BSDoc_H FOREIGN KEY(IDCSKCB,IDBSDoc) REFERENCES dbo.DM_NhanVien(IDCSKCB,ID),
        CONSTRAINT FK_QL_CLS_Phieu_NVDuyet_H FOREIGN KEY(IDCSKCB,IDNhanVienDuyet) REFERENCES dbo.DM_NhanVien(IDCSKCB,ID),
        CONSTRAINT FK_QL_CLS_Phieu_NVHuyDuyet_H FOREIGN KEY(IDCSKCB,IDNhanVienHuyDuyet) REFERENCES dbo.DM_NhanVien(IDCSKCB,ID),
        CONSTRAINT UQ_QL_CLS_Phieu_CD_H UNIQUE(IDCSKCB,IDChiDinhCT),
        CONSTRAINT UQ_QL_CLS_Phieu_CSKCB_ID_H UNIQUE(IDCSKCB,ID),
        CONSTRAINT CK_QL_CLS_Phieu_Loai_H CHECK(LoaiKetQua IN(1,2,3)),
        CONSTRAINT CK_QL_CLS_Phieu_TrangThai_H CHECK(TrangThai BETWEEN 0 AND 4)
    );
END;
GO

