    ALTER TABLE dbo.QL_CLS_PhieuKetQua ADD IDDichVu BIGINT NULL;
GO

UPDATE P
SET P.IDVaoVien=COALESCE(P.IDVaoVien,C.IDVaoVien),
    P.IDDichVu=COALESCE(P.IDDichVu,C.IDDichVu)
FROM dbo.QL_CLS_PhieuKetQua P
INNER JOIN dbo.QL_ChiDinh_CT C
  ON C.IDCSKCB=P.IDCSKCB AND C.ID=P.IDChiDinhCT
WHERE P.IDVaoVien IS NULL OR P.IDDichVu IS NULL;
GO

/* Tương thích DB đã có schema CLS từ contract khác trước khi tạo index. */
IF COL_LENGTH(N'dbo.QL_CLS_FormKQXN_CT',N'Active') IS NULL
    ALTER TABLE dbo.QL_CLS_FormKQXN_CT
        ADD Active BIT NOT NULL CONSTRAINT DF_QL_CLS_FormCT_Active_53 DEFAULT(1) WITH VALUES;
