    ALTER TABLE dbo.QL_CLS_FormKQXN_CT
        ADD STT INT NOT NULL CONSTRAINT DF_QL_CLS_FormCT_STT_53 DEFAULT(999) WITH VALUES;

IF COL_LENGTH(N'dbo.QL_CLS_KetQuaXN_CT',N'Active') IS NULL
    ALTER TABLE dbo.QL_CLS_KetQuaXN_CT
        ADD Active BIT NOT NULL CONSTRAINT DF_QL_CLS_KQXN_Active_53 DEFAULT(1) WITH VALUES;
IF COL_LENGTH(N'dbo.QL_CLS_KetQuaXN_CT',N'STT') IS NULL
    ALTER TABLE dbo.QL_CLS_KetQuaXN_CT
        ADD STT INT NOT NULL CONSTRAINT DF_QL_CLS_KQXN_STT_53 DEFAULT(999) WITH VALUES;

IF COL_LENGTH(N'dbo.QL_CLS_PhieuKetQua_File',N'Active') IS NULL
    ALTER TABLE dbo.QL_CLS_PhieuKetQua_File
        ADD Active BIT NOT NULL CONSTRAINT DF_QL_CLS_File_Active_53 DEFAULT(1) WITH VALUES;
