    ALTER TABLE dbo.QL_CLS_PhieuKetQua_File
        ADD NgayTaiLen DATETIME2(0) NOT NULL CONSTRAINT DF_QL_CLS_File_Ngay_53 DEFAULT(SYSDATETIME()) WITH VALUES;
GO

IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.QL_CLS_FormKQXN_CT') AND name=N'IX_QL_CLS_FormCT_Form_H')
    CREATE INDEX IX_QL_CLS_FormCT_Form_H
    ON dbo.QL_CLS_FormKQXN_CT(IDCSKCB,IDForm,Active,STT) INCLUDE(IDTriSoXN);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.QL_CLS_KetQuaXN_CT') AND name=N'IX_QL_CLS_KQXN_Phieu_H')
    CREATE INDEX IX_QL_CLS_KQXN_Phieu_H
    ON dbo.QL_CLS_KetQuaXN_CT(IDCSKCB,IDPhieuKetQua,Active,STT);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.QL_CLS_PhieuKetQua_File') AND name=N'IX_QL_CLS_File_Phieu_H')
    CREATE INDEX IX_QL_CLS_File_Phieu_H
    ON dbo.QL_CLS_PhieuKetQua_File(IDCSKCB,IDPhieuKetQua,Active,NgayTaiLen DESC);
GO




/* =====================================================================
 INLINE SOURCE: Doc/Database/01_main_schema_contract.sql
 ===================================================================== */
/*
01_main_schema_contract.sql
Chuan hoa schema canonical ma runtime main su dung.
Legacy migration/drop duoc thuc hien tap trung o 18_main_cleanup_legacy.sql.
*/
USE [QLPM];
GO
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
GO

IF OBJECT_ID(N'dbo.QL_CLS_DM_TriSoXN',N'U') IS NULL
 OR OBJECT_ID(N'dbo.QL_CLS_KetQuaXN_CT',N'U') IS NULL
    THROW 59010,N'Thieu schema CLS V2; khong the chuan hoa contract main.',1;
GO

/* COMMON DM_DonViTinh: tach danh muc don vi tinh thuoc theo HIS HH_DM_DonViTinh. */
IF OBJECT_ID(N'dbo.DM_DonViTinh',N'U') IS NULL
BEGIN
    CREATE TABLE dbo.DM_DonViTinh
    (
        ID BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_DM_DonViTinh PRIMARY KEY,
        IDCSKCB BIGINT NOT NULL,
        MaDVT NVARCHAR(100) NOT NULL,
        TenDVT NVARCHAR(1000) NOT NULL,
        Active BIT NOT NULL CONSTRAINT DF_DM_DonViTinh_Active DEFAULT(1),
        CONSTRAINT UQ_DM_DonViTinh_CSKCB_ID UNIQUE(IDCSKCB,ID),
        CONSTRAINT UQ_DM_DonViTinh_CSKCB_Ma UNIQUE(IDCSKCB,MaDVT),
        CONSTRAINT FK_DM_DonViTinh_CSKCB FOREIGN KEY(IDCSKCB) REFERENCES dbo.DM_CSKCB(ID)
    );
END;
GO

IF COL_LENGTH(N'dbo.DM_Thuoc',N'IDDonViTinh') IS NULL
    ALTER TABLE dbo.DM_Thuoc ADD IDDonViTinh BIGINT NULL;
GO

/* Giu tuong thich data cu: tao DVT legacy tu chuoi DonViTinh roi map FK. */
INSERT dbo.DM_DonViTinh(IDCSKCB,MaDVT,TenDVT,Active)
SELECT DISTINCT
       T.IDCSKCB,
       N'LEGACY_' + CONVERT(VARCHAR(64),HASHBYTES('SHA2_256',
           CONCAT(CONVERT(NVARCHAR(40),T.IDCSKCB),N'|',LOWER(LTRIM(RTRIM(T.DonViTinh))))),2),
       LTRIM(RTRIM(T.DonViTinh)),
       1
FROM dbo.DM_Thuoc T
WHERE NULLIF(LTRIM(RTRIM(T.DonViTinh)),N'') IS NOT NULL
  AND NOT EXISTS
  (
      SELECT 1
      FROM dbo.DM_DonViTinh D
      WHERE D.IDCSKCB=T.IDCSKCB
        AND LOWER(LTRIM(RTRIM(D.TenDVT)))=LOWER(LTRIM(RTRIM(T.DonViTinh)))
  );
GO

UPDATE T
SET T.IDDonViTinh=D.ID
FROM dbo.DM_Thuoc T
INNER JOIN dbo.DM_DonViTinh D
    ON D.IDCSKCB=T.IDCSKCB
   AND LOWER(LTRIM(RTRIM(D.TenDVT)))=LOWER(LTRIM(RTRIM(T.DonViTinh)))
WHERE T.IDDonViTinh IS NULL
  AND NULLIF(LTRIM(RTRIM(T.DonViTinh)),N'') IS NOT NULL;
GO

IF NOT EXISTS
(
    SELECT 1
    FROM sys.foreign_keys
    WHERE parent_object_id=OBJECT_ID(N'dbo.DM_Thuoc')
      AND name=N'FK_DM_Thuoc_DonViTinh'
)
    ALTER TABLE dbo.DM_Thuoc WITH CHECK
        ADD CONSTRAINT FK_DM_Thuoc_DonViTinh
        FOREIGN KEY(IDCSKCB,IDDonViTinh)
        REFERENCES dbo.DM_DonViTinh(IDCSKCB,ID);
GO

/* COMMON DM_DichVu CLS contract:
   0=chua cau hinh, 1=XN form tri so, 2=CLS mo ta/ket luan.
   Loai 3 (CLS tu do) da bo; ket qua cu loai 3 duoc quy ve loai 2 vi cung luu MoTa/KetLuan. */
IF COL_LENGTH(N'dbo.DM_DichVu',N'LoaiKetQua') IS NULL
    ALTER TABLE dbo.DM_DichVu
        ADD LoaiKetQua TINYINT NOT NULL
            CONSTRAINT DF_DM_DichVu_LoaiKetQua_Common DEFAULT(0) WITH VALUES;
IF COL_LENGTH(N'dbo.DM_DichVu',N'IDFormKQ') IS NULL
    ALTER TABLE dbo.DM_DichVu ADD IDFormKQ BIGINT NULL;
GO

UPDATE dbo.DM_DichVu
SET LoaiKetQua=0,IDFormKQ=NULL
WHERE LoaiKetQua=3;
GO

IF OBJECT_ID(N'dbo.QL_CLS_PhieuKetQua',N'U') IS NOT NULL
    UPDATE dbo.QL_CLS_PhieuKetQua SET LoaiKetQua=2 WHERE LoaiKetQua=3;
GO

DECLARE @DFLoaiKetQua SYSNAME;
SELECT @DFLoaiKetQua=DC.name
FROM sys.default_constraints DC
INNER JOIN sys.columns C
  ON C.object_id=DC.parent_object_id AND C.column_id=DC.parent_column_id
WHERE DC.parent_object_id=OBJECT_ID(N'dbo.DM_DichVu') AND C.name=N'LoaiKetQua';
IF @DFLoaiKetQua IS NOT NULL
    EXEC(N'ALTER TABLE dbo.DM_DichVu DROP CONSTRAINT '+QUOTENAME(@DFLoaiKetQua));
ALTER TABLE dbo.DM_DichVu
    ADD CONSTRAINT DF_DM_DichVu_LoaiKetQua_Common DEFAULT(0) FOR LoaiKetQua;
GO

IF OBJECT_ID(N'dbo.CK_DM_DichVu_LoaiKetQua_Main',N'C') IS NULL
    ALTER TABLE dbo.DM_DichVu WITH CHECK
        ADD CONSTRAINT CK_DM_DichVu_LoaiKetQua_Main CHECK(LoaiKetQua IN(0,1,2));
GO

IF COL_LENGTH(N'dbo.QL_CLS_KetQuaXN_CT',N'Trai') IS NULL
    ALTER TABLE dbo.QL_CLS_KetQuaXN_CT ADD Trai NVARCHAR(200) NULL;
IF COL_LENGTH(N'dbo.QL_CLS_KetQuaXN_CT',N'Phai') IS NULL
    ALTER TABLE dbo.QL_CLS_KetQuaXN_CT ADD Phai NVARCHAR(200) NULL;
IF COL_LENGTH(N'dbo.QL_CLS_KetQuaXN_CT',N'CongThuc') IS NULL
    ALTER TABLE dbo.QL_CLS_KetQuaXN_CT ADD CongThuc NVARCHAR(MAX) NULL;
GO

IF EXISTS
(
    SELECT 1
    FROM sys.indexes I
    INNER JOIN sys.index_columns IC
      ON IC.object_id=I.object_id AND IC.index_id=I.index_id
    INNER JOIN sys.columns C
      ON C.object_id=IC.object_id AND C.column_id=IC.column_id
    WHERE I.object_id=OBJECT_ID(N'dbo.QL_CLS_KetQuaXN_CT')
      AND I.name=N'IX_QL_CLS_KQXN_Phieu'
      AND C.name IN(N'Duyet',N'HuyDuyet',N'Active')
)
    DROP INDEX IX_QL_CLS_KQXN_Phieu ON dbo.QL_CLS_KetQuaXN_CT;
GO

IF NOT EXISTS
(
    SELECT 1 FROM sys.indexes
    WHERE object_id=OBJECT_ID(N'dbo.QL_CLS_KetQuaXN_CT')
      AND name=N'IX_QL_CLS_KQXN_Phieu'
)
    CREATE INDEX IX_QL_CLS_KQXN_Phieu
        ON dbo.QL_CLS_KetQuaXN_CT(IDCSKCB,IDPhieuKetQua,STT)
        INCLUDE(IDTriSoXN,GiaTri,GiaTriSo,DanhGia);
GO

CREATE OR ALTER TRIGGER dbo.TR_QL_ChiDinh_CT_BaoVeKetQuaCLS
ON dbo.QL_ChiDinh_CT
AFTER UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS
    (
        SELECT 1
        FROM inserted I
        INNER JOIN deleted D
          ON D.ID=I.ID AND D.IDCSKCB=I.IDCSKCB
        WHERE D.Active=1
          AND I.Active=0
          AND EXISTS
          (
              SELECT 1
              FROM dbo.QL_CLS_PhieuKetQua P
              WHERE P.IDCSKCB=I.IDCSKCB
                AND P.IDChiDinhCT=I.ID
                AND P.Active=1
          )
    )
        THROW 58500,N'Không thể xóa/vô hiệu hóa chỉ định đã có kết quả CLS.',1;
END;
GO

PRINT N'01_main_schema_contract.sql: OK';
GO



