GO
IF COL_LENGTH(N'dbo.DM_NhanVien',N'MaTinh') IS NULL
    ALTER TABLE dbo.DM_NhanVien ADD MaTinh NVARCHAR(20) NULL;
GO
IF COL_LENGTH(N'dbo.DM_NhanVien',N'MaPhuongXa') IS NULL
