USE [QLPM];
GO

/*
14_common_cls_tri_so_import.sql
- QL_CLS_DM_TriSoXN chi giu danh tinh + metadata chuan hoa.
- DVT/range/gioi tinh/tuoi/cong thuc chi nam o QL_CLS_FormKQXN_CT.
- Bo sung metadata LOINC + import Excel danh muc tri so.
- Legacy config duoc migrate/drop o 18_main_cleanup_legacy.sql.
*/

SET NOCOUNT ON;
SET XACT_ABORT ON;
GO

/* =========================================================
   0. TUONG THICH SCHEMA CLS DA TON TAI
   ========================================================= */
IF COL_LENGTH(N'dbo.QL_CLS_DM_TriSoXN',N'Active') IS NULL
    ALTER TABLE dbo.QL_CLS_DM_TriSoXN
        ADD Active BIT NOT NULL CONSTRAINT DF_QL_CLS_TriSo_Active_Compat DEFAULT(1) WITH VALUES;
IF COL_LENGTH(N'dbo.QL_CLS_DM_TriSoXN',N'NgayTao') IS NULL
    ALTER TABLE dbo.QL_CLS_DM_TriSoXN
        ADD NgayTao DATETIME2(0) NOT NULL CONSTRAINT DF_QL_CLS_TriSo_NgayTao_Compat DEFAULT(SYSDATETIME()) WITH VALUES;
IF COL_LENGTH(N'dbo.QL_CLS_DM_TriSoXN',N'NgayCapNhat') IS NULL
    ALTER TABLE dbo.QL_CLS_DM_TriSoXN ADD NgayCapNhat DATETIME2(0) NULL;

IF COL_LENGTH(N'dbo.QL_CLS_FormKQXN_CT',N'Active') IS NULL
    ALTER TABLE dbo.QL_CLS_FormKQXN_CT
        ADD Active BIT NOT NULL CONSTRAINT DF_QL_CLS_FormCT_Active_Compat DEFAULT(1) WITH VALUES;
