/* =========================================================
   3. DANH MUC TRI SO + IMPORT EXCEL
   ========================================================= */
CREATE OR ALTER PROCEDURE dbo.STO_QL_CLS_DM_TriSo_DanhSach
    @IDCSKCB BIGINT,
    @TuKhoa NVARCHAR(200)=NULL,
    @Trang INT=1,
    @KichThuocTrang INT=100
AS
BEGIN
    SET NOCOUNT ON;
    SET @TuKhoa=NULLIF(LTRIM(RTRIM(@TuKhoa)),N'');
    SET @Trang=CASE WHEN @Trang<1 THEN 1 ELSE @Trang END;
    SET @KichThuocTrang=CASE WHEN @KichThuocTrang<10 THEN 10 WHEN @KichThuocTrang>200 THEN 200 ELSE @KichThuocTrang END;

    ;WITH S AS
    (
        SELECT
            T.ID,T.MaTriSo,T.TenTriSo,T.TenVietTat,T.LOINCCode,
            T.LOINCComponent,T.LOINCProperty,T.LOINCTimeAspect,T.LOINCSystem,T.LOINCScale,T.LOINCMethod,
            T.LoaiDuLieu,T.Active,T.NgayTao,T.NgayCapNhat,
            COUNT(*) OVER() TongSoDong
        FROM dbo.QL_CLS_DM_TriSoXN T
        WHERE T.IDCSKCB=@IDCSKCB
          AND
          (
              @TuKhoa IS NULL
              OR T.MaTriSo LIKE N'%'+@TuKhoa+N'%'
              OR T.TenTriSo LIKE N'%'+@TuKhoa+N'%'
              OR T.TenVietTat LIKE N'%'+@TuKhoa+N'%'
              OR T.LOINCCode LIKE N'%'+@TuKhoa+N'%'
          )
    )
    SELECT *
    FROM S
    ORDER BY Active DESC,TenTriSo,ID
    OFFSET (@Trang-1)*@KichThuocTrang ROWS
    FETCH NEXT @KichThuocTrang ROWS ONLY;
END;
GO

CREATE OR ALTER PROCEDURE dbo.STO_QL_CLS_DM_TriSo_Import
    @IDCSKCB BIGINT,
    @DuLieuJson NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @IDCSKCB<=0
    BEGIN
        SELECT 400 Status,N'Thieu co so kham chua benh.' Message,0 SoDong,0 SoThem,0 SoCapNhat,N'[]' LoiJson;
        RETURN;
    END;

    IF ISJSON(ISNULL(@DuLieuJson,N''))<>1
    BEGIN
        SELECT 400 Status,N'Du lieu import khong dung JSON.' Message,0 SoDong,0 SoThem,0 SoCapNhat,N'[]' LoiJson;
        RETURN;
    END;

    DECLARE @D TABLE
    (
        DongExcel INT NOT NULL,
        MaTriSo NVARCHAR(100) NULL,
        TenTriSo NVARCHAR(1000) NULL,
        TenVietTat NVARCHAR(255) NULL,
        LOINCCode NVARCHAR(50) NULL,
        LOINCComponent NVARCHAR(255) NULL,
        LOINCProperty NVARCHAR(255) NULL,
        LOINCTimeAspect NVARCHAR(255) NULL,
        LOINCSystem NVARCHAR(255) NULL,
        LOINCScale NVARCHAR(255) NULL,
        LOINCMethod NVARCHAR(255) NULL,
        LoaiDuLieu NVARCHAR(20) NULL,
        Active BIT NOT NULL,
        LaMoi BIT NULL,
        Loi NVARCHAR(2000) NULL
    );

    INSERT @D
    (
        DongExcel,MaTriSo,TenTriSo,TenVietTat,LOINCCode,LOINCComponent,LOINCProperty,
        LOINCTimeAspect,LOINCSystem,LOINCScale,LOINCMethod,LoaiDuLieu,Active
    )
    SELECT
        ISNULL(J.DongExcel,0),NULLIF(LTRIM(RTRIM(J.MaTriSo)),N''),NULLIF(LTRIM(RTRIM(J.TenTriSo)),N''),
        NULLIF(LTRIM(RTRIM(J.TenVietTat)),N''),NULLIF(LTRIM(RTRIM(J.LOINCCode)),N''),
        NULLIF(LTRIM(RTRIM(J.LOINCComponent)),N''),NULLIF(LTRIM(RTRIM(J.LOINCProperty)),N''),
        NULLIF(LTRIM(RTRIM(J.LOINCTimeAspect)),N''),NULLIF(LTRIM(RTRIM(J.LOINCSystem)),N''),
        NULLIF(LTRIM(RTRIM(J.LOINCScale)),N''),NULLIF(LTRIM(RTRIM(J.LOINCMethod)),N''),
        UPPER(ISNULL(NULLIF(LTRIM(RTRIM(J.LoaiDuLieu)),N''),N'NUMBER')),ISNULL(J.Active,1)
    FROM OPENJSON(@DuLieuJson)
    WITH
    (
        DongExcel INT '$.dong_excel',
        MaTriSo NVARCHAR(100) '$.ma_tri_so',
        TenTriSo NVARCHAR(1000) '$.ten_tri_so',
        TenVietTat NVARCHAR(255) '$.ten_viet_tat',
        LOINCCode NVARCHAR(50) '$.loinc_code',
        LOINCComponent NVARCHAR(255) '$.loinc_component',
        LOINCProperty NVARCHAR(255) '$.loinc_property',
        LOINCTimeAspect NVARCHAR(255) '$.loinc_time_aspect',
        LOINCSystem NVARCHAR(255) '$.loinc_system',
        LOINCScale NVARCHAR(255) '$.loinc_scale',
        LOINCMethod NVARCHAR(255) '$.loinc_method',
        LoaiDuLieu NVARCHAR(20) '$.loai_du_lieu',
        Active BIT '$.active'
    ) J;

    IF NOT EXISTS(SELECT 1 FROM @D)
    BEGIN
        SELECT 400 Status,N'Excel khong co dong tri so de import.' Message,0 SoDong,0 SoThem,0 SoCapNhat,N'[]' LoiJson;
        RETURN;
    END;

    UPDATE D
    SET Loi=NULLIF(CONCAT_WS(N'; ',
        CASE WHEN DongExcel<=1 THEN N'So dong Excel khong hop le' END,
        CASE WHEN MaTriSo IS NULL THEN N'Thieu Ma tri so' END,
        CASE WHEN TenTriSo IS NULL THEN N'Thieu Ten tri so' END,
        CASE WHEN LEN(ISNULL(MaTriSo,N''))>100 THEN N'Ma tri so vuot 100 ky tu' END,
        CASE WHEN LEN(ISNULL(TenTriSo,N''))>1000 THEN N'Ten tri so vuot 1000 ky tu' END,
        CASE WHEN LEN(ISNULL(TenVietTat,N''))>255 THEN N'Ten viet tat vuot 255 ky tu' END,
        CASE WHEN LEN(ISNULL(LOINCCode,N''))>50 THEN N'LOINC vuot 50 ky tu' END,
        CASE WHEN LoaiDuLieu NOT IN(N'NUMBER',N'TEXT',N'CHOICE',N'BOOLEAN') THEN N'Loai du lieu chi nhan NUMBER/TEXT/CHOICE/BOOLEAN' END
    ),N'')
    FROM @D D;

    ;WITH Dup AS
    (
        SELECT MaTriSo FROM @D WHERE MaTriSo IS NOT NULL
        GROUP BY MaTriSo HAVING COUNT(*)>1
    )
    UPDATE D
    SET Loi=CONCAT_WS(N'; ',NULLIF(D.Loi,N''),N'Trung Ma tri so trong file Excel')
    FROM @D D
    INNER JOIN Dup X ON X.MaTriSo=D.MaTriSo;

    UPDATE D
    SET LaMoi=CASE WHEN EXISTS
    (
        SELECT 1 FROM dbo.QL_CLS_DM_TriSoXN T
        WHERE T.IDCSKCB=@IDCSKCB AND T.MaTriSo=D.MaTriSo
    ) THEN 0 ELSE 1 END
    FROM @D D
    WHERE D.MaTriSo IS NOT NULL;

    DECLARE @SoDong INT=(SELECT COUNT(*) FROM @D);
    DECLARE @SoLoi INT=(SELECT COUNT(*) FROM @D WHERE Loi IS NOT NULL);
    DECLARE @SoThem INT=(SELECT COUNT(*) FROM @D WHERE LaMoi=1);
    DECLARE @SoCapNhat INT=(SELECT COUNT(*) FROM @D WHERE LaMoi=0);

    IF @SoLoi>0
    BEGIN
        DECLARE @LoiJson NVARCHAR(MAX)=
        (
            SELECT DongExcel,MaTriSo,TenTriSo,Loi
            FROM @D WHERE Loi IS NOT NULL ORDER BY DongExcel
            FOR JSON PATH
        );
        SELECT 400 Status,
               CONCAT(N'Excel co ',@SoLoi,N' dong loi. Chua import du lieu nao.') Message,
               @SoDong SoDong,0 SoThem,0 SoCapNhat,ISNULL(@LoiJson,N'[]') LoiJson;
        RETURN;
    END;

    BEGIN TRY
        BEGIN TRAN;

        UPDATE T
        SET T.TenTriSo=D.TenTriSo,
            T.TenVietTat=D.TenVietTat,
            T.LOINCCode=D.LOINCCode,
            T.LOINCComponent=D.LOINCComponent,
            T.LOINCProperty=D.LOINCProperty,
            T.LOINCTimeAspect=D.LOINCTimeAspect,
            T.LOINCSystem=D.LOINCSystem,
            T.LOINCScale=D.LOINCScale,
            T.LOINCMethod=D.LOINCMethod,
            T.LoaiDuLieu=D.LoaiDuLieu,
            T.Active=D.Active,
            T.NgayCapNhat=SYSDATETIME()
        FROM dbo.QL_CLS_DM_TriSoXN T
        INNER JOIN @D D ON D.MaTriSo=T.MaTriSo
        WHERE T.IDCSKCB=@IDCSKCB AND D.LaMoi=0;

        INSERT dbo.QL_CLS_DM_TriSoXN
        (
            IDCSKCB,MaTriSo,TenTriSo,TenVietTat,LOINCCode,LOINCComponent,LOINCProperty,
            LOINCTimeAspect,LOINCSystem,LOINCScale,LOINCMethod,LoaiDuLieu,Active
        )
        SELECT
            @IDCSKCB,D.MaTriSo,D.TenTriSo,D.TenVietTat,D.LOINCCode,D.LOINCComponent,D.LOINCProperty,
            D.LOINCTimeAspect,D.LOINCSystem,D.LOINCScale,D.LOINCMethod,D.LoaiDuLieu,D.Active
        FROM @D D
        WHERE D.LaMoi=1;

        COMMIT;

        SELECT 200 Status,
               CONCAT(N'Import danh muc tri so thanh cong: them ',@SoThem,N', cap nhat ',@SoCapNhat,N'.') Message,
               @SoDong SoDong,@SoThem SoThem,@SoCapNhat SoCapNhat,N'[]' LoiJson;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK;
        SELECT 500 Status,ERROR_MESSAGE() Message,@SoDong SoDong,0 SoThem,0 SoCapNhat,N'[]' LoiJson;
    END CATCH;
END;
GO

