INSERT dbo.DM_PhuongXa(ID,IDCSKCB,IDTinhThanh,MaPhuongXa,TenPhuongXa,Active)
SELECT J.id,@IDCSKCB_SEED,J.id_tinh,J.ma,J.ten,1
FROM OPENJSON(@J_Phuong)
WITH(id BIGINT '$.id',ma NVARCHAR(20) '$.ma',ten NVARCHAR(200) '$.ten',id_tinh BIGINT '$.id_tinh') J
WHERE NOT EXISTS(SELECT 1 FROM dbo.DM_PhuongXa X WHERE X.ID=J.id);
SET IDENTITY_INSERT dbo.DM_PhuongXa OFF;

