INSERT dbo.DM_Thuoc
    (ID,IDCSKCB,MaThuoc,TenThuoc,IDDonViTinh,DonViTinh,DuongDung,HamLuong,HoatChat,GiaBan,Active)
SELECT J.id,@IDCSKCB_SEED,J.ma,J.ten,J.id_don_vi_tinh,J.don_vi_tinh,J.duong_dung,J.ham_luong,J.hoat_chat,ISNULL(J.gia_ban,0),1
FROM OPENJSON(@J_Thuoc)
WITH(
    id BIGINT '$.id',ma NVARCHAR(50) '$.ma',ten NVARCHAR(500) '$.ten',
    id_don_vi_tinh BIGINT '$.id_don_vi_tinh',don_vi_tinh NVARCHAR(100) '$.don_vi_tinh',
    duong_dung NVARCHAR(200) '$.duong_dung',ham_luong NVARCHAR(300) '$.ham_luong',
    hoat_chat NVARCHAR(500) '$.hoat_chat',gia_ban DECIMAL(18,2) '$.gia_ban'
) J
WHERE NOT EXISTS(SELECT 1 FROM dbo.DM_Thuoc X WHERE X.ID=J.id);
SET IDENTITY_INSERT dbo.DM_Thuoc OFF;

