/* Kiem tra nhanh so dong seed danh muc. */
DECLARE @IDCSKCB_SEED_CHECK BIGINT=(SELECT TOP(1) ID FROM dbo.DM_CSKCB WHERE MaCSKCB=N'CS001');
SELECT N'DM_TinhThanh' Bang,COUNT(*) SoDong FROM dbo.DM_TinhThanh WHERE IDCSKCB=@IDCSKCB_SEED_CHECK
UNION ALL SELECT N'DM_PhuongXa',COUNT(*) FROM dbo.DM_PhuongXa WHERE IDCSKCB=@IDCSKCB_SEED_CHECK
UNION ALL SELECT N'DM_ICD10',COUNT(*) FROM dbo.DM_ICD10 WHERE IDCSKCB=@IDCSKCB_SEED_CHECK
UNION ALL SELECT N'DM_Thuoc',COUNT(*) FROM dbo.DM_Thuoc WHERE IDCSKCB=@IDCSKCB_SEED_CHECK
UNION ALL SELECT N'DM_DichVu',COUNT(*) FROM dbo.DM_DichVu WHERE IDCSKCB=@IDCSKCB_SEED_CHECK
UNION ALL SELECT N'DM_DonViTinh',COUNT(*) FROM dbo.DM_DonViTinh WHERE IDCSKCB=@IDCSKCB_SEED_CHECK
UNION ALL SELECT N'DM_DanToc',COUNT(*) FROM dbo.DM_DanToc WHERE IDCSKCB=@IDCSKCB_SEED_CHECK
UNION ALL SELECT N'DM_TriSoSinhHieu',COUNT(*) FROM dbo.DM_TriSoSinhHieu WHERE IDCSKCB=@IDCSKCB_SEED_CHECK
UNION ALL SELECT N'DM_NhanVien',COUNT(*) FROM dbo.DM_NhanVien WHERE IDCSKCB=@IDCSKCB_SEED_CHECK;
GO


