/* =====================================================================
 INLINE SOURCE: Doc/Database/18_main_cleanup_legacy.sql
 ===================================================================== */
USE [QLPM];
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
GO

/*
18_main_cleanup_legacy.sql
- Main chi giu schema runtime canonical.
- DSS/AHP se lam lai sau: xoa toan bo object DSS khoi DB main.
- Truoc khi DROP, migrate du lieu legacy con gia tri sang source-of-truth canonical.
*/

IF DB_NAME()<>N'QLPM'
    THROW 59070,N'Script cleanup chi duoc chay tren QLPM.',1;
GO

/* 1. Migrate mapping dich vu -> form cu. */
IF OBJECT_ID(N'dbo.QL_CLS_DichVu_FormKQ',N'U') IS NOT NULL
BEGIN
    UPDATE D
    SET D.LoaiKetQua=CASE WHEN M.LoaiKetQua IN(1,2) THEN M.LoaiKetQua ELSE 0 END,
        D.IDFormKQ=M.IDForm
    FROM dbo.DM_DichVu D
    INNER JOIN dbo.QL_CLS_DichVu_FormKQ M
      ON M.IDCSKCB=D.IDCSKCB AND M.IDDichVu=D.ID
    WHERE M.Active=1;
END;
GO

/* 2. Migrate ICD header cu cua phac do sang bang chi tiet. */
IF OBJECT_ID(N'dbo.DM_PhacDo_ChanDoan',N'U') IS NOT NULL
AND COL_LENGTH(N'dbo.DM_PhacDo',N'IDICD10') IS NOT NULL
BEGIN
    EXEC sys.sp_executesql N'
        INSERT dbo.DM_PhacDo_ChanDoan
        (IDCSKCB,IDPhacDo,IDICD10,BanDau,BenhChinh,BenhKhac,ThuTu,Active)
        SELECT P.IDCSKCB,P.ID,P.IDICD10,
               ISNULL(P.BanDau,0),ISNULL(P.BenhChinh,0),ISNULL(P.BenhKhac,0),1,1
        FROM dbo.DM_PhacDo P
        WHERE P.IDICD10 IS NOT NULL
          AND NOT EXISTS
          (
              SELECT 1
              FROM dbo.DM_PhacDo_ChanDoan C
              WHERE C.IDCSKCB=P.IDCSKCB
                AND C.IDPhacDo=P.ID
                AND C.IDICD10=P.IDICD10
          );';
END;
GO

/* 3. Migrate config tri so master cu sang form detail neu dong form chua co config. */
IF COL_LENGTH(N'dbo.QL_CLS_DM_TriSoXN',N'DonViTinh') IS NOT NULL
AND COL_LENGTH(N'dbo.QL_CLS_DM_TriSoXN',N'DinhLuong') IS NOT NULL
AND COL_LENGTH(N'dbo.QL_CLS_DM_TriSoXN',N'CongThucMoi') IS NOT NULL
BEGIN
    EXEC sys.sp_executesql N'
        UPDATE C
        SET C.TenHienThi=COALESCE(NULLIF(C.TenHienThi,N''''),T.TenTriSo),
            C.DonViTinh=T.DonViTinh,
            C.DinhLuong=T.DinhLuong,
            C.LuongDinhTinh=T.LuongDinhTinh,
            C.TuyetDoi=T.TuyetDoi,
            C.TriSoBinhThuong1=T.TriSoBinhThuong1,
            C.GHMin1=T.GHMin1,
            C.GHMax1=T.GHMax1,
            C.MacDinh1=T.MacDinh1,
            C.TriSoBinhThuong2=T.TriSoBinhThuong2,
            C.GHMin2=T.GHMin2,
            C.GHMax2=T.GHMax2,
            C.MacDinh2=T.MacDinh2,
            C.DonViTinh2=T.DonViTinh2,
            C.TiLeQuyDoi=T.TiLeQuyDoi,
            C.IDGioiTinh=T.IDGioiTinh,
            C.GHTuoi=T.GHTuoi,
            C.TuoiMin=T.TuoiMin,
            C.TuoiMax=T.TuoiMax,
            C.LamTron=T.LamTron,
            C.Nguong=T.Nguong,
            C.Tieude=T.Tieude,
            C.CongThuc=T.CongThuc,
            C.CongThucMoi=T.CongThucMoi
        FROM dbo.QL_CLS_FormKQXN_CT C
        INNER JOIN dbo.QL_CLS_DM_TriSoXN T
          ON T.IDCSKCB=C.IDCSKCB AND T.ID=C.IDTriSoXN
        WHERE C.TenHienThi IS NULL;';
END;
GO

/* LoaiDuLieu la metadata master; suy ra mot lan tu flags cu neu can. */
IF COL_LENGTH(N'dbo.QL_CLS_DM_TriSoXN',N'LoaiDuLieu') IS NOT NULL
AND COL_LENGTH(N'dbo.QL_CLS_DM_TriSoXN',N'DinhLuong') IS NOT NULL
BEGIN
    EXEC sys.sp_executesql N'
        UPDATE dbo.QL_CLS_DM_TriSoXN
        SET LoaiDuLieu=
            CASE
                WHEN ISNULL(DinhLuong,0)=1 OR ISNULL(TuyetDoi,0)=1 THEN N''NUMBER''
                WHEN ISNULL(LuongDinhTinh,0)=1 THEN N''TEXT''
                ELSE LoaiDuLieu
            END
        WHERE LoaiDuLieu IS NULL
           OR LTRIM(RTRIM(LoaiDuLieu))=N''''
           OR (UPPER(LTRIM(RTRIM(LoaiDuLieu)))=N''NUMBER''
               AND ISNULL(DinhLuong,0)=0
               AND ISNULL(TuyetDoi,0)=0
               AND ISNULL(LuongDinhTinh,0)=1);';
END;
GO

BEGIN TRY
    BEGIN TRAN;

    /* Xoa metadata quyen DSS neu tung ton tai. */
    IF OBJECT_ID(N'dbo.HT_Chuc_Nang',N'U') IS NOT NULL
       AND OBJECT_ID(N'dbo.HT_Quyen_Vai_Tro',N'U') IS NOT NULL
    BEGIN
        DELETE Q
        FROM dbo.HT_Quyen_Vai_Tro Q
        INNER JOIN dbo.HT_Chuc_Nang C
          ON C.IDCSKCB=Q.IDCSKCB AND C.ID=Q.ID_Chuc_Nang
        WHERE C.Ma_Chuc_Nang LIKE N'dss[_]%'
           OR C.Duong_Dan LIKE N'/dss%';

        DELETE FROM dbo.HT_Chuc_Nang
        WHERE Ma_Chuc_Nang LIKE N'dss[_]%'
           OR Duong_Dan LIKE N'/dss%';
    END;

    IF OBJECT_ID(N'dbo.HT_Phan_He',N'U') IS NOT NULL
    BEGIN
        DELETE P
        FROM dbo.HT_Phan_He P
        WHERE P.Ma_Phan_He=N'dss'
          AND NOT EXISTS
          (
              SELECT 1 FROM dbo.HT_Chuc_Nang C
              WHERE C.IDCSKCB=P.IDCSKCB AND C.ID_Phan_He=P.ID
          );
    END;

    /* Xoa stored module legacy/DSS. */
    DECLARE @Sql NVARCHAR(MAX)=N'';

    SELECT @Sql += N'DROP PROCEDURE '
        +QUOTENAME(SCHEMA_NAME(schema_id))+N'.'+QUOTENAME(name)+N';'+CHAR(13)+CHAR(10)
    FROM sys.procedures
    WHERE (name LIKE N'STO[_]DSS[_]%' OR name LIKE N'DSS[_]%'
        OR name LIKE N'STO[_]QL[_]KetQuaCLS%'
        OR name LIKE N'STO[_]QL[_]CLS[_]%[_]V2'
        OR name LIKE N'STO[_]QL[_]CLS[_]KetQua[_]Duyet%');

    IF NULLIF(@Sql,N'') IS NOT NULL EXEC sys.sp_executesql @Sql;

    SET @Sql=N'';
    SELECT @Sql += N'DROP VIEW '
        +QUOTENAME(SCHEMA_NAME(schema_id))+N'.'+QUOTENAME(name)+N';'+CHAR(13)+CHAR(10)
    FROM sys.views
    WHERE name LIKE N'DSS[_]%';
    IF NULLIF(@Sql,N'') IS NOT NULL EXEC sys.sp_executesql @Sql;

    SET @Sql=N'';
    SELECT @Sql += N'DROP FUNCTION '
        +QUOTENAME(SCHEMA_NAME(schema_id))+N'.'+QUOTENAME(name)+N';'+CHAR(13)+CHAR(10)
    FROM sys.objects
    WHERE type IN(N'FN',N'IF',N'TF')
      AND (name LIKE N'DSS[_]%' OR name LIKE N'FN[_]DSS[_]%');
    IF NULLIF(@Sql,N'') IS NOT NULL EXEC sys.sp_executesql @Sql;

    SET @Sql=N'';
    SELECT @Sql += N'DROP TRIGGER '
        +QUOTENAME(OBJECT_SCHEMA_NAME(object_id))+N'.'+QUOTENAME(name)+N';'+CHAR(13)+CHAR(10)
    FROM sys.triggers
    WHERE parent_class=1 AND name LIKE N'TR[_]DSS[_]%';
    IF NULLIF(@Sql,N'') IS NOT NULL EXEC sys.sp_executesql @Sql;

    SET @Sql=N'';
    SELECT @Sql += N'DROP SEQUENCE '
        +QUOTENAME(SCHEMA_NAME(schema_id))+N'.'+QUOTENAME(name)+N';'+CHAR(13)+CHAR(10)
    FROM sys.sequences
    WHERE name LIKE N'SEQ[_]DSS[_]%' OR name LIKE N'DSS[_]%';
    IF NULLIF(@Sql,N'') IS NOT NULL EXEC sys.sp_executesql @Sql;

    /* Danh sach bang legacy can xoa. */
    CREATE TABLE #DropTable
    (
        SchemaName SYSNAME NOT NULL,
        TableName SYSNAME NOT NULL,
        PRIMARY KEY(SchemaName,TableName)
    );

    INSERT #DropTable(SchemaName,TableName)
    SELECT SCHEMA_NAME(schema_id),name
    FROM sys.tables
    WHERE SCHEMA_NAME(schema_id)=N'dbo'
      AND name LIKE N'DSS[_]%';

    INSERT #DropTable(SchemaName,TableName)
    SELECT N'dbo',X.TableName
    FROM (VALUES
        (N'QL_CLS_DichVu_FormKQ'),
        (N'QL_KetQuaCLS_File'),
        (N'QL_KetQuaCLS'),
        (N'QL_Thuoc_Di_Ung'),
        (N'sysdiagrams')
    ) X(TableName)
    WHERE OBJECT_ID(N'dbo.'+X.TableName,N'U') IS NOT NULL
      AND NOT EXISTS(SELECT 1 FROM #DropTable D WHERE D.SchemaName=N'dbo' AND D.TableName=X.TableName);

    /* Drop FK vao/ra bang se xoa. */
    SET @Sql=N'';
    SELECT @Sql += N'ALTER TABLE '
        +QUOTENAME(SCHEMA_NAME(T.schema_id))+N'.'+QUOTENAME(T.name)
        +N' DROP CONSTRAINT '+QUOTENAME(FK.name)+N';'+CHAR(13)+CHAR(10)
    FROM sys.foreign_keys FK
    INNER JOIN sys.tables T ON T.object_id=FK.parent_object_id
    WHERE EXISTS
    (
        SELECT 1 FROM #DropTable D
        WHERE OBJECT_ID(QUOTENAME(D.SchemaName)+N'.'+QUOTENAME(D.TableName)) IN(FK.parent_object_id,FK.referenced_object_id)
    );
    IF NULLIF(@Sql,N'') IS NOT NULL EXEC sys.sp_executesql @Sql;

    DECLARE @SchemaName SYSNAME,@TableName SYSNAME,@ColumnName SYSNAME;
    DECLARE CTable CURSOR LOCAL FAST_FORWARD FOR
        SELECT SchemaName,TableName FROM #DropTable;
    OPEN CTable;
    FETCH NEXT FROM CTable INTO @SchemaName,@TableName;
    WHILE @@FETCH_STATUS=0
    BEGIN
        IF OBJECT_ID(QUOTENAME(@SchemaName)+N'.'+QUOTENAME(@TableName),N'U') IS NOT NULL
        BEGIN
            SET @Sql=N'DROP TABLE '+QUOTENAME(@SchemaName)+N'.'+QUOTENAME(@TableName)+N';';
            EXEC sys.sp_executesql @Sql;
        END;
        FETCH NEXT FROM CTable INTO @SchemaName,@TableName;
    END;
    CLOSE CTable;
    DEALLOCATE CTable;

    /* Stored Database Diagram helper objects cung la legacy dev-tool. */
    DROP PROCEDURE IF EXISTS dbo.sp_alterdiagram;
    DROP PROCEDURE IF EXISTS dbo.sp_creatediagram;
    DROP PROCEDURE IF EXISTS dbo.sp_dropdiagram;
    DROP PROCEDURE IF EXISTS dbo.sp_helpdiagramdefinition;
    DROP PROCEDURE IF EXISTS dbo.sp_helpdiagrams;
    DROP PROCEDURE IF EXISTS dbo.sp_renamediagram;
    DROP FUNCTION IF EXISTS dbo.fn_diagramobjects;

    /* Danh sach cot legacy/trung source-of-truth. */
    CREATE TABLE #DropColumn
    (
        SchemaName SYSNAME NOT NULL,
        TableName SYSNAME NOT NULL,
        ColumnName SYSNAME NOT NULL,
        PRIMARY KEY(SchemaName,TableName,ColumnName)
    );

    INSERT #DropColumn VALUES
      (N'dbo',N'DM_NhanVien',N'UserId'),
      (N'dbo',N'DM_PhacDo',N'NoiDung'),
      (N'dbo',N'DM_PhacDo',N'IDICD10'),
      (N'dbo',N'DM_PhacDo',N'BanDau'),
      (N'dbo',N'DM_PhacDo',N'BenhChinh'),
      (N'dbo',N'DM_PhacDo',N'BenhKhac'),
      (N'dbo',N'QL_BenhNhan',N'Tuoi'),
      (N'dbo',N'QL_ChiDinh_CT',N'NgayGioThucHien'),
      (N'dbo',N'QL_ChiDinh_CT',N'NgayGioKetQua'),
      (N'dbo',N'QL_ChiDinh_CT',N'IDNhanVienThucHien'),
      (N'dbo',N'QL_ChiDinh_CT',N'IDBacSiThucHien'),
      (N'dbo',N'QL_ChiDinh_CT',N'IDPhieuKetQua'),
      (N'dbo',N'QL_CLS_FormKQXN',N'STT'),
      (N'dbo',N'QL_CLS_PhieuKetQua',N'Duyet'),
      (N'dbo',N'QL_CLS_PhieuKetQua',N'IDNhanVienDuyet'),
      (N'dbo',N'QL_CLS_PhieuKetQua',N'NgayGioDuyet'),
      (N'dbo',N'QL_CLS_PhieuKetQua',N'NgayGioHuyDuyet'),
      (N'dbo',N'QL_CLS_PhieuKetQua',N'IDNhanVienHuyDuyet'),
      (N'dbo',N'QL_CLS_PhieuKetQua',N'IDVaoVien'),
      (N'dbo',N'QL_CLS_PhieuKetQua',N'IDDichVu'),
      (N'dbo',N'QL_CLS_KetQuaXN_CT',N'Active'),
      (N'dbo',N'QL_CLS_KetQuaXN_CT',N'Duyet'),
      (N'dbo',N'QL_CLS_KetQuaXN_CT',N'IDNhanVienDuyet'),
      (N'dbo',N'QL_CLS_KetQuaXN_CT',N'NgayGioDuyet'),
      (N'dbo',N'QL_CLS_KetQuaXN_CT',N'HuyDuyet'),
      (N'dbo',N'QL_CLS_KetQuaXN_CT',N'IDNhanVienHuy'),
      (N'dbo',N'QL_CLS_KetQuaXN_CT',N'NgayGioHuyDuyet'),
      (N'dbo',N'QL_CLS_DM_TriSoXN',N'DonViTinh'),
      (N'dbo',N'QL_CLS_DM_TriSoXN',N'DinhLuong'),
      (N'dbo',N'QL_CLS_DM_TriSoXN',N'TriSoBinhThuong1'),
      (N'dbo',N'QL_CLS_DM_TriSoXN',N'GHMin1'),
      (N'dbo',N'QL_CLS_DM_TriSoXN',N'GHMax1'),
      (N'dbo',N'QL_CLS_DM_TriSoXN',N'MacDinh1'),
      (N'dbo',N'QL_CLS_DM_TriSoXN',N'TriSoBinhThuong2'),
      (N'dbo',N'QL_CLS_DM_TriSoXN',N'GHMin2'),
      (N'dbo',N'QL_CLS_DM_TriSoXN',N'GHMax2'),
      (N'dbo',N'QL_CLS_DM_TriSoXN',N'MacDinh2'),
      (N'dbo',N'QL_CLS_DM_TriSoXN',N'IDGioiTinh'),
      (N'dbo',N'QL_CLS_DM_TriSoXN',N'TuoiMin'),
      (N'dbo',N'QL_CLS_DM_TriSoXN',N'TuoiMax'),
      (N'dbo',N'QL_CLS_DM_TriSoXN',N'LamTron'),
      (N'dbo',N'QL_CLS_DM_TriSoXN',N'ThuTu'),
      (N'dbo',N'QL_CLS_DM_TriSoXN',N'LuongDinhTinh'),
      (N'dbo',N'QL_CLS_DM_TriSoXN',N'TuyetDoi'),
      (N'dbo',N'QL_CLS_DM_TriSoXN',N'DonViTinh2'),
      (N'dbo',N'QL_CLS_DM_TriSoXN',N'TiLeQuyDoi'),
      (N'dbo',N'QL_CLS_DM_TriSoXN',N'GHTuoi'),
      (N'dbo',N'QL_CLS_DM_TriSoXN',N'Nguong'),
      (N'dbo',N'QL_CLS_DM_TriSoXN',N'Tieude'),
      (N'dbo',N'QL_CLS_DM_TriSoXN',N'CongThuc'),
      (N'dbo',N'QL_CLS_DM_TriSoXN',N'CongThucMoi');

    DECLARE CCol CURSOR LOCAL FAST_FORWARD FOR
        SELECT SchemaName,TableName,ColumnName FROM #DropColumn;
    OPEN CCol;
    FETCH NEXT FROM CCol INTO @SchemaName,@TableName,@ColumnName;
    WHILE @@FETCH_STATUS=0
    BEGIN
        DECLARE @ObjectID INT=OBJECT_ID(QUOTENAME(@SchemaName)+N'.'+QUOTENAME(@TableName),N'U');
        DECLARE @ColumnID INT=NULL;
        IF @ObjectID IS NOT NULL
            SELECT @ColumnID=column_id FROM sys.columns WHERE object_id=@ObjectID AND name=@ColumnName;

        IF @ColumnID IS NOT NULL
        BEGIN
            /* FK */
            SET @Sql=N'';
            SELECT @Sql += N'ALTER TABLE '+QUOTENAME(SCHEMA_NAME(T.schema_id))+N'.'+QUOTENAME(T.name)
                +N' DROP CONSTRAINT '+QUOTENAME(FK.name)+N';'+CHAR(13)+CHAR(10)
            FROM sys.foreign_keys FK
            INNER JOIN sys.foreign_key_columns FKC ON FKC.constraint_object_id=FK.object_id
            INNER JOIN sys.tables T ON T.object_id=FK.parent_object_id
            WHERE (FKC.parent_object_id=@ObjectID AND FKC.parent_column_id=@ColumnID)
               OR (FKC.referenced_object_id=@ObjectID AND FKC.referenced_column_id=@ColumnID);
            IF NULLIF(@Sql,N'') IS NOT NULL EXEC sys.sp_executesql @Sql;

            /* DEFAULT */
            SET @Sql=N'';
            SELECT @Sql += N'ALTER TABLE '+QUOTENAME(@SchemaName)+N'.'+QUOTENAME(@TableName)
                +N' DROP CONSTRAINT '+QUOTENAME(name)+N';'
            FROM sys.default_constraints
            WHERE parent_object_id=@ObjectID AND parent_column_id=@ColumnID;
            IF NULLIF(@Sql,N'') IS NOT NULL EXEC sys.sp_executesql @Sql;

            /* CHECK constraint co dependency cot. */
            SET @Sql=N'';
            SELECT DISTINCT @Sql += N'ALTER TABLE '+QUOTENAME(@SchemaName)+N'.'+QUOTENAME(@TableName)
                +N' DROP CONSTRAINT '+QUOTENAME(CC.name)+N';'
            FROM sys.check_constraints CC
            LEFT JOIN sys.sql_expression_dependencies D ON D.referencing_id=CC.object_id
            WHERE CC.parent_object_id=@ObjectID
              AND (D.referenced_id=@ObjectID AND D.referenced_minor_id=@ColumnID
                   OR CC.definition LIKE N'%'+QUOTENAME(@ColumnName)+N'%');
            IF NULLIF(@Sql,N'') IS NOT NULL EXEC sys.sp_executesql @Sql;

            /* UNIQUE/key constraint neu co. */
            SET @Sql=N'';
            SELECT DISTINCT @Sql += N'ALTER TABLE '+QUOTENAME(@SchemaName)+N'.'+QUOTENAME(@TableName)
                +N' DROP CONSTRAINT '+QUOTENAME(KC.name)+N';'
            FROM sys.key_constraints KC
            INNER JOIN sys.index_columns IC
              ON IC.object_id=KC.parent_object_id AND IC.index_id=KC.unique_index_id
            WHERE KC.parent_object_id=@ObjectID AND IC.column_id=@ColumnID;
            IF NULLIF(@Sql,N'') IS NOT NULL EXEC sys.sp_executesql @Sql;

            /* Index con lai. */
            SET @Sql=N'';
            SELECT DISTINCT @Sql += N'DROP INDEX '+QUOTENAME(I.name)+N' ON '
                +QUOTENAME(@SchemaName)+N'.'+QUOTENAME(@TableName)+N';'
            FROM sys.indexes I
            INNER JOIN sys.index_columns IC
              ON IC.object_id=I.object_id AND IC.index_id=I.index_id
            WHERE I.object_id=@ObjectID AND IC.column_id=@ColumnID
              AND I.name IS NOT NULL AND I.is_primary_key=0 AND I.is_unique_constraint=0;
            IF NULLIF(@Sql,N'') IS NOT NULL EXEC sys.sp_executesql @Sql;

            /* Standalone statistics (manual/auto). Index-backed stats da duoc xu ly o tren. */
            SET @Sql=N'';
            SELECT DISTINCT @Sql += N'DROP STATISTICS '+QUOTENAME(@SchemaName)+N'.'+QUOTENAME(@TableName)+N'.'+QUOTENAME(S.name)+N';'
            FROM sys.stats S
            INNER JOIN sys.stats_columns SC
              ON SC.object_id=S.object_id AND SC.stats_id=S.stats_id
            LEFT JOIN sys.indexes I
              ON I.object_id=S.object_id AND I.index_id=S.stats_id
            WHERE S.object_id=@ObjectID
              AND SC.column_id=@ColumnID
              AND I.index_id IS NULL;
            IF NULLIF(@Sql,N'') IS NOT NULL EXEC sys.sp_executesql @Sql;

            SET @Sql=N'ALTER TABLE '+QUOTENAME(@SchemaName)+N'.'+QUOTENAME(@TableName)
                +N' DROP COLUMN '+QUOTENAME(@ColumnName)+N';';
            EXEC sys.sp_executesql @Sql;
        END;

        FETCH NEXT FROM CCol INTO @SchemaName,@TableName,@ColumnName;
    END;
    CLOSE CCol;
    DEALLOCATE CCol;

    COMMIT;
END TRY
BEGIN CATCH
    IF XACT_STATE()<>0 ROLLBACK;
    THROW;
END CATCH;
GO

PRINT N'18_main_cleanup_legacy.sql: OK - main chi con schema canonical.';
GO



/* =====================================================================
 INLINE SOURCE: Doc/Database/20_REBUILD_ALL_STO_MAIN.sql
 ===================================================================== */
:ON ERROR EXIT

/*
=====================================================================
QLPM MAIN - REBUILD TOAN BO STO
Tao: 2026-09-22

MUC DICH
- DROP toan bo stored procedure dbo.STO_% hien co trong database QLPM.
- Tao lai STO runtime cua nhanh main tu mot contract duy nhat.
- KHONG DROP TABLE, KHONG XOA DU LIEU, KHONG DROP TRIGGER/FUNCTION.
- Sinh hieu chi luu trong luong Kham.
- Trang thai Da kham: co toa thuoc HOAC bac si bam Kham xong.
- CLS chi ghi/sua ket qua; KHONG co nghiep vu duyet/huy duyet.
- Cau hinh range/DonViTinh/gioi/tuoi/cong thuc CLS lay tu QL_CLS_FormKQXN_CT.
- Gia dich vu/thuoc trong nghiep vu lay tu danh muc server, khong tin DonGia client.
- Chay script nay tren DB main da qua updater v70. Main khong con DSS/legacy schema.

LUU Y
- Day la file destructive doi voi STO, nen nen backup/script-out STO cu neu can doi chieu.
=====================================================================
*/
USE [QLPM];
GO
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
GO

IF DB_NAME()<>N'QLPM'
    THROW 59000,N'Script chi duoc phep chay tren database QLPM.',1;
GO

DECLARE @Thieu NVARCHAR(MAX)=N'';
IF OBJECT_ID(N'dbo.DM_CSKCB',N'U') IS NULL SET @Thieu+=N'DM_CSKCB; ';
IF OBJECT_ID(N'dbo.DM_NhanVien',N'U') IS NULL SET @Thieu+=N'DM_NhanVien; ';
IF COL_LENGTH(N'dbo.HT_Tai_Khoan',N'LaQuanTriHeThong') IS NULL SET @Thieu+=N'HT_Tai_Khoan.LaQuanTriHeThong (hay chay 00_CapNhat_TatCa.sql v76 truoc); ';
IF OBJECT_ID(N'dbo.QL_BenhNhan',N'U') IS NULL SET @Thieu+=N'QL_BenhNhan; ';
IF OBJECT_ID(N'dbo.QL_VaoVien',N'U') IS NULL SET @Thieu+=N'QL_VaoVien; ';
IF OBJECT_ID(N'dbo.QL_ChiDinh_CT',N'U') IS NULL SET @Thieu+=N'QL_ChiDinh_CT; ';
IF OBJECT_ID(N'dbo.QL_CLS_PhieuKetQua',N'U') IS NULL SET @Thieu+=N'QL_CLS_PhieuKetQua; ';
IF OBJECT_ID(N'dbo.QL_CLS_FormKQXN_CT',N'U') IS NULL SET @Thieu+=N'QL_CLS_FormKQXN_CT; ';
IF @Thieu<>N'' THROW 59001,N'Thieu schema bat buoc. Hay cap nhat schema truoc khi rebuild STO.',1;
GO

BEGIN TRANSACTION;
GO

PRINT N'===== DROP TOAN BO dbo.STO_% =====';
DECLARE @Drop NVARCHAR(MAX)=N'';
SELECT @Drop+=N'DROP PROCEDURE '+QUOTENAME(SCHEMA_NAME(P.schema_id))+N'.'+QUOTENAME(P.name)+N';'+CHAR(13)+CHAR(10)
FROM sys.procedures P
WHERE SCHEMA_NAME(P.schema_id)=N'dbo'
  AND P.name LIKE N'STO[_]%'
ORDER BY P.name;
IF NULLIF(@Drop,N'') IS NOT NULL EXEC sys.sp_executesql @Drop;
PRINT N'===== DROP STO HOAN TAT =====';
GO


/* ==================== STO_HT_CSKCB_Danh_Sach ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_HT_CSKCB_Danh_Sach
    @TuKhoa NVARCHAR(200)=NULL,
    @MaCSKCB NVARCHAR(20)=NULL,
    @TenCSKCB NVARCHAR(300)=NULL,
    @MaTinh NVARCHAR(20)=NULL,
    @MaPhuongXa NVARCHAR(20)=NULL,
    @Active BIT=NULL,
    @Trang INT=1,
    @KichThuocTrang INT=25
AS
BEGIN
    SET NOCOUNT ON;
    SET @TuKhoa=NULLIF(LTRIM(RTRIM(@TuKhoa)),N'');
    SET @MaCSKCB=NULLIF(LTRIM(RTRIM(@MaCSKCB)),N'');
    SET @TenCSKCB=NULLIF(LTRIM(RTRIM(@TenCSKCB)),N'');
    SET @MaTinh=NULLIF(LTRIM(RTRIM(@MaTinh)),N'');
    SET @MaPhuongXa=NULLIF(LTRIM(RTRIM(@MaPhuongXa)),N'');
    SET @Trang=CASE WHEN @Trang<1 THEN 1 ELSE @Trang END;
    SET @KichThuocTrang=CASE WHEN @KichThuocTrang<10 THEN 10 WHEN @KichThuocTrang>100 THEN 100 ELSE @KichThuocTrang END;

    ;WITH D AS
    (
        SELECT
            C.ID AS IDCSKCB,
            C.MaCSKCB,
            C.TenCSKCB,
            C.SoNhaTenDuong,
            C.DiaChi,
            C.MaTinh,
            C.MaPhuongXa,
            C.SDT,
            C.Email,
            C.MaST,
            C.SoTK,
            C.IDNganHang,
            NH.MaNganHang,
            NH.TenNganHang,
            C.UrlLogo,
            C.Active
        FROM dbo.DM_CSKCB C
        LEFT JOIN dbo.DM_NganHang NH ON NH.ID=C.IDNganHang
        WHERE (@Active IS NULL OR C.Active=@Active)
          AND (@MaCSKCB IS NULL OR C.MaCSKCB LIKE N'%'+@MaCSKCB+N'%')
          AND (@TenCSKCB IS NULL OR C.TenCSKCB LIKE N'%'+@TenCSKCB+N'%')
          AND (@MaTinh IS NULL OR C.MaTinh=@MaTinh)
          AND (@MaPhuongXa IS NULL OR C.MaPhuongXa=@MaPhuongXa)
          AND
          (
               @TuKhoa IS NULL
               OR C.MaCSKCB LIKE N'%'+@TuKhoa+N'%'
               OR C.TenCSKCB LIKE N'%'+@TuKhoa+N'%'
               OR C.SoNhaTenDuong LIKE N'%'+@TuKhoa+N'%'
               OR C.DiaChi LIKE N'%'+@TuKhoa+N'%'
               OR C.SDT LIKE N'%'+@TuKhoa+N'%'
               OR C.Email LIKE N'%'+@TuKhoa+N'%'
               OR C.MaST LIKE N'%'+@TuKhoa+N'%'
               OR C.SoTK LIKE N'%'+@TuKhoa+N'%'
               OR NH.MaNganHang LIKE N'%'+@TuKhoa+N'%'
               OR NH.TenNganHang LIKE N'%'+@TuKhoa+N'%'
          )
    )
    SELECT D.*,COUNT(*) OVER() AS TongSoDong
    FROM D
    ORDER BY D.Active DESC,D.TenCSKCB,D.IDCSKCB
    OFFSET (@Trang-1)*@KichThuocTrang ROWS
    FETCH NEXT @KichThuocTrang ROWS ONLY;
END;
GO

/* ==================== STO_HT_CSKCB_Luu ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_HT_CSKCB_Luu
    @IDCSKCB BIGINT=NULL,
    @MaCSKCB NVARCHAR(20),
    @TenCSKCB NVARCHAR(300),
    @SoNhaTenDuong NVARCHAR(300)=NULL,
    @MaTinh NVARCHAR(20)=NULL,
    @MaPhuongXa NVARCHAR(20)=NULL,
    @SDT NVARCHAR(100)=NULL,
    @Email NVARCHAR(200)=NULL,
    @MaST NVARCHAR(50)=NULL,
    @SoTK NVARCHAR(100)=NULL,
    @IDNganHang BIGINT=NULL,
    @UrlLogo NVARCHAR(1000)=NULL,
    @Active BIT=1
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    SET @MaCSKCB=NULLIF(LTRIM(RTRIM(@MaCSKCB)),N'');
    SET @TenCSKCB=NULLIF(LTRIM(RTRIM(@TenCSKCB)),N'');
    SET @SoNhaTenDuong=NULLIF(LTRIM(RTRIM(@SoNhaTenDuong)),N'');
    SET @MaTinh=NULLIF(LTRIM(RTRIM(@MaTinh)),N'');
    SET @MaPhuongXa=NULLIF(LTRIM(RTRIM(@MaPhuongXa)),N'');
    SET @SDT=NULLIF(LTRIM(RTRIM(@SDT)),N'');

    IF @SDT IS NOT NULL AND (LEN(@SDT)>10 OR @SDT LIKE N'%[^0-9]%')
    BEGIN
        SELECT 400 AS Status,N'Số điện thoại chỉ được nhập số và tối đa 10 ký tự.' AS Message,@IDCSKCB AS IDCSKCB;
        RETURN;
    END;

    SET @Email=NULLIF(LTRIM(RTRIM(@Email)),N'');
    SET @MaST=NULLIF(LTRIM(RTRIM(@MaST)),N'');
    SET @SoTK=NULLIF(LTRIM(RTRIM(@SoTK)),N'');
    SET @UrlLogo=NULLIF(LTRIM(RTRIM(@UrlLogo)),N'');

    IF @MaCSKCB IS NULL OR @TenCSKCB IS NULL
    BEGIN
        SELECT 400 AS Status,N'Mã CSKCB và tên CSKCB là bắt buộc.' AS Message,@IDCSKCB AS IDCSKCB;
        RETURN;
    END;

    IF @IDNganHang IS NOT NULL
       AND NOT EXISTS(SELECT 1 FROM dbo.DM_NganHang WHERE ID=@IDNganHang)
    BEGIN
        SELECT 400 AS Status,N'Ngân hàng không tồn tại.' AS Message,@IDCSKCB AS IDCSKCB;
        RETURN;
    END;

    IF EXISTS
    (
        SELECT 1
        FROM dbo.DM_CSKCB
        WHERE MaCSKCB=@MaCSKCB
          AND (@IDCSKCB IS NULL OR ID<>@IDCSKCB)
    )
    BEGIN
        SELECT 409 AS Status,N'Mã CSKCB đã tồn tại.' AS Message,@IDCSKCB AS IDCSKCB;
        RETURN;
    END;

    DECLARE @TenTinh NVARCHAR(200)=NULL,
            @TenPhuongXa NVARCHAR(200)=NULL,
            @DiaChi NVARCHAR(500)=NULL;

    IF @MaTinh IS NOT NULL
        SELECT TOP(1) @TenTinh=T.TenTinh
        FROM dbo.DM_TinhThanh T
        WHERE T.Active=1 AND T.MaTinh=@MaTinh
        ORDER BY T.ID;

    IF @MaPhuongXa IS NOT NULL
        SELECT TOP(1) @TenPhuongXa=P.TenPhuongXa
        FROM dbo.DM_PhuongXa P
        LEFT JOIN dbo.DM_TinhThanh T
          ON T.IDCSKCB=P.IDCSKCB AND T.ID=P.IDTinhThanh
        WHERE P.Active=1
          AND P.MaPhuongXa=@MaPhuongXa
          AND (@MaTinh IS NULL OR T.MaTinh=@MaTinh)
        ORDER BY P.ID;

    SET @DiaChi=NULLIF(CONCAT_WS(N', ',@SoNhaTenDuong,@TenPhuongXa,@TenTinh),N'');

    BEGIN TRY
        BEGIN TRAN;

        IF ISNULL(@IDCSKCB,0)=0
        BEGIN
            INSERT dbo.DM_CSKCB
            (
                MaCSKCB,TenCSKCB,SoNhaTenDuong,DiaChi,MaTinh,MaPhuongXa,SDT,Email,MaST,SoTK,IDNganHang,UrlLogo,Active
            )
            VALUES
            (
                @MaCSKCB,@TenCSKCB,@SoNhaTenDuong,@DiaChi,@MaTinh,@MaPhuongXa,@SDT,@Email,@MaST,@SoTK,@IDNganHang,@UrlLogo,ISNULL(@Active,1)
            );

            SET @IDCSKCB=SCOPE_IDENTITY();
        END
        ELSE
        BEGIN
            IF NOT EXISTS(SELECT 1 FROM dbo.DM_CSKCB WHERE ID=@IDCSKCB)
            BEGIN
                ROLLBACK;
                SELECT 404 AS Status,N'Không tìm thấy CSKCB.' AS Message,@IDCSKCB AS IDCSKCB;
                RETURN;
            END;

            UPDATE dbo.DM_CSKCB
            SET MaCSKCB=@MaCSKCB,
                TenCSKCB=@TenCSKCB,
                SoNhaTenDuong=@SoNhaTenDuong,
                DiaChi=@DiaChi,
                MaTinh=@MaTinh,
                MaPhuongXa=@MaPhuongXa,
                SDT=@SDT,
                Email=@Email,
                MaST=@MaST,
                SoTK=@SoTK,
                IDNganHang=@IDNganHang,
                UrlLogo=@UrlLogo,
                Active=ISNULL(@Active,1)
            WHERE ID=@IDCSKCB;
        END;

        COMMIT;
        SELECT 200 AS Status,N'Lưu CSKCB thành công.' AS Message,@IDCSKCB AS IDCSKCB;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT>0 ROLLBACK;
        SELECT 500 AS Status,ERROR_MESSAGE() AS Message,@IDCSKCB AS IDCSKCB;
    END CATCH;
END;
GO

/* ==================== STO_HT_CSKCB_Xoa ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_HT_CSKCB_Xoa
    @IDCSKCB BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF NOT EXISTS(SELECT 1 FROM dbo.DM_CSKCB WHERE ID=@IDCSKCB)
    BEGIN
        SELECT 404 AS Status,N'Không tìm thấy CSKCB.' AS Message;
        RETURN;
    END;

    BEGIN TRY
        BEGIN TRAN;

        DECLARE @AppLockResult INT;
        DECLARE @AppLockResource NVARCHAR(255)=N'QLPM_HARD_DELETE_CSKCB_'+CONVERT(NVARCHAR(30),@IDCSKCB);

        EXEC @AppLockResult=sys.sp_getapplock
            @Resource=@AppLockResource,
            @LockMode=N'Exclusive',
            @LockOwner=N'Transaction',
            @LockTimeout=10000;
        IF @AppLockResult<0
            THROW 51000,N'Không lấy được khóa xóa CSKCB. Hãy thử lại.',1;

        CREATE TABLE #TenantTables
        (
            ObjectID INT NOT NULL PRIMARY KEY,
            SchemaName SYSNAME NOT NULL,
            TableName SYSNAME NOT NULL
        );

        INSERT #TenantTables(ObjectID,SchemaName,TableName)
        SELECT T.object_id,S.name,T.name
        FROM sys.tables T
        INNER JOIN sys.schemas S ON S.schema_id=T.schema_id
        WHERE T.is_ms_shipped=0
          AND EXISTS
          (
              SELECT 1 FROM sys.columns C
              WHERE C.object_id=T.object_id AND C.name=N'IDCSKCB'
          );

        CREATE TABLE #FkTamTat
        (
            ParentObjectID INT NOT NULL,
            SchemaName SYSNAME NOT NULL,
            TableName SYSNAME NOT NULL,
            FKName SYSNAME NOT NULL,
            PRIMARY KEY(ParentObjectID,FKName)
        );

        INSERT #FkTamTat(ParentObjectID,SchemaName,TableName,FKName)
        SELECT DISTINCT FK.parent_object_id,S.name,T.name,FK.name
        FROM sys.foreign_keys FK
        INNER JOIN sys.tables T ON T.object_id=FK.parent_object_id
        INNER JOIN sys.schemas S ON S.schema_id=T.schema_id
        WHERE FK.is_disabled=0
          AND
          (
              EXISTS(SELECT 1 FROM #TenantTables X WHERE X.ObjectID=FK.parent_object_id)
              OR EXISTS(SELECT 1 FROM #TenantTables X WHERE X.ObjectID=FK.referenced_object_id)
              OR FK.referenced_object_id=OBJECT_ID(N'dbo.DM_CSKCB')
          );

        DECLARE @Schema SYSNAME,@Table SYSNAME,@FK SYSNAME,@Sql NVARCHAR(MAX);

        DECLARE fk_off CURSOR LOCAL FAST_FORWARD FOR
            SELECT SchemaName,TableName,FKName FROM #FkTamTat ORDER BY SchemaName,TableName,FKName;
        OPEN fk_off;
        FETCH NEXT FROM fk_off INTO @Schema,@Table,@FK;
        WHILE @@FETCH_STATUS=0
        BEGIN
            SET @Sql=N'ALTER TABLE '+QUOTENAME(@Schema)+N'.'+QUOTENAME(@Table)
                +N' NOCHECK CONSTRAINT '+QUOTENAME(@FK)+N';';
            EXEC sys.sp_executesql @Sql;
            FETCH NEXT FROM fk_off INTO @Schema,@Table,@FK;
        END;
        CLOSE fk_off;
        DEALLOCATE fk_off;

        DECLARE table_delete CURSOR LOCAL FAST_FORWARD FOR
            SELECT SchemaName,TableName FROM #TenantTables ORDER BY SchemaName,TableName;
        OPEN table_delete;
        FETCH NEXT FROM table_delete INTO @Schema,@Table;
        WHILE @@FETCH_STATUS=0
        BEGIN
            SET @Sql=N'DELETE FROM '+QUOTENAME(@Schema)+N'.'+QUOTENAME(@Table)
                +N' WHERE [IDCSKCB]=@IDCSKCB;';
            EXEC sys.sp_executesql @Sql,N'@IDCSKCB BIGINT',@IDCSKCB;
            FETCH NEXT FROM table_delete INTO @Schema,@Table;
        END;
        CLOSE table_delete;
        DEALLOCATE table_delete;

        DELETE dbo.DM_CSKCB WHERE ID=@IDCSKCB;

        DECLARE fk_on CURSOR LOCAL FAST_FORWARD FOR
            SELECT SchemaName,TableName,FKName FROM #FkTamTat ORDER BY SchemaName,TableName,FKName;
        OPEN fk_on;
        FETCH NEXT FROM fk_on INTO @Schema,@Table,@FK;
        WHILE @@FETCH_STATUS=0
        BEGIN
            SET @Sql=N'ALTER TABLE '+QUOTENAME(@Schema)+N'.'+QUOTENAME(@Table)
                +N' WITH CHECK CHECK CONSTRAINT '+QUOTENAME(@FK)+N';';
            EXEC sys.sp_executesql @Sql;
            FETCH NEXT FROM fk_on INTO @Schema,@Table,@FK;
        END;
        CLOSE fk_on;
        DEALLOCATE fk_on;

        COMMIT;
        SELECT 200 AS Status,N'Đã xóa hoàn toàn CSKCB và toàn bộ dữ liệu trong database.' AS Message;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK;
        SELECT 500 AS Status,ERROR_MESSAGE() AS Message;
    END CATCH
END;
GO

/* ==================== STO_HT_Dang_Nhap_Lay_Tai_Khoan ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_HT_Dang_Nhap_Lay_Tai_Khoan
    @Ten_Dang_Nhap NVARCHAR(150)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT TOP(1)
        T.ID AS ID_Tai_Khoan,
        T.IDCSKCB,
        T.IDNhanVien,
        T.Ten_Dang_Nhap,
        T.Mat_Khau_Hash,
        T.Bat_Buoc_Doi_Mat_Khau,
        T.So_Lan_Dang_Nhap_Sai,
        T.Khoa_Den_Luc,
        T.Lan_Dang_Nhap_Cuoi,
        T.Active AS Tai_Khoan_Active,
        T.LaQuanTriHeThong,
        CASE WHEN T.LaQuanTriHeThong=1 THEN T.Ten_Dang_Nhap ELSE N.HoTen END AS HoTen,
        CASE WHEN T.LaQuanTriHeThong=1 THEN N'ADMIN' ELSE N.MaNhanVien END AS MaNhanVien,
        CASE WHEN T.LaQuanTriHeThong=1 THEN CAST(0 AS BIT) ELSE ISNULL(N.LaBacSi,0) END AS LaBacSi,
        CASE WHEN T.LaQuanTriHeThong=1 THEN N'Quản trị hệ thống' ELSE N.ChucDanh END AS ChucDanh,
        CASE WHEN T.LaQuanTriHeThong=1 THEN CAST(1 AS BIT) ELSE ISNULL(N.Active,0) END AS Nhan_Vien_Active,
        CASE WHEN T.LaQuanTriHeThong=1 THEN NULL ELSE C.TenCSKCB END AS TenCSKCB,
        CASE WHEN T.LaQuanTriHeThong=1 THEN CAST(1 AS BIT) ELSE ISNULL(C.Active,0) END AS CSKCB_Active
    FROM dbo.HT_Tai_Khoan T
    LEFT JOIN dbo.DM_NhanVien N
        ON T.LaQuanTriHeThong=0
       AND N.IDCSKCB=T.IDCSKCB
       AND N.ID=T.IDNhanVien
    LEFT JOIN dbo.DM_CSKCB C
        ON T.LaQuanTriHeThong=0
       AND C.ID=T.IDCSKCB
    WHERE LOWER(T.Ten_Dang_Nhap)=LOWER(LTRIM(RTRIM(@Ten_Dang_Nhap)));
END;
GO

/* ==================== STO_HT_Doi_Mat_Khau ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_HT_Doi_Mat_Khau
    @ID_Tai_Khoan BIGINT,
    @Mat_Khau_Hash NVARCHAR(1000)
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE dbo.HT_Tai_Khoan
    SET Mat_Khau_Hash=@Mat_Khau_Hash,
        Bat_Buoc_Doi_Mat_Khau=0,
        Ngay_Cap_Nhat=SYSDATETIME()
    WHERE ID=@ID_Tai_Khoan AND Active=1;

    IF @@ROWCOUNT=0 SELECT 404 AS Status, N'Không tìm thấy tài khoản đang hoạt động.' AS Message;
    ELSE SELECT 200 AS Status, N'Đổi mật khẩu thành công.' AS Message;
END;
GO

/* ==================== STO_HT_Khoi_Tao_Quan_Tri ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_HT_Khoi_Tao_Quan_Tri
    @Ten_Dang_Nhap NVARCHAR(150),
    @Mat_Khau_Hash NVARCHAR(1000)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRAN;

        SET @Ten_Dang_Nhap=NULLIF(LTRIM(RTRIM(@Ten_Dang_Nhap)),N'');
        IF @Ten_Dang_Nhap IS NULL OR NULLIF(@Mat_Khau_Hash,N'') IS NULL
            THROW 56000,N'Tên đăng nhập và mật khẩu là bắt buộc.',1;

        IF EXISTS(SELECT 1 FROM dbo.HT_Tai_Khoan WHERE LaQuanTriHeThong=1)
        BEGIN
            ROLLBACK;
            SELECT 409 AS Status,N'Hệ thống đã có tài khoản quản trị global.' AS Message;
            RETURN;
        END;

        IF EXISTS(SELECT 1 FROM dbo.HT_Tai_Khoan WHERE LOWER(Ten_Dang_Nhap)=LOWER(@Ten_Dang_Nhap))
        BEGIN
            ROLLBACK;
            SELECT 409 AS Status,N'Tên đăng nhập đã tồn tại.' AS Message;
            RETURN;
        END;

        INSERT dbo.HT_Tai_Khoan
            (IDCSKCB,IDNhanVien,Ten_Dang_Nhap,Mat_Khau_Hash,Bat_Buoc_Doi_Mat_Khau,LaQuanTriHeThong,Active)
        VALUES
            (NULL,NULL,@Ten_Dang_Nhap,@Mat_Khau_Hash,0,1,1);

        COMMIT;
        SELECT 200 AS Status,N'Khởi tạo quản trị hệ thống global thành công.' AS Message;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK;
        SELECT 500 AS Status,ERROR_MESSAGE() AS Message;
    END CATCH
END;
GO

/* ==================== STO_HT_Khoi_Tao_Thong_Tin ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_HT_Khoi_Tao_Thong_Tin
    @IDCSKCB BIGINT = NULL,
    @TuKhoa NVARCHAR(200) = NULL,
    @Top INT = 100
AS
BEGIN
    SET NOCOUNT ON;
    SET @TuKhoa=NULLIF(LTRIM(RTRIM(@TuKhoa)),N'');
    SET @Top=CASE WHEN @Top<1 THEN 1 WHEN @Top>100 THEN 100 ELSE @Top END;

    SELECT TOP (@Top)
        C.ID AS IDCSKCB,
        C.MaCSKCB,
        C.TenCSKCB,
        C.Active,
        CASE
            WHEN EXISTS(SELECT 1 FROM dbo.HT_Tai_Khoan T WHERE T.IDCSKCB = C.ID)
                THEN CAST(1 AS BIT)
            ELSE CAST(0 AS BIT)
        END AS DaCoTaiKhoan
    FROM dbo.DM_CSKCB C
    WHERE C.Active = 1
      AND (@IDCSKCB IS NULL OR C.ID = @IDCSKCB)
      AND
      (
          @TuKhoa IS NULL
          OR C.MaCSKCB LIKE N'%'+@TuKhoa+N'%'
          OR C.TenCSKCB LIKE N'%'+@TuKhoa+N'%'
      )
    ORDER BY C.TenCSKCB,C.ID;

    SELECT TOP (@Top)
        N.ID AS IDNhanVien,
        N.IDCSKCB,
        N.MaNhanVien,
        N.HoTen,
        N.LaBacSi,
        N.ChucDanh
    FROM dbo.DM_NhanVien N
    WHERE @IDCSKCB IS NOT NULL
      AND N.Active = 1
      AND N.IDCSKCB = @IDCSKCB
      AND
      (
          @TuKhoa IS NULL
          OR N.MaNhanVien LIKE N'%'+@TuKhoa+N'%'
          OR N.HoTen LIKE N'%'+@TuKhoa+N'%'
      )
      AND NOT EXISTS
      (
          SELECT 1
          FROM dbo.HT_Tai_Khoan T
          WHERE T.IDCSKCB = N.IDCSKCB
      )
    ORDER BY N.HoTen,N.ID;
END;
GO

/* ==================== STO_HT_Lay_Quyen_Tai_Khoan ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_HT_Lay_Quyen_Tai_Khoan
    @ID_Tai_Khoan BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS
    (
        SELECT 1
        FROM dbo.HT_Tai_Khoan
        WHERE ID=@ID_Tai_Khoan
          AND Active=1
          AND LaQuanTriHeThong=1
    )
    BEGIN
        SELECT
            CAST(0 AS BIGINT) AS ID_Vai_Tro,
            N'quan_tri_he_thong' AS Ma_Vai_Tro,
            N'Quản trị hệ thống' AS Ten_Vai_Tro;

        SELECT
            CAST(NULL AS NVARCHAR(150)) AS Ma_Chuc_Nang,
            CAST(0 AS INT) AS Xem,
            CAST(0 AS INT) AS Them,
            CAST(0 AS INT) AS Sua,
            CAST(0 AS INT) AS Xoa,
            CAST(0 AS INT) AS Xuat,
            CAST(0 AS INT) AS CaNhan
        WHERE 1=0;
        RETURN;
    END;

    SELECT DISTINCT
        VT.ID AS ID_Vai_Tro,
        CASE WHEN VT.Ma_Vai_Tro=N'quan_tri_he_thong' THEN N'quan_tri_cskcb' ELSE VT.Ma_Vai_Tro END AS Ma_Vai_Tro,
        CASE WHEN VT.Ma_Vai_Tro=N'quan_tri_he_thong' AND VT.Ten_Vai_Tro=N'Quản trị hệ thống'
             THEN N'Quản trị cơ sở KCB' ELSE VT.Ten_Vai_Tro END AS Ten_Vai_Tro
    FROM dbo.HT_Tai_Khoan T
    INNER JOIN dbo.HT_Tai_Khoan_Vai_Tro TV
        ON TV.IDCSKCB=T.IDCSKCB
       AND TV.ID_Tai_Khoan=T.ID
       AND TV.Active=1
    INNER JOIN dbo.DM_Vai_Tro VT
        ON VT.IDCSKCB=TV.IDCSKCB
       AND VT.ID=TV.ID_Vai_Tro
       AND VT.Active=1
    WHERE T.ID=@ID_Tai_Khoan
      AND T.Active=1
      AND T.LaQuanTriHeThong=0;

    SELECT
        CN.Ma_Chuc_Nang,
        MAX(CONVERT(INT,Q.Xem)) AS Xem,
        MAX(CONVERT(INT,Q.Them)) AS Them,
        MAX(CONVERT(INT,Q.Sua)) AS Sua,
        MAX(CONVERT(INT,Q.Xoa)) AS Xoa,
        MAX(CONVERT(INT,Q.Xuat)) AS Xuat,
        MAX(CONVERT(INT,Q.Ca_Nhan)) AS CaNhan
    FROM dbo.HT_Tai_Khoan T
    INNER JOIN dbo.HT_Tai_Khoan_Vai_Tro TV
        ON TV.IDCSKCB=T.IDCSKCB
       AND TV.ID_Tai_Khoan=T.ID
       AND TV.Active=1
    INNER JOIN dbo.HT_Quyen_Vai_Tro Q
        ON Q.IDCSKCB=TV.IDCSKCB
       AND Q.ID_Vai_Tro=TV.ID_Vai_Tro
    INNER JOIN dbo.HT_Chuc_Nang CN
        ON CN.IDCSKCB=Q.IDCSKCB
       AND CN.ID=Q.ID_Chuc_Nang
       AND CN.Active=1
    WHERE T.ID=@ID_Tai_Khoan
      AND T.Active=1
      AND T.LaQuanTriHeThong=0
    GROUP BY CN.Ma_Chuc_Nang;
END;
GO

/* ==================== STO_HT_Nhan_Vien_Danh_Sach ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_HT_Nhan_Vien_Danh_Sach
    @IDCSKCB BIGINT=NULL,
    @TuKhoa NVARCHAR(200)=NULL,
    @Trang INT=1,
    @KichThuocTrang INT=25
AS
BEGIN
    SET NOCOUNT ON;
    SET @TuKhoa=NULLIF(LTRIM(RTRIM(@TuKhoa)),N'');
    SET @Trang=CASE WHEN @Trang<1 THEN 1 ELSE @Trang END;
    SET @KichThuocTrang=CASE WHEN @KichThuocTrang<10 THEN 10 WHEN @KichThuocTrang>100 THEN 100 ELSE @KichThuocTrang END;

    ;WITH D AS
    (
        SELECT
            N.ID AS IDNhanVien,N.IDCSKCB,C.MaCSKCB,C.TenCSKCB,N.MaNhanVien,N.HoTen,N.LaBacSi,N.ChucDanh,
            N.DienThoai,N.SoNhaTenDuong,N.DiaChi,N.MaTinh,N.MaPhuongXa,N.Email,N.Active,
            CASE WHEN T.ID IS NULL THEN CAST(0 AS BIT) ELSE CAST(1 AS BIT) END AS DaCoTaiKhoan,
            T.Ten_Dang_Nhap
        FROM dbo.DM_NhanVien N
        INNER JOIN dbo.DM_CSKCB C ON C.ID=N.IDCSKCB
        LEFT JOIN dbo.HT_Tai_Khoan T
          ON T.IDCSKCB=N.IDCSKCB AND T.IDNhanVien=N.ID
        WHERE (@IDCSKCB IS NULL OR N.IDCSKCB=@IDCSKCB)
          AND
          (
              @TuKhoa IS NULL
              OR N.MaNhanVien LIKE N'%'+@TuKhoa+N'%'
              OR N.HoTen LIKE N'%'+@TuKhoa+N'%'
              OR N.DienThoai LIKE N'%'+@TuKhoa+N'%'
              OR N.SoNhaTenDuong LIKE N'%'+@TuKhoa+N'%'
              OR N.DiaChi LIKE N'%'+@TuKhoa+N'%'
              OR N.Email LIKE N'%'+@TuKhoa+N'%'
              OR C.MaCSKCB LIKE N'%'+@TuKhoa+N'%'
              OR C.TenCSKCB LIKE N'%'+@TuKhoa+N'%'
          )
    )
    SELECT D.*,COUNT(*) OVER() AS TongSoDong
    FROM D
    ORDER BY D.IDNhanVien DESC
    OFFSET (@Trang-1)*@KichThuocTrang ROWS
    FETCH NEXT @KichThuocTrang ROWS ONLY;
END;
GO

/* ==================== STO_HT_Nhan_Vien_Luu ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_HT_Nhan_Vien_Luu
    @IDCSKCB BIGINT,
    @IDNhanVien BIGINT = NULL,
    @MaNhanVien NVARCHAR(30),
    @HoTen NVARCHAR(200),
    @LaBacSi BIT = 0,
    @ChucDanh NVARCHAR(100) = NULL,
    @DienThoai NVARCHAR(20) = NULL,
    @SoNhaTenDuong NVARCHAR(300) = NULL,
    @MaTinh NVARCHAR(20) = NULL,
    @MaPhuongXa NVARCHAR(20) = NULL,
    @Email NVARCHAR(200) = NULL,
    @Active BIT = 1
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        SET @MaNhanVien = NULLIF(LTRIM(RTRIM(@MaNhanVien)), N'');
        SET @HoTen = NULLIF(LTRIM(RTRIM(@HoTen)), N'');
        SET @ChucDanh = NULLIF(LTRIM(RTRIM(@ChucDanh)), N'');
        SET @DienThoai = NULLIF(LTRIM(RTRIM(@DienThoai)), N'');
        SET @SoNhaTenDuong = NULLIF(LTRIM(RTRIM(@SoNhaTenDuong)), N'');
        SET @MaTinh = NULLIF(LTRIM(RTRIM(@MaTinh)), N'');
        SET @MaPhuongXa = NULLIF(LTRIM(RTRIM(@MaPhuongXa)), N'');
        SET @Email = NULLIF(LTRIM(RTRIM(@Email)), N'');

        IF @DienThoai IS NOT NULL AND (LEN(@DienThoai)>10 OR @DienThoai LIKE N'%[^0-9]%')
            THROW 51000, N'Số điện thoại chỉ được nhập số và tối đa 10 ký tự.', 1;

        IF @MaNhanVien IS NULL OR @HoTen IS NULL
            THROW 51000, N'Mã nhân viên và họ tên là bắt buộc.', 1;

        IF EXISTS
        (
            SELECT 1
            FROM dbo.DM_NhanVien
            WHERE IDCSKCB = @IDCSKCB
              AND MaNhanVien = @MaNhanVien
              AND (@IDNhanVien IS NULL OR ID <> @IDNhanVien)
        )
            THROW 51000, N'Mã nhân viên đã tồn tại.', 1;

        DECLARE @TenTinh NVARCHAR(200)=NULL,
                @TenPhuongXa NVARCHAR(200)=NULL,
                @DiaChi NVARCHAR(500)=NULL;

        IF @MaTinh IS NOT NULL
            SELECT TOP(1) @TenTinh=T.TenTinh
            FROM dbo.DM_TinhThanh T
            WHERE T.Active=1 AND T.MaTinh=@MaTinh
            ORDER BY CASE WHEN T.IDCSKCB=@IDCSKCB THEN 0 ELSE 1 END,T.ID;

        IF @MaPhuongXa IS NOT NULL
            SELECT TOP(1) @TenPhuongXa=P.TenPhuongXa
            FROM dbo.DM_PhuongXa P
            LEFT JOIN dbo.DM_TinhThanh T
              ON T.IDCSKCB=P.IDCSKCB AND T.ID=P.IDTinhThanh
            WHERE P.Active=1
              AND P.MaPhuongXa=@MaPhuongXa
              AND (@MaTinh IS NULL OR T.MaTinh=@MaTinh)
            ORDER BY CASE WHEN P.IDCSKCB=@IDCSKCB THEN 0 ELSE 1 END,P.ID;

        SET @DiaChi=NULLIF(CONCAT_WS(N', ',@SoNhaTenDuong,@TenPhuongXa,@TenTinh),N'');

        IF @IDNhanVien IS NULL OR @IDNhanVien = 0
        BEGIN
            INSERT dbo.DM_NhanVien
            (
                IDCSKCB, MaNhanVien, HoTen, LaBacSi,
                ChucDanh, DienThoai, SoNhaTenDuong, DiaChi, MaTinh, MaPhuongXa, Email, Active
            )
            VALUES
            (
                @IDCSKCB, @MaNhanVien, @HoTen, @LaBacSi,
                @ChucDanh, @DienThoai, @SoNhaTenDuong, @DiaChi, @MaTinh, @MaPhuongXa, @Email, @Active
            );

            SET @IDNhanVien = SCOPE_IDENTITY();
        END
        ELSE
        BEGIN
            IF NOT EXISTS
            (
                SELECT 1 FROM dbo.DM_NhanVien
                WHERE IDCSKCB = @IDCSKCB AND ID = @IDNhanVien
            )
                THROW 51000, N'Không tìm thấy nhân viên.', 1;

            UPDATE dbo.DM_NhanVien
            SET MaNhanVien = @MaNhanVien,
                HoTen = @HoTen,
                LaBacSi = @LaBacSi,
                ChucDanh = @ChucDanh,
                DienThoai = @DienThoai,
                SoNhaTenDuong = @SoNhaTenDuong,
                DiaChi = @DiaChi,
                MaTinh = @MaTinh,
                MaPhuongXa = @MaPhuongXa,
                Email = @Email,
                Active = @Active
            WHERE IDCSKCB = @IDCSKCB
              AND ID = @IDNhanVien;
        END;

        SELECT
            200 AS Status,
            N'Lưu nhân viên thành công.' AS Message,
            @IDNhanVien AS IDNhanVien;
    END TRY
    BEGIN CATCH
        SELECT
            400 AS Status,
            ERROR_MESSAGE() AS Message,
            @IDNhanVien AS IDNhanVien;
    END CATCH
END;
GO

/* ==================== STO_HT_Nhan_Vien_Xoa ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_HT_Nhan_Vien_Xoa
    @IDCSKCB BIGINT,
    @IDNhanVien BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF NOT EXISTS(SELECT 1 FROM dbo.DM_NhanVien WHERE IDCSKCB=@IDCSKCB AND ID=@IDNhanVien)
    BEGIN
        SELECT 404 AS Status,N'Không tìm thấy nhân viên.' AS Message;
        RETURN;
    END;

    BEGIN TRY
        BEGIN TRAN;

        DELETE TV
        FROM dbo.HT_Tai_Khoan_Vai_Tro TV
        INNER JOIN dbo.HT_Tai_Khoan T
          ON T.IDCSKCB=TV.IDCSKCB AND T.ID=TV.ID_Tai_Khoan
        WHERE T.IDCSKCB=@IDCSKCB AND T.IDNhanVien=@IDNhanVien;

        DELETE dbo.HT_Tai_Khoan
        WHERE IDCSKCB=@IDCSKCB AND IDNhanVien=@IDNhanVien;

        CREATE TABLE #RefNhanVien
        (
            ObjectID INT NOT NULL,
            SchemaName SYSNAME NOT NULL,
            TableName SYSNAME NOT NULL,
            ColumnName SYSNAME NOT NULL,
            CoIDCSKCB BIT NOT NULL,
            PRIMARY KEY(ObjectID,ColumnName)
        );

        INSERT #RefNhanVien(ObjectID,SchemaName,TableName,ColumnName,CoIDCSKCB)
        SELECT DISTINCT
            T.object_id,S.name,T.name,PC.name,
            CASE WHEN EXISTS
            (
                SELECT 1 FROM sys.columns TC
                WHERE TC.object_id=T.object_id AND TC.name=N'IDCSKCB'
            ) THEN 1 ELSE 0 END
        FROM sys.foreign_keys FK
        INNER JOIN sys.foreign_key_columns FKC ON FKC.constraint_object_id=FK.object_id
        INNER JOIN sys.tables T ON T.object_id=FK.parent_object_id
        INNER JOIN sys.schemas S ON S.schema_id=T.schema_id
        INNER JOIN sys.columns PC
          ON PC.object_id=FK.parent_object_id AND PC.column_id=FKC.parent_column_id
        INNER JOIN sys.columns RC
          ON RC.object_id=FK.referenced_object_id AND RC.column_id=FKC.referenced_column_id
        WHERE FK.referenced_object_id=OBJECT_ID(N'dbo.DM_NhanVien')
          AND RC.name=N'ID'
          AND PC.is_nullable=1;

        DECLARE @Known TABLE(ColumnName SYSNAME PRIMARY KEY);
        INSERT @Known(ColumnName) VALUES
        (N'IDNhanVien'),(N'IDNguoiTiepNhan'),(N'IDBacSiKham'),(N'IDBacSi'),
        (N'IDBacSiChiDinh'),(N'IDBacSiKe'),(N'IDNhanVienThu'),
        (N'IDNVThucHien'),(N'IDBSDoc');

        INSERT #RefNhanVien(ObjectID,SchemaName,TableName,ColumnName,CoIDCSKCB)
        SELECT T.object_id,S.name,T.name,C.name,1
        FROM sys.tables T
        INNER JOIN sys.schemas S ON S.schema_id=T.schema_id
        INNER JOIN sys.columns C ON C.object_id=T.object_id
        INNER JOIN @Known K ON K.ColumnName=C.name
        WHERE T.is_ms_shipped=0
          AND C.is_nullable=1
          AND EXISTS
          (
              SELECT 1 FROM sys.columns TC
              WHERE TC.object_id=T.object_id AND TC.name=N'IDCSKCB'
          )
          AND NOT EXISTS
          (
              SELECT 1 FROM #RefNhanVien X
              WHERE X.ObjectID=T.object_id AND X.ColumnName=C.name
          );

        DECLARE @Schema SYSNAME,@Table SYSNAME,@Column SYSNAME,@CoIDCSKCB BIT,@Sql NVARCHAR(MAX);

        DECLARE ref_cursor CURSOR LOCAL FAST_FORWARD FOR
            SELECT SchemaName,TableName,ColumnName,CoIDCSKCB
            FROM #RefNhanVien
            ORDER BY SchemaName,TableName,ColumnName;
        OPEN ref_cursor;
        FETCH NEXT FROM ref_cursor INTO @Schema,@Table,@Column,@CoIDCSKCB;
        WHILE @@FETCH_STATUS=0
        BEGIN
            SET @Sql=N'UPDATE '+QUOTENAME(@Schema)+N'.'+QUOTENAME(@Table)
                +N' SET '+QUOTENAME(@Column)+N'=NULL WHERE '+QUOTENAME(@Column)+N'=@IDNhanVien'
                +CASE WHEN @CoIDCSKCB=1 THEN N' AND [IDCSKCB]=@IDCSKCB' ELSE N'' END+N';';

            EXEC sys.sp_executesql @Sql,N'@IDCSKCB BIGINT,@IDNhanVien BIGINT',@IDCSKCB,@IDNhanVien;
            FETCH NEXT FROM ref_cursor INTO @Schema,@Table,@Column,@CoIDCSKCB;
        END;
        CLOSE ref_cursor;
        DEALLOCATE ref_cursor;

        DELETE dbo.DM_NhanVien
        WHERE IDCSKCB=@IDCSKCB AND ID=@IDNhanVien;

        COMMIT;
        SELECT 200 AS Status,N'Đã xóa hoàn toàn nhân viên, tài khoản và gỡ tham chiếu khỏi dữ liệu nghiệp vụ.' AS Message;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK;
        IF ERROR_NUMBER()=547
            SELECT 409 AS Status,N'Còn quan hệ bắt buộc tới nhân viên chưa thể gỡ tự động: '+ERROR_MESSAGE() AS Message;
        ELSE
            SELECT 500 AS Status,ERROR_MESSAGE() AS Message;
    END CATCH
END;
GO

/* ==================== STO_HT_Nhan_Vien_Import_Excel ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_HT_Nhan_Vien_Import_Excel
    @IDCSKCB BIGINT,
    @DuLieuJson NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @IDCSKCB<=0
    BEGIN
        SELECT 400 Status,N'Thiếu cơ sở khám chữa bệnh.' Message,0 SoDong,0 SoThem,0 SoCapNhat;
        SELECT TOP(0) CAST(NULL AS INT) DongExcel,CAST(NULL AS NVARCHAR(30)) MaNhanVien,CAST(NULL AS NVARCHAR(2000)) Loi;
        RETURN;
    END;

    IF ISJSON(ISNULL(@DuLieuJson,N''))<>1
    BEGIN
        SELECT 400 Status,N'Dữ liệu import không hợp lệ.' Message,0 SoDong,0 SoThem,0 SoCapNhat;
        SELECT TOP(0) CAST(NULL AS INT) DongExcel,CAST(NULL AS NVARCHAR(30)) MaNhanVien,CAST(NULL AS NVARCHAR(2000)) Loi;
        RETURN;
    END;

    DECLARE @D TABLE
    (
        DongExcel INT NOT NULL,
        MaNhanVien NVARCHAR(30) NULL,
        HoTen NVARCHAR(200) NULL,
        LaBacSi BIT NOT NULL,
        ChucDanh NVARCHAR(100) NULL,
        DienThoai NVARCHAR(20) NULL,
        SoNhaTenDuong NVARCHAR(300) NULL,
        MaTinh NVARCHAR(20) NULL,
        MaPhuongXa NVARCHAR(20) NULL,
        DiaChi NVARCHAR(500) NULL,
        Email NVARCHAR(200) NULL,
        Active BIT NOT NULL,
        LaMoi BIT NULL,
        Loi NVARCHAR(2000) NULL
    );

    INSERT @D(DongExcel,MaNhanVien,HoTen,LaBacSi,ChucDanh,DienThoai,SoNhaTenDuong,MaTinh,MaPhuongXa,Email,Active)
    SELECT
        ISNULL(J.DongExcel,0),
        NULLIF(LTRIM(RTRIM(J.MaNhanVien)),N''),
        NULLIF(LTRIM(RTRIM(J.HoTen)),N''),
        ISNULL(J.LaBacSi,0),
        NULLIF(LTRIM(RTRIM(J.ChucDanh)),N''),
        NULLIF(LTRIM(RTRIM(J.DienThoai)),N''),
        NULLIF(LTRIM(RTRIM(J.SoNhaTenDuong)),N''),
        NULLIF(LTRIM(RTRIM(J.MaTinh)),N''),
        NULLIF(LTRIM(RTRIM(J.MaPhuongXa)),N''),
        NULLIF(LTRIM(RTRIM(J.Email)),N''),
        ISNULL(J.Active,1)
    FROM OPENJSON(@DuLieuJson)
    WITH
    (
        DongExcel INT '$.dong_excel',
        MaNhanVien NVARCHAR(30) '$.ma_nhan_vien',
        HoTen NVARCHAR(200) '$.ho_ten',
        LaBacSi BIT '$.la_bac_si',
        ChucDanh NVARCHAR(100) '$.chuc_danh',
        DienThoai NVARCHAR(20) '$.dien_thoai',
        SoNhaTenDuong NVARCHAR(300) '$.so_nha_ten_duong',
        MaTinh NVARCHAR(20) '$.ma_tinh',
        MaPhuongXa NVARCHAR(20) '$.ma_phuong_xa',
        Email NVARCHAR(200) '$.email',
        Active BIT '$.active'
    ) J;

    IF NOT EXISTS(SELECT 1 FROM @D)
    BEGIN
        SELECT 400 Status,N'Excel không có dòng nhân viên để import.' Message,0 SoDong,0 SoThem,0 SoCapNhat;
        SELECT TOP(0) CAST(NULL AS INT) DongExcel,CAST(NULL AS NVARCHAR(30)) MaNhanVien,CAST(NULL AS NVARCHAR(2000)) Loi;
        RETURN;
    END;

    UPDATE D
    SET Loi=NULLIF(CONCAT_WS(N'; ',
        CASE WHEN DongExcel<=1 THEN N'Số dòng Excel không hợp lệ' END,
        CASE WHEN MaNhanVien IS NULL THEN N'Thiếu Mã nhân viên' END,
        CASE WHEN HoTen IS NULL THEN N'Thiếu Họ tên' END,
        CASE WHEN LEN(ISNULL(MaNhanVien,N''))>30 THEN N'Mã nhân viên vượt 30 ký tự' END,
        CASE WHEN LEN(ISNULL(HoTen,N''))>200 THEN N'Họ tên vượt 200 ký tự' END,
        CASE WHEN DienThoai IS NOT NULL AND (LEN(DienThoai)>10 OR DienThoai LIKE N'%[^0-9]%') THEN N'SĐT chỉ được nhập số và tối đa 10 ký tự' END,
        CASE WHEN LEN(ISNULL(SoNhaTenDuong,N''))>300 THEN N'Số nhà / tên đường vượt 300 ký tự' END,
        CASE WHEN LEN(ISNULL(MaTinh,N''))>20 THEN N'Mã tỉnh vượt 20 ký tự' END,
        CASE WHEN LEN(ISNULL(MaPhuongXa,N''))>20 THEN N'Mã phường / xã vượt 20 ký tự' END,
        CASE WHEN LEN(ISNULL(Email,N''))>200 THEN N'Email vượt 200 ký tự' END
    ),N'')
    FROM @D D;

    ;WITH Dup AS
    (
        SELECT MaNhanVien
        FROM @D
        WHERE MaNhanVien IS NOT NULL
        GROUP BY MaNhanVien
        HAVING COUNT(*)>1
    )
    UPDATE D
    SET Loi=CONCAT_WS(N'; ',NULLIF(D.Loi,N''),N'Trùng Mã nhân viên trong file Excel')
    FROM @D D
    INNER JOIN Dup X ON X.MaNhanVien=D.MaNhanVien;

    UPDATE D
    SET DiaChi=NULLIF(CONCAT_WS(N', ',D.SoNhaTenDuong,PX.TenPhuongXa,TT.TenTinh),N'')
    FROM @D D
    OUTER APPLY
    (
        SELECT TOP(1) T.TenTinh
        FROM dbo.DM_TinhThanh T
        WHERE T.Active=1 AND T.MaTinh=D.MaTinh
        ORDER BY CASE WHEN T.IDCSKCB=@IDCSKCB THEN 0 ELSE 1 END,T.ID
    ) TT
    OUTER APPLY
    (
        SELECT TOP(1) P.TenPhuongXa
        FROM dbo.DM_PhuongXa P
        LEFT JOIN dbo.DM_TinhThanh T
          ON T.IDCSKCB=P.IDCSKCB AND T.ID=P.IDTinhThanh
        WHERE P.Active=1
          AND P.MaPhuongXa=D.MaPhuongXa
          AND (D.MaTinh IS NULL OR T.MaTinh=D.MaTinh)
        ORDER BY CASE WHEN P.IDCSKCB=@IDCSKCB THEN 0 ELSE 1 END,P.ID
    ) PX;

    UPDATE D
    SET LaMoi=CASE WHEN EXISTS
    (
        SELECT 1 FROM dbo.DM_NhanVien N
        WHERE N.IDCSKCB=@IDCSKCB AND N.MaNhanVien=D.MaNhanVien
    ) THEN 0 ELSE 1 END
    FROM @D D
    WHERE D.MaNhanVien IS NOT NULL;

    DECLARE @SoDong INT=(SELECT COUNT(*) FROM @D),
            @SoThem INT=(SELECT COUNT(*) FROM @D WHERE LaMoi=1),
            @SoCapNhat INT=(SELECT COUNT(*) FROM @D WHERE LaMoi=0);

    IF EXISTS(SELECT 1 FROM @D WHERE Loi IS NOT NULL)
    BEGIN
        SELECT 400 Status,N'File có dữ liệu không hợp lệ. Chưa import dòng nào.' Message,@SoDong SoDong,0 SoThem,0 SoCapNhat;
        SELECT DongExcel,MaNhanVien,Loi FROM @D WHERE Loi IS NOT NULL ORDER BY DongExcel;
        RETURN;
    END;

    BEGIN TRY
        BEGIN TRAN;

        UPDATE N
        SET N.HoTen=D.HoTen,
            N.LaBacSi=D.LaBacSi,
            N.ChucDanh=D.ChucDanh,
            N.DienThoai=D.DienThoai,
            N.SoNhaTenDuong=D.SoNhaTenDuong,
            N.DiaChi=D.DiaChi,
            N.MaTinh=D.MaTinh,
            N.MaPhuongXa=D.MaPhuongXa,
            N.Email=D.Email,
            N.Active=D.Active
        FROM dbo.DM_NhanVien N
        INNER JOIN @D D ON D.MaNhanVien=N.MaNhanVien AND D.LaMoi=0
        WHERE N.IDCSKCB=@IDCSKCB;

        INSERT dbo.DM_NhanVien
        (
            IDCSKCB,MaNhanVien,HoTen,LaBacSi,ChucDanh,DienThoai,
            SoNhaTenDuong,DiaChi,MaTinh,MaPhuongXa,Email,Active
        )
        SELECT
            @IDCSKCB,MaNhanVien,HoTen,LaBacSi,ChucDanh,DienThoai,
            SoNhaTenDuong,DiaChi,MaTinh,MaPhuongXa,Email,Active
        FROM @D
        WHERE LaMoi=1;

        COMMIT;

        SELECT 200 Status,N'Import nhân viên thành công.' Message,@SoDong SoDong,@SoThem SoThem,@SoCapNhat SoCapNhat;
        SELECT TOP(0) CAST(NULL AS INT) DongExcel,CAST(NULL AS NVARCHAR(30)) MaNhanVien,CAST(NULL AS NVARCHAR(2000)) Loi;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK;
        SELECT 500 Status,ERROR_MESSAGE() Message,@SoDong SoDong,0 SoThem,0 SoCapNhat;
        SELECT TOP(0) CAST(NULL AS INT) DongExcel,CAST(NULL AS NVARCHAR(30)) MaNhanVien,CAST(NULL AS NVARCHAR(2000)) Loi;
    END CATCH
END;
GO

/* ==================== STO_HT_Phien_Kiem_Tra ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_HT_Phien_Kiem_Tra
    @ID_Tai_Khoan BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT TOP(1)
        T.ID AS ID_Tai_Khoan,
        T.IDCSKCB,
        T.IDNhanVien,
        T.Ten_Dang_Nhap,
        T.Bat_Buoc_Doi_Mat_Khau,
        T.Active AS Tai_Khoan_Active,
        T.LaQuanTriHeThong,
        CASE WHEN T.LaQuanTriHeThong=1 THEN N'ADMIN' ELSE N.MaNhanVien END AS MaNhanVien,
        CASE WHEN T.LaQuanTriHeThong=1 THEN T.Ten_Dang_Nhap ELSE N.HoTen END AS HoTen,
        CASE WHEN T.LaQuanTriHeThong=1 THEN CAST(1 AS BIT) ELSE ISNULL(N.Active,0) END AS Nhan_Vien_Active,
        CASE WHEN T.LaQuanTriHeThong=1 THEN NULL ELSE C.TenCSKCB END AS TenCSKCB,
        CASE WHEN T.LaQuanTriHeThong=1 THEN CAST(1 AS BIT) ELSE ISNULL(C.Active,0) END AS CSKCB_Active
    FROM dbo.HT_Tai_Khoan T
    LEFT JOIN dbo.DM_NhanVien N
        ON T.LaQuanTriHeThong=0
       AND N.IDCSKCB=T.IDCSKCB
       AND N.ID=T.IDNhanVien
    LEFT JOIN dbo.DM_CSKCB C
        ON T.LaQuanTriHeThong=0
       AND C.ID=T.IDCSKCB
    WHERE T.ID=@ID_Tai_Khoan;
END;
GO

/* ==================== STO_HT_Quyen_Vai_Tro_Lay ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_HT_Quyen_Vai_Tro_Lay
    @IDCSKCB BIGINT,
    @ID_Vai_Tro BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT
        P.ID AS ID_Phan_He,P.Ma_Phan_He,P.Ten_Phan_He,P.Thu_Tu AS Thu_Tu_Phan_He,
        C.ID AS ID_Chuc_Nang,C.Ma_Chuc_Nang,C.Ten_Chuc_Nang,C.Duong_Dan,C.Thu_Tu AS Thu_Tu_Chuc_Nang,
        ISNULL(Q.Xem,0) AS Xem,ISNULL(Q.Them,0) AS Them,ISNULL(Q.Sua,0) AS Sua,
        ISNULL(Q.Xoa,0) AS Xoa,ISNULL(Q.Xuat,0) AS Xuat,ISNULL(Q.Ca_Nhan,0) AS Ca_Nhan
    FROM dbo.HT_Phan_He P
    INNER JOIN dbo.HT_Chuc_Nang C ON C.IDCSKCB=P.IDCSKCB AND C.ID_Phan_He=P.ID AND C.Active=1
    LEFT JOIN dbo.HT_Quyen_Vai_Tro Q ON Q.IDCSKCB=C.IDCSKCB AND Q.ID_Vai_Tro=@ID_Vai_Tro AND Q.ID_Chuc_Nang=C.ID
    WHERE P.IDCSKCB=@IDCSKCB AND P.Active=1
    ORDER BY P.Thu_Tu,P.ID,C.Thu_Tu,C.ID;
END;
GO

/* ==================== STO_HT_Quyen_Vai_Tro_Luu ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_HT_Quyen_Vai_Tro_Luu
    @IDCSKCB BIGINT,
    @ID_Vai_Tro BIGINT,
    @Quyen_Json NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    BEGIN TRY
        BEGIN TRAN;

        IF NOT EXISTS(SELECT 1 FROM dbo.DM_Vai_Tro WHERE IDCSKCB=@IDCSKCB AND ID=@ID_Vai_Tro AND Active=1)
            THROW 51000,N'Vai trò không tồn tại hoặc đã ngừng hoạt động.',1;

        DELETE dbo.HT_Quyen_Vai_Tro
        WHERE IDCSKCB=@IDCSKCB AND ID_Vai_Tro=@ID_Vai_Tro;

        INSERT dbo.HT_Quyen_Vai_Tro(IDCSKCB,ID_Vai_Tro,ID_Chuc_Nang,Xem,Them,Sua,Xoa,Xuat,Ca_Nhan)
        SELECT
            @IDCSKCB,@ID_Vai_Tro,J.ID_Chuc_Nang,J.Xem,J.Them,J.Sua,J.Xoa,J.Xuat,J.Ca_Nhan
        FROM OPENJSON(ISNULL(@Quyen_Json,N'[]'))
        WITH
        (
            ID_Chuc_Nang BIGINT '$.id_chuc_nang',
            Xem BIT '$.xem',Them BIT '$.them',Sua BIT '$.sua',Xoa BIT '$.xoa',Xuat BIT '$.xuat',Ca_Nhan BIT '$.ca_nhan'
        ) J
        INNER JOIN dbo.HT_Chuc_Nang C ON C.IDCSKCB=@IDCSKCB AND C.ID=J.ID_Chuc_Nang AND C.Active=1;

        COMMIT;
        SELECT 200 AS Status,N'Lưu phân quyền thành công.' AS Message;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT>0 ROLLBACK;
        SELECT 400 AS Status,ERROR_MESSAGE() AS Message;
    END CATCH
END;
GO

/* ==================== STO_HT_Tai_Khoan_Danh_Sach ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_HT_Tai_Khoan_Danh_Sach
    @IDCSKCB BIGINT=NULL,
    @TuKhoa NVARCHAR(200)=NULL,
    @Trang INT=1,
    @KichThuocTrang INT=25
AS
BEGIN
    SET NOCOUNT ON;
    SET @TuKhoa=NULLIF(LTRIM(RTRIM(@TuKhoa)),N'');
    SET @Trang=CASE WHEN @Trang<1 THEN 1 ELSE @Trang END;
    SET @KichThuocTrang=CASE WHEN @KichThuocTrang<10 THEN 10 WHEN @KichThuocTrang>100 THEN 100 ELSE @KichThuocTrang END;

    ;WITH D AS
    (
        SELECT
            T.ID AS ID_Tai_Khoan,T.IDCSKCB,C.MaCSKCB,C.TenCSKCB,T.IDNhanVien,N.MaNhanVien,N.HoTen,N.ChucDanh,
            T.Ten_Dang_Nhap,T.Bat_Buoc_Doi_Mat_Khau,T.So_Lan_Dang_Nhap_Sai,T.Khoa_Den_Luc,T.Lan_Dang_Nhap_Cuoi,T.Active,
            STRING_AGG(V.Ten_Vai_Tro,N', ') WITHIN GROUP (ORDER BY V.Ten_Vai_Tro,V.ID) AS Vai_Tro,
            STRING_AGG(CONVERT(NVARCHAR(30),V.ID),N',') AS ID_Vai_Tro
        FROM dbo.HT_Tai_Khoan T
        INNER JOIN dbo.DM_CSKCB C ON C.ID=T.IDCSKCB
        INNER JOIN dbo.DM_NhanVien N ON N.IDCSKCB=T.IDCSKCB AND N.ID=T.IDNhanVien
        LEFT JOIN dbo.HT_Tai_Khoan_Vai_Tro TV
          ON TV.IDCSKCB=T.IDCSKCB AND TV.ID_Tai_Khoan=T.ID AND TV.Active=1
        LEFT JOIN dbo.DM_Vai_Tro V
          ON V.IDCSKCB=TV.IDCSKCB AND V.ID=TV.ID_Vai_Tro AND V.Active=1
        WHERE (@IDCSKCB IS NULL OR T.IDCSKCB=@IDCSKCB)
          AND
          (
              @TuKhoa IS NULL
              OR T.Ten_Dang_Nhap LIKE N'%'+@TuKhoa+N'%'
              OR N.MaNhanVien LIKE N'%'+@TuKhoa+N'%'
              OR N.HoTen LIKE N'%'+@TuKhoa+N'%'
              OR C.MaCSKCB LIKE N'%'+@TuKhoa+N'%'
              OR C.TenCSKCB LIKE N'%'+@TuKhoa+N'%'
          )
        GROUP BY
            T.ID,T.IDCSKCB,C.MaCSKCB,C.TenCSKCB,T.IDNhanVien,N.MaNhanVien,N.HoTen,N.ChucDanh,
            T.Ten_Dang_Nhap,T.Bat_Buoc_Doi_Mat_Khau,T.So_Lan_Dang_Nhap_Sai,
            T.Khoa_Den_Luc,T.Lan_Dang_Nhap_Cuoi,T.Active
    )
    SELECT D.*,COUNT(*) OVER() AS TongSoDong
    FROM D
    ORDER BY D.ID_Tai_Khoan DESC
    OFFSET (@Trang-1)*@KichThuocTrang ROWS
    FETCH NEXT @KichThuocTrang ROWS ONLY;
END;
GO

/* ==================== STO_HT_Tai_Khoan_Doi_Trang_Thai ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_HT_Tai_Khoan_Doi_Trang_Thai
    @IDCSKCB BIGINT,
    @ID_Tai_Khoan BIGINT,
    @Active BIT
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE dbo.HT_Tai_Khoan
    SET Active=@Active,
        Khoa_Den_Luc=CASE WHEN @Active=1 THEN NULL ELSE Khoa_Den_Luc END,
        Ngay_Cap_Nhat=SYSDATETIME()
    WHERE IDCSKCB=@IDCSKCB AND ID=@ID_Tai_Khoan;

    IF @@ROWCOUNT=0 SELECT 404 AS Status, N'Không tìm thấy tài khoản.' AS Message;
    ELSE SELECT 200 AS Status, CASE WHEN @Active=1 THEN N'Đã mở tài khoản.' ELSE N'Đã khóa tài khoản.' END AS Message;
END;
GO

/* ==================== STO_HT_Tai_Khoan_Luu ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_HT_Tai_Khoan_Luu
    @IDCSKCB BIGINT,
    @ID_Tai_Khoan BIGINT = NULL,
    @IDNhanVien BIGINT,
    @Ten_Dang_Nhap NVARCHAR(150),
    @Mat_Khau_Hash NVARCHAR(1000) = NULL,
    @Vai_Tro_Json NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRAN;

        SET @Ten_Dang_Nhap = LTRIM(RTRIM(@Ten_Dang_Nhap));
        IF @Ten_Dang_Nhap = N'' THROW 51000, N'Tên đăng nhập là bắt buộc.', 1;

        IF NOT EXISTS(SELECT 1 FROM dbo.DM_NhanVien WHERE IDCSKCB=@IDCSKCB AND ID=@IDNhanVien AND Active=1)
            THROW 51000, N'Nhân viên không tồn tại hoặc đã ngừng hoạt động.', 1;

        IF EXISTS
        (
            SELECT 1 FROM dbo.HT_Tai_Khoan
            WHERE LOWER(Ten_Dang_Nhap) = LOWER(@Ten_Dang_Nhap)
              AND (@ID_Tai_Khoan IS NULL OR ID <> @ID_Tai_Khoan)
        )
            THROW 51000, N'Tên đăng nhập đã tồn tại.', 1;

        IF @ID_Tai_Khoan IS NULL OR @ID_Tai_Khoan = 0
        BEGIN
            IF @Mat_Khau_Hash IS NULL OR @Mat_Khau_Hash = N''
                THROW 51000, N'Mật khẩu là bắt buộc khi tạo tài khoản.', 1;

            INSERT dbo.HT_Tai_Khoan(IDCSKCB,IDNhanVien,Ten_Dang_Nhap,Mat_Khau_Hash,Bat_Buoc_Doi_Mat_Khau)
            VALUES(@IDCSKCB,@IDNhanVien,@Ten_Dang_Nhap,@Mat_Khau_Hash,0);
            SET @ID_Tai_Khoan = SCOPE_IDENTITY();
        END
        ELSE
        BEGIN
            IF NOT EXISTS(SELECT 1 FROM dbo.HT_Tai_Khoan WHERE ID=@ID_Tai_Khoan AND IDCSKCB=@IDCSKCB)
                THROW 51000, N'Không tìm thấy tài khoản.', 1;

            UPDATE dbo.HT_Tai_Khoan
            SET IDNhanVien=@IDNhanVien,
                Ten_Dang_Nhap=@Ten_Dang_Nhap,
                Ngay_Cap_Nhat=SYSDATETIME()
            WHERE ID=@ID_Tai_Khoan AND IDCSKCB=@IDCSKCB;
        END

        UPDATE dbo.HT_Tai_Khoan_Vai_Tro
        SET Active=0
        WHERE IDCSKCB=@IDCSKCB AND ID_Tai_Khoan=@ID_Tai_Khoan;

        ;WITH V AS
        (
            SELECT DISTINCT TRY_CONVERT(BIGINT,[value]) AS ID_Vai_Tro
            FROM OPENJSON(ISNULL(@Vai_Tro_Json,N'[]'))
            WHERE TRY_CONVERT(BIGINT,[value]) IS NOT NULL
        )
        UPDATE TV
        SET Active=1
        FROM dbo.HT_Tai_Khoan_Vai_Tro TV
        INNER JOIN V ON V.ID_Vai_Tro = TV.ID_Vai_Tro
        WHERE TV.IDCSKCB=@IDCSKCB AND TV.ID_Tai_Khoan=@ID_Tai_Khoan;

        ;WITH V AS
        (
            SELECT DISTINCT TRY_CONVERT(BIGINT,[value]) AS ID_Vai_Tro
            FROM OPENJSON(ISNULL(@Vai_Tro_Json,N'[]'))
            WHERE TRY_CONVERT(BIGINT,[value]) IS NOT NULL
        )
        INSERT dbo.HT_Tai_Khoan_Vai_Tro(IDCSKCB,ID_Tai_Khoan,ID_Vai_Tro,Active)
        SELECT @IDCSKCB,@ID_Tai_Khoan,V.ID_Vai_Tro,1
        FROM V
        INNER JOIN dbo.DM_Vai_Tro R ON R.IDCSKCB=@IDCSKCB AND R.ID=V.ID_Vai_Tro AND R.Active=1
        WHERE NOT EXISTS
        (
            SELECT 1 FROM dbo.HT_Tai_Khoan_Vai_Tro X
            WHERE X.IDCSKCB=@IDCSKCB AND X.ID_Tai_Khoan=@ID_Tai_Khoan AND X.ID_Vai_Tro=V.ID_Vai_Tro
        );

        COMMIT;
        SELECT 200 AS Status, N'Lưu tài khoản thành công.' AS Message, @ID_Tai_Khoan AS ID_Tai_Khoan;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;
        SELECT 400 AS Status, ERROR_MESSAGE() AS Message, @ID_Tai_Khoan AS ID_Tai_Khoan;
    END CATCH
END;
GO

/* ==================== STO_HT_Tai_Khoan_Lay_Theo_ID ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_HT_Tai_Khoan_Lay_Theo_ID
    @IDCSKCB BIGINT,
    @ID_Tai_Khoan BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT TOP 1 ID AS ID_Tai_Khoan,Ten_Dang_Nhap
    FROM dbo.HT_Tai_Khoan
    WHERE IDCSKCB=@IDCSKCB AND ID=@ID_Tai_Khoan;
END;
GO

/* ==================== STO_HT_Tai_Khoan_Xoa ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_HT_Tai_Khoan_Xoa
    @IDCSKCB BIGINT,
    @ID_Tai_Khoan BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF NOT EXISTS(SELECT 1 FROM dbo.HT_Tai_Khoan WHERE IDCSKCB=@IDCSKCB AND ID=@ID_Tai_Khoan)
    BEGIN
        SELECT 404 AS Status,N'Không tìm thấy tài khoản.' AS Message;
        RETURN;
    END;

    BEGIN TRY
        BEGIN TRAN;
        DELETE dbo.HT_Tai_Khoan_Vai_Tro
        WHERE IDCSKCB=@IDCSKCB AND ID_Tai_Khoan=@ID_Tai_Khoan;

        DELETE dbo.HT_Tai_Khoan
        WHERE IDCSKCB=@IDCSKCB AND ID=@ID_Tai_Khoan;
        COMMIT;

        SELECT 200 AS Status,N'Xóa tài khoản thành công.' AS Message;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK;
        IF ERROR_NUMBER()=547
            SELECT 409 AS Status,N'Tài khoản còn dữ liệu liên quan nên chưa thể xóa.' AS Message;
        ELSE
            SELECT 500 AS Status,ERROR_MESSAGE() AS Message;
    END CATCH
END;
GO

/* ==================== STO_HT_Tai_Khoan_Reset_Mat_Khau ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_HT_Tai_Khoan_Reset_Mat_Khau
    @IDCSKCB BIGINT,
    @ID_Tai_Khoan BIGINT,
    @Mat_Khau_Hash NVARCHAR(1000)
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE dbo.HT_Tai_Khoan
    SET Mat_Khau_Hash=@Mat_Khau_Hash,
        Bat_Buoc_Doi_Mat_Khau=0,
        So_Lan_Dang_Nhap_Sai=0,
        Khoa_Den_Luc=NULL,
        Ngay_Cap_Nhat=SYSDATETIME()
    WHERE IDCSKCB=@IDCSKCB AND ID=@ID_Tai_Khoan;

    IF @@ROWCOUNT=0 SELECT 404 AS Status, N'Không tìm thấy tài khoản.' AS Message;
    ELSE SELECT 200 AS Status, N'Đã đặt lại mật khẩu về mặc định: a' AS Message;
END;
GO

/* ==================== STO_HT_Vai_Tro_Danh_Sach ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_HT_Vai_Tro_Danh_Sach
    @IDCSKCB BIGINT=NULL,
    @TuKhoa NVARCHAR(200)=NULL,
    @Trang INT=1,
    @KichThuocTrang INT=25
AS
BEGIN
    SET NOCOUNT ON;
    SET @TuKhoa=NULLIF(LTRIM(RTRIM(@TuKhoa)),N'');
    SET @Trang=CASE WHEN @Trang<1 THEN 1 ELSE @Trang END;
    SET @KichThuocTrang=CASE WHEN @KichThuocTrang<10 THEN 10 WHEN @KichThuocTrang>100 THEN 100 ELSE @KichThuocTrang END;

    ;WITH D AS
    (
        SELECT V.ID AS ID_Vai_Tro,V.IDCSKCB,C.MaCSKCB,C.TenCSKCB,V.Ma_Vai_Tro,V.Ten_Vai_Tro,V.Mo_Ta,V.Active,V.Ngay_Tao,V.Ngay_Cap_Nhat
        FROM dbo.DM_Vai_Tro V
        INNER JOIN dbo.DM_CSKCB C ON C.ID=V.IDCSKCB
        WHERE (@IDCSKCB IS NULL OR V.IDCSKCB=@IDCSKCB)
          AND
          (
              @TuKhoa IS NULL
              OR V.Ma_Vai_Tro LIKE N'%'+@TuKhoa+N'%'
              OR V.Ten_Vai_Tro LIKE N'%'+@TuKhoa+N'%'
              OR V.Mo_Ta LIKE N'%'+@TuKhoa+N'%'
              OR C.MaCSKCB LIKE N'%'+@TuKhoa+N'%'
              OR C.TenCSKCB LIKE N'%'+@TuKhoa+N'%'
          )
    )
    SELECT D.*,COUNT(*) OVER() AS TongSoDong
    FROM D
    ORDER BY D.Active DESC,D.Ten_Vai_Tro,D.ID_Vai_Tro
    OFFSET (@Trang-1)*@KichThuocTrang ROWS
    FETCH NEXT @KichThuocTrang ROWS ONLY;
END;
GO

/* ==================== STO_HT_Vai_Tro_Luu ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_HT_Vai_Tro_Luu
    @IDCSKCB BIGINT,
    @ID_Vai_Tro BIGINT = NULL,
    @Ma_Vai_Tro NVARCHAR(100),
    @Ten_Vai_Tro NVARCHAR(300),
    @Mo_Ta NVARCHAR(1000) = NULL,
    @Active BIT = 1
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        SET @Ma_Vai_Tro=LTRIM(RTRIM(@Ma_Vai_Tro));
        SET @Ten_Vai_Tro=LTRIM(RTRIM(@Ten_Vai_Tro));
        IF @Ma_Vai_Tro=N'' OR @Ten_Vai_Tro=N'' THROW 51000,N'Mã và tên vai trò là bắt buộc.',1;

        IF EXISTS(SELECT 1 FROM dbo.DM_Vai_Tro WHERE IDCSKCB=@IDCSKCB AND Ma_Vai_Tro=@Ma_Vai_Tro AND (@ID_Vai_Tro IS NULL OR ID<>@ID_Vai_Tro))
            THROW 51000,N'Mã vai trò đã tồn tại.',1;

        IF @ID_Vai_Tro IS NULL OR @ID_Vai_Tro=0
        BEGIN
            INSERT dbo.DM_Vai_Tro(IDCSKCB,Ma_Vai_Tro,Ten_Vai_Tro,Mo_Ta,Active)
            VALUES(@IDCSKCB,@Ma_Vai_Tro,@Ten_Vai_Tro,@Mo_Ta,@Active);
            SET @ID_Vai_Tro=SCOPE_IDENTITY();
        END
        ELSE
        BEGIN
            UPDATE dbo.DM_Vai_Tro
            SET Ma_Vai_Tro=@Ma_Vai_Tro,Ten_Vai_Tro=@Ten_Vai_Tro,Mo_Ta=@Mo_Ta,Active=@Active,Ngay_Cap_Nhat=SYSDATETIME()
            WHERE IDCSKCB=@IDCSKCB AND ID=@ID_Vai_Tro;
        END
        SELECT 200 AS Status,N'Lưu vai trò thành công.' AS Message,@ID_Vai_Tro AS ID_Vai_Tro;
    END TRY
    BEGIN CATCH
        SELECT 400 AS Status,ERROR_MESSAGE() AS Message,@ID_Vai_Tro AS ID_Vai_Tro;
    END CATCH
END;
GO

/* ==================== STO_HT_Vai_Tro_Xoa ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_HT_Vai_Tro_Xoa
    @IDCSKCB BIGINT,
    @ID_Vai_Tro BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @MaVaiTro NVARCHAR(100)=
    (
        SELECT Ma_Vai_Tro FROM dbo.DM_Vai_Tro
        WHERE IDCSKCB=@IDCSKCB AND ID=@ID_Vai_Tro
    );

    IF @MaVaiTro IS NULL
    BEGIN
        SELECT 404 AS Status,N'Không tìm thấy vai trò.' AS Message;
        RETURN;
    END;

    IF @MaVaiTro=N'quan_tri_he_thong'
    BEGIN
        SELECT 409 AS Status,N'Không được xóa vai trò quản trị hệ thống.' AS Message;
        RETURN;
    END;

    BEGIN TRY
        BEGIN TRAN;

        DELETE dbo.HT_Tai_Khoan_Vai_Tro
        WHERE IDCSKCB=@IDCSKCB AND ID_Vai_Tro=@ID_Vai_Tro;

        DELETE dbo.HT_Quyen_Vai_Tro
        WHERE IDCSKCB=@IDCSKCB AND ID_Vai_Tro=@ID_Vai_Tro;

        DELETE dbo.DM_Vai_Tro
        WHERE IDCSKCB=@IDCSKCB AND ID=@ID_Vai_Tro;

        COMMIT;
        SELECT 200 AS Status,N'Đã xóa hoàn toàn vai trò và gỡ khỏi mọi tài khoản.' AS Message;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK;
        SELECT 500 AS Status,ERROR_MESSAGE() AS Message;
    END CATCH
END;
GO

/* ==================== STO_DM_PhacDo_ChiTiet ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_DM_PhacDo_ChiTiet
    @IDCSKCB BIGINT,
    @ID BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    -- Result set 1: Thông tin phác đồ. Chẩn đoán nằm duy nhất ở result set 4.
    SELECT P.ID,
           P.MaPhacDo,
           P.TenPhacDo,
           P.TrieuChung,
           P.Active
    FROM dbo.DM_PhacDo P
    WHERE P.IDCSKCB = @IDCSKCB AND P.ID = @ID;

    -- Result set 2: Chi định CLS mẫu
    SELECT C.ID,
           C.IDDichVu,
           D.MaDichVu,
           D.TenDichVu,
           C.SoLuong,
           COALESCE(C.DonGia, D.DonGia) AS DonGia,
           C.GuiNgoai,
           C.NoiGuiNgoai,
           C.GhiChu
    FROM dbo.DM_PhacDo_ChiDinh C
    JOIN dbo.DM_DichVu D ON D.IDCSKCB = C.IDCSKCB AND D.ID = C.IDDichVu
    WHERE C.IDCSKCB = @IDCSKCB AND C.IDPhacDo = @ID AND C.Active = 1
    ORDER BY C.ThuTu, C.ID;

    -- Result set 3: Đơn thuốc mẫu
    SELECT T.ID,
           T.IDThuoc,
           D.MaThuoc,
           D.TenThuoc,
           D.HoatChat,
           COALESCE(DVT.TenDVT,D.DonViTinh) AS DonViTinh,
           T.SoNgay,
           T.Sang,
           T.Trua,
           T.Chieu,
           T.Toi,
           T.LieuDung,
           T.DuongDung,
           T.CachDung,
           T.SoLuong,
           COALESCE(T.DonGia, D.GiaBan) AS DonGia,
           T.ThuTu
    FROM dbo.DM_PhacDo_Thuoc T
    JOIN dbo.DM_Thuoc D ON D.IDCSKCB = T.IDCSKCB AND D.ID = T.IDThuoc
    LEFT JOIN dbo.DM_DonViTinh DVT ON DVT.IDCSKCB=D.IDCSKCB AND DVT.ID=D.IDDonViTinh
    WHERE T.IDCSKCB = @IDCSKCB AND T.IDPhacDo = @ID AND T.Active = 1
    ORDER BY T.ThuTu, T.ID;

    -- Result set 4: Danh sách chẩn đoán ICD-10 mẫu
    SELECT C.ID,
           C.IDICD10,
           I.MaBenh,
           I.TenBenh,
           C.BanDau,
           C.BenhChinh,
           C.BenhKhac,
           C.ThuTu
    FROM dbo.DM_PhacDo_ChanDoan C
    JOIN dbo.DM_ICD10 I ON I.IDCSKCB = C.IDCSKCB AND I.ID = C.IDICD10
    WHERE C.IDCSKCB = @IDCSKCB
      AND C.IDPhacDo = @ID
      AND C.Active = 1
    ORDER BY ISNULL(C.ThuTu, 2147483647), C.ID;
END;

GO

/* ==================== STO_DM_PhacDo_DanhSach ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_DM_PhacDo_DanhSach
    @IDCSKCB BIGINT,
    @TuKhoa NVARCHAR(200) = NULL,
    @Trang INT = 1,
    @KichThuocTrang INT = 25
AS
BEGIN
    SET NOCOUNT ON;

    SET @TuKhoa = NULLIF(LTRIM(RTRIM(@TuKhoa)), N'');
    SET @Trang = CASE WHEN @Trang < 1 THEN 1 ELSE @Trang END;
    SET @KichThuocTrang = CASE
        WHEN @KichThuocTrang < 10 THEN 10
        WHEN @KichThuocTrang > 100 THEN 100
        ELSE @KichThuocTrang
    END;

    ;WITH D AS
    (
        SELECT
            P.ID,
            P.MaPhacDo,
            P.TenPhacDo,
            CD.IDICD10,
            CD.MaBenh AS MaICD10,
            CD.TenBenh AS TenICD10,
            P.TrieuChung,
            P.Active,
            (SELECT COUNT(*) FROM dbo.DM_PhacDo_ChiDinh X WHERE X.IDCSKCB=P.IDCSKCB AND X.IDPhacDo=P.ID AND X.Active=1) AS SoLuongChiDinh,
            (SELECT COUNT(*) FROM dbo.DM_PhacDo_Thuoc X WHERE X.IDCSKCB=P.IDCSKCB AND X.IDPhacDo=P.ID AND X.Active=1) AS SoLuongThuoc
        FROM dbo.DM_PhacDo P
        OUTER APPLY
        (
            SELECT TOP(1) C.IDICD10,I.MaBenh,I.TenBenh
            FROM dbo.DM_PhacDo_ChanDoan C
            INNER JOIN dbo.DM_ICD10 I
              ON I.IDCSKCB=C.IDCSKCB AND I.ID=C.IDICD10
            WHERE C.IDCSKCB=P.IDCSKCB AND C.IDPhacDo=P.ID AND C.Active=1
            ORDER BY
                CASE WHEN C.BenhChinh=1 THEN 0 WHEN C.BanDau=1 THEN 1 ELSE 2 END,
                ISNULL(C.ThuTu,2147483647),C.ID
        ) CD
        WHERE P.IDCSKCB=@IDCSKCB
          AND P.Active=1
          AND
          (
              @TuKhoa IS NULL
              OR P.MaPhacDo LIKE N'%' + @TuKhoa + N'%'
              OR P.TenPhacDo LIKE N'%' + @TuKhoa + N'%'
              OR CD.MaBenh LIKE N'%' + @TuKhoa + N'%'
              OR CD.TenBenh LIKE N'%' + @TuKhoa + N'%'
          )
    )
    SELECT D.*,COUNT(*) OVER() AS TongSoDong
    FROM D
    ORDER BY D.MaPhacDo,D.TenPhacDo,D.ID
    OFFSET (@Trang-1)*@KichThuocTrang ROWS
    FETCH NEXT @KichThuocTrang ROWS ONLY;
END;
GO

/* ==================== STO_DM_PhacDo_Luu ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_DM_PhacDo_Luu
    @IDCSKCB BIGINT,
    @ID BIGINT = NULL OUTPUT,
    @MaPhacDo NVARCHAR(30),
    @TenPhacDo NVARCHAR(300),
    @TrieuChung NVARCHAR(2000) = NULL,
    @ChanDoanJson NVARCHAR(MAX) = N'[]',
    @ChiDinhJson NVARCHAR(MAX) = N'[]',
    @ThuocJson NVARCHAR(MAX) = N'[]'
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRAN;

        SET @MaPhacDo = NULLIF(LTRIM(RTRIM(@MaPhacDo)), N'');
        SET @TenPhacDo = NULLIF(LTRIM(RTRIM(@TenPhacDo)), N'');

        DECLARE @CD TABLE
        (
            IDICD10 BIGINT NOT NULL PRIMARY KEY,
            BanDau BIT NOT NULL,
            BenhChinh BIT NOT NULL,
            BenhKhac BIT NOT NULL,
            ThuTu INT NULL
        );

        IF ISJSON(@ChanDoanJson) = 1
        BEGIN
            INSERT @CD(IDICD10, BanDau, BenhChinh, BenhKhac, ThuTu)
            SELECT IDICD10,
                   ISNULL(BanDau, 0),
                   ISNULL(BenhChinh, 0),
                   ISNULL(BenhKhac, 0),
                   ThuTu
            FROM OPENJSON(@ChanDoanJson) WITH
            (
                IDICD10 BIGINT '$.IDICD10',
                BanDau BIT '$.BanDau',
                BenhChinh BIT '$.BenhChinh',
                BenhKhac BIT '$.BenhKhac',
                ThuTu INT '$.ThuTu'
            )
            WHERE IDICD10 IS NOT NULL;
        END;

        IF (SELECT COUNT(*) FROM @CD) > 12
        BEGIN
            ROLLBACK;
            SELECT 400 AS Status, N'Mỗi phác đồ chỉ được tối đa 12 chẩn đoán ICD-10.' AS Message, @ID AS ID;
            RETURN;
        END;

        IF (SELECT COUNT(*) FROM @CD WHERE BenhChinh = 1) <> 1
        BEGIN
            ROLLBACK;
            SELECT 400 AS Status, N'Phác đồ bắt buộc phải có đúng 1 bệnh chính.' AS Message, @ID AS ID;
            RETURN;
        END;

        IF EXISTS
        (
            SELECT 1
            FROM @CD C
            LEFT JOIN dbo.DM_ICD10 I
              ON I.IDCSKCB = @IDCSKCB
             AND I.ID = C.IDICD10
             AND I.Active = 1
            WHERE I.ID IS NULL
        )
        BEGIN
            ROLLBACK;
            SELECT 400 AS Status, N'Có mã ICD-10 không hợp lệ.' AS Message, @ID AS ID;
            RETURN;
        END;

        IF @MaPhacDo IS NULL OR @TenPhacDo IS NULL
        BEGIN
            ROLLBACK;
            SELECT 400 AS Status, N'Mã và tên phác đồ là bắt buộc.' AS Message, @ID AS ID;
            RETURN;
        END;

        IF @ID IS NULL OR @ID <= 0
        BEGIN
            DECLARE @IDPhacDoTrung BIGINT,@ActivePhacDoTrung BIT;

            SELECT TOP(1)
                   @IDPhacDoTrung=ID,
                   @ActivePhacDoTrung=Active
            FROM dbo.DM_PhacDo WITH(UPDLOCK,HOLDLOCK)
            WHERE IDCSKCB=@IDCSKCB AND MaPhacDo=@MaPhacDo;

            IF @IDPhacDoTrung IS NOT NULL AND ISNULL(@ActivePhacDoTrung,0)=1
            BEGIN
                ROLLBACK;
                SELECT 409 AS Status, N'Mã phác đồ đã tồn tại.' AS Message, @ID AS ID;
                RETURN;
            END;

            IF @IDPhacDoTrung IS NOT NULL
            BEGIN
                SET @ID=@IDPhacDoTrung;
                UPDATE dbo.DM_PhacDo
                SET TenPhacDo=@TenPhacDo,
                    TrieuChung=@TrieuChung,
                    Active=1
                WHERE IDCSKCB=@IDCSKCB AND ID=@ID;
            END
            ELSE
            BEGIN
                INSERT dbo.DM_PhacDo(IDCSKCB, MaPhacDo, TenPhacDo, TrieuChung, Active)
                VALUES(@IDCSKCB, @MaPhacDo, @TenPhacDo, @TrieuChung, 1);
                SET @ID = SCOPE_IDENTITY();
            END;
        END
        ELSE
        BEGIN
            IF EXISTS
            (
                SELECT 1
                FROM dbo.DM_PhacDo WITH(UPDLOCK,HOLDLOCK)
                WHERE IDCSKCB=@IDCSKCB
                  AND MaPhacDo=@MaPhacDo
                  AND ID<>@ID
            )
            BEGIN
                ROLLBACK;
                SELECT 409 AS Status, N'Mã phác đồ đã tồn tại ở một phác đồ khác.' AS Message, @ID AS ID;
                RETURN;
            END;

            UPDATE dbo.DM_PhacDo
            SET MaPhacDo = @MaPhacDo,
                TenPhacDo = @TenPhacDo,
                TrieuChung = @TrieuChung,
                Active = 1
            WHERE IDCSKCB = @IDCSKCB AND ID = @ID;
        END;

        -- Lưu danh sách chẩn đoán ICD-10 mẫu
        DELETE FROM dbo.DM_PhacDo_ChanDoan
        WHERE IDCSKCB = @IDCSKCB AND IDPhacDo = @ID;

        INSERT dbo.DM_PhacDo_ChanDoan
        (
            IDCSKCB, IDPhacDo, IDICD10,
            BanDau, BenhChinh, BenhKhac,
            ThuTu, Active
        )
        SELECT @IDCSKCB, @ID, C.IDICD10,
               C.BanDau, C.BenhChinh, C.BenhKhac,
               C.ThuTu, 1
        FROM @CD C;

        -- Lưu Chỉ định CLS mẫu
        DELETE FROM dbo.DM_PhacDo_ChiDinh WHERE IDCSKCB = @IDCSKCB AND IDPhacDo = @ID;

        IF ISJSON(@ChiDinhJson) = 1
        BEGIN
            INSERT dbo.DM_PhacDo_ChiDinh(IDCSKCB, IDPhacDo, IDDichVu, SoLuong, DonGia, GuiNgoai, NoiGuiNgoai, GhiChu, ThuTu, Active)
            SELECT @IDCSKCB, @ID, D.ID, ISNULL(NULLIF(J.SoLuong, 0), 1), COALESCE(J.DonGia, D.DonGia), ISNULL(J.GuiNgoai, 0), J.NoiGuiNgoai, J.GhiChu, J.ThuTu, 1
            FROM OPENJSON(@ChiDinhJson) WITH
            (
                IDDichVu BIGINT '$.IDDichVu',
                SoLuong DECIMAL(10,2) '$.SoLuong',
                DonGia DECIMAL(18,2) '$.DonGia',
                GuiNgoai BIT '$.GuiNgoai',
                NoiGuiNgoai NVARCHAR(300) '$.NoiGuiNgoai',
                GhiChu NVARCHAR(500) '$.GhiChu',
                ThuTu INT '$.ThuTu'
            ) J
            JOIN dbo.DM_DichVu D ON D.IDCSKCB = @IDCSKCB AND D.ID = J.IDDichVu AND D.Active = 1;
        END;

        -- Lưu Đơn thuốc mẫu
        DELETE FROM dbo.DM_PhacDo_Thuoc WHERE IDCSKCB = @IDCSKCB AND IDPhacDo = @ID;

        IF ISJSON(@ThuocJson) = 1
        BEGIN
            INSERT dbo.DM_PhacDo_Thuoc(IDCSKCB, IDPhacDo, IDThuoc, SoNgay, Sang, Trua, Chieu, Toi, LieuDung, DuongDung, CachDung, SoLuong, DonGia, ThuTu, Active)
            SELECT @IDCSKCB, @ID, D.ID, ISNULL(NULLIF(J.SoNgay, 0), 3), J.Sang, J.Trua, J.Chieu, J.Toi, J.LieuDung, J.DuongDung, J.CachDung,
                   ISNULL(NULLIF(J.SoLuong, 0), 1), COALESCE(J.DonGia, D.GiaBan), J.ThuTu, 1
            FROM OPENJSON(@ThuocJson) WITH
            (
                IDThuoc BIGINT '$.IDThuoc',
                SoNgay INT '$.SoNgay',
                Sang NVARCHAR(50) '$.Sang',
                Trua NVARCHAR(50) '$.Trua',
                Chieu NVARCHAR(50) '$.Chieu',
                Toi NVARCHAR(50) '$.Toi',
                LieuDung NVARCHAR(300) '$.LieuDung',
                DuongDung NVARCHAR(100) '$.DuongDung',
                CachDung NVARCHAR(500) '$.CachDung',
                SoLuong DECIMAL(10,2) '$.SoLuong',
                DonGia DECIMAL(18,2) '$.DonGia',
                ThuTu INT '$.ThuTu'
            ) J
            JOIN dbo.DM_Thuoc D ON D.IDCSKCB = @IDCSKCB AND D.ID = J.IDThuoc AND D.Active = 1;
        END;

        COMMIT;
        SELECT 200 AS Status, N'Lưu phác đồ thành công.' AS Message, @ID AS ID;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK;
        SELECT 500 AS Status, ERROR_MESSAGE() AS Message, @ID AS ID;
    END CATCH
END;

GO

/* ==================== STO_DM_PhacDo_Xoa ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_DM_PhacDo_Xoa
    @IDCSKCB BIGINT,
    @ID BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE dbo.DM_PhacDo SET Active = 0 WHERE IDCSKCB = @IDCSKCB AND ID = @ID;
    SELECT CASE WHEN @@ROWCOUNT > 0 THEN 200 ELSE 404 END AS Status,
           CASE WHEN @@ROWCOUNT > 0 THEN N'Xóa phác đồ thành công.' ELSE N'Không tìm thấy phác đồ.' END AS Message;
END;
GO

/* ==================== STO_QL_ThuTien_CapNhatTong ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_ThuTien_CapNhatTong @IDCSKCB BIGINT,@IDVaoVien BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE T SET TongTien=X.Tong,TienGiam=X.Giam,ThucThu=X.Thuc
    FROM dbo.QL_ThuTien T CROSS APPLY(SELECT ISNULL(SUM(ThanhTien),0) Tong,ISNULL(SUM(TienGiam),0) Giam,ISNULL(SUM(ThucThu),0) Thuc FROM dbo.QL_ThuTien_CT WHERE IDCSKCB=@IDCSKCB AND IDThuTien=T.ID) X
    WHERE T.IDCSKCB=@IDCSKCB AND T.IDVaoVien=@IDVaoVien;
END;
GO

/* ==================== STO_QL_BenhNhan_Xoa ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_BenhNhan_Xoa @IDCSKCB BIGINT,@IDBenhNhan BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    IF EXISTS(SELECT 1 FROM dbo.QL_VaoVien WHERE IDCSKCB=@IDCSKCB AND IDBenhNhan=@IDBenhNhan)
    BEGIN SELECT 409 AS Status,N'Bệnh nhân đã có dữ liệu lượt khám, không được xóa hồ sơ.' AS Message; RETURN; END;
    UPDATE dbo.QL_BenhNhan SET Active=0,NgayCapNhat=SYSDATETIME() WHERE IDCSKCB=@IDCSKCB AND ID=@IDBenhNhan AND Active=1;
    SELECT CASE WHEN @@ROWCOUNT>0 THEN 200 ELSE 404 END AS Status,CASE WHEN @@ROWCOUNT>0 THEN N'Xóa bệnh nhân thành công.' ELSE N'Không tìm thấy bệnh nhân.' END AS Message;
END;
GO

/* ==================== STO_QL_TiepNhan_BoCongKham ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_TiepNhan_BoCongKham
    @IDCSKCB BIGINT,
    @IDVaoVien BIGINT,
    @IDCongKhamCTJson NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRAN;

        DECLARE @TrangThaiKham TINYINT, @Active BIT;
        SELECT @TrangThaiKham = TrangThaiKham,
               @Active = Active
        FROM dbo.QL_VaoVien WITH (UPDLOCK, HOLDLOCK)
        WHERE IDCSKCB = @IDCSKCB
          AND ID = @IDVaoVien;

        IF @TrangThaiKham IS NULL
        BEGIN
            COMMIT;
            SELECT 404 AS Status, N'Không tìm thấy lượt khám.' AS Message, 0 AS HuyLuotKham, 0 AS SoLuongConLai;
            RETURN;
        END;

        IF @TrangThaiKham <> 0
        BEGIN
            COMMIT;
            SELECT 409 AS Status, N'Chỉ được bỏ công khám khi bệnh nhân chưa khám.' AS Message, 0 AS HuyLuotKham, 0 AS SoLuongConLai;
            RETURN;
        END;

        IF ISNULL(@Active, 0) <> 1
        BEGIN
            COMMIT;
            SELECT 404 AS Status, N'Không tìm thấy lượt khám đang hoạt động.' AS Message, 0 AS HuyLuotKham, 0 AS SoLuongConLai;
            RETURN;
        END;

        IF EXISTS
        (
            SELECT 1 FROM dbo.QL_ThuTien
            WHERE IDCSKCB = @IDCSKCB
              AND IDVaoVien = @IDVaoVien
              AND DaThu = 1
        )
        BEGIN
            COMMIT;
            SELECT 409 AS Status, N'Lượt khám đã thu tiền, không thể bỏ đăng ký công khám.' AS Message, 0 AS HuyLuotKham, 0 AS SoLuongConLai;
            RETURN;
        END;

        DECLARE @IDs TABLE (ID BIGINT PRIMARY KEY);
        IF ISJSON(@IDCongKhamCTJson)=1
        BEGIN
            INSERT INTO @IDs (ID)
            SELECT DISTINCT TRY_CONVERT(BIGINT, value)
            FROM OPENJSON(@IDCongKhamCTJson)
            WHERE TRY_CONVERT(BIGINT, value) IS NOT NULL;
        END;

        IF NOT EXISTS (SELECT 1 FROM @IDs)
        BEGIN
            COMMIT;
            SELECT 400 AS Status, N'Chưa chọn công khám nào để bỏ đăng ký.' AS Message, 0 AS HuyLuotKham, 0 AS SoLuongConLai;
            RETURN;
        END;

        DECLARE @IDCongKham BIGINT =
        (
            SELECT ID FROM dbo.QL_CongKham
            WHERE IDCSKCB = @IDCSKCB AND IDVaoVien = @IDVaoVien
        );

        IF @IDCongKham IS NULL
        BEGIN
            COMMIT;
            SELECT 404 AS Status, N'Lượt khám không có phiếu công khám.' AS Message, 0 AS HuyLuotKham, 0 AS SoLuongConLai;
            RETURN;
        END;

        IF EXISTS
        (
            SELECT 1
            FROM @IDs I
            WHERE NOT EXISTS
            (
                SELECT 1
                FROM dbo.QL_CongKham_CT CT
                WHERE CT.IDCSKCB = @IDCSKCB
                  AND CT.IDCongKham = @IDCongKham
                  AND CT.ID = I.ID
                  AND CT.Active = 1
            )
        )
        BEGIN
            COMMIT;
            SELECT 400 AS Status, N'Có công khám không thuộc lượt khám hoặc đã được bỏ trước đó.' AS Message, 0 AS HuyLuotKham, 0 AS SoLuongConLai;
            RETURN;
        END;

        DECLARE @IDThuTien BIGINT =
        (
            SELECT ID FROM dbo.QL_ThuTien
            WHERE IDCSKCB = @IDCSKCB AND IDVaoVien = @IDVaoVien
        );

        IF @IDThuTien IS NOT NULL
        BEGIN
            DELETE T
            FROM dbo.QL_ThuTien_CT T
            JOIN dbo.QL_CongKham_CT C
              ON C.IDCSKCB = T.IDCSKCB AND C.ID = T.IDCongKhamCT
            JOIN @IDs I ON I.ID = C.ID
            WHERE T.IDCSKCB = @IDCSKCB
              AND T.IDThuTien = @IDThuTien
              AND C.IDCongKham = @IDCongKham;
        END;

        DELETE CT
        FROM dbo.QL_CongKham_CT CT
        JOIN @IDs I ON I.ID = CT.ID
        WHERE CT.IDCSKCB = @IDCSKCB
          AND CT.IDCongKham = @IDCongKham;

        DECLARE @SoLuongConLai INT = (
            SELECT COUNT(1) FROM dbo.QL_CongKham_CT 
            WHERE IDCSKCB = @IDCSKCB AND IDCongKham = @IDCongKham AND Active = 1
        );

        IF @SoLuongConLai = 0
        BEGIN
            UPDATE dbo.QL_VaoVien
            SET DaChuyenKham = 0,
                TrangThaiKham = 0,
                ThoiGianChuyenKham = NULL,
                IDBacSiKham = NULL,
                BatDauKhamLuc = NULL,
                NgayCapNhat = SYSDATETIME()
            WHERE IDCSKCB = @IDCSKCB AND ID = @IDVaoVien;
        END;

        IF @IDThuTien IS NOT NULL
            EXEC dbo.STO_QL_ThuTien_CapNhatTong @IDCSKCB, @IDVaoVien;

        COMMIT;
        SELECT 200 AS Status,
               CASE WHEN @SoLuongConLai = 0
                    THEN N'Đã bỏ toàn bộ công khám. Lượt tiếp nhận đã được đưa về Chưa chuyển.'
                    ELSE N'Bỏ đăng ký công khám thành công.'
               END AS Message,
               0 AS HuyLuotKham,
               @SoLuongConLai AS SoLuongConLai;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK;
        SELECT 500 AS Status, ERROR_MESSAGE() AS Message, 0 AS HuyLuotKham, 0 AS SoLuongConLai;
    END CATCH
END;
GO

/* ==================== STO_QL_TiepNhan_BoDangKy ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_TiepNhan_BoDangKy
    @IDCSKCB BIGINT,
    @IDVaoVien BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRAN;

        DECLARE @TrangThai TINYINT,@Active BIT;
        SELECT @TrangThai=TrangThaiKham,@Active=Active
        FROM dbo.QL_VaoVien WITH(UPDLOCK,HOLDLOCK)
        WHERE IDCSKCB=@IDCSKCB AND ID=@IDVaoVien;

        IF @Active IS NULL OR @Active=0
        BEGIN
            ROLLBACK;
            SELECT 404 AS Status,N'Không tìm thấy lượt tiếp nhận đang hoạt động.' AS Message;
            RETURN;
        END;

        IF ISNULL(@TrangThai,0)<>0
           OR EXISTS(SELECT 1 FROM dbo.QL_PhieuSinhHieu WHERE IDCSKCB=@IDCSKCB AND IDVaoVien=@IDVaoVien)
           OR EXISTS(SELECT 1 FROM dbo.QL_ChanDoan_CT WHERE IDCSKCB=@IDCSKCB AND IDVaoVien=@IDVaoVien)
           OR EXISTS(SELECT 1 FROM dbo.QL_ChiDinh_CT WHERE IDCSKCB=@IDCSKCB AND IDVaoVien=@IDVaoVien AND Active=1)
           OR EXISTS(SELECT 1 FROM dbo.QL_ToaThuoc_CT WHERE IDCSKCB=@IDCSKCB AND IDVaoVien=@IDVaoVien AND Active=1)
        BEGIN
            ROLLBACK;
            SELECT 409 AS Status,N'Lượt khám đã phát sinh dữ liệu khám, không được xóa đăng ký tiếp nhận.' AS Message;
            RETURN;
        END;

        IF EXISTS(SELECT 1 FROM dbo.QL_ThuTien WHERE IDCSKCB=@IDCSKCB AND IDVaoVien=@IDVaoVien AND DaThu=1)
        BEGIN
            ROLLBACK;
            SELECT 409 AS Status,N'Lượt khám đã thu tiền, không thể xóa.' AS Message;
            RETURN;
        END;

        DELETE CT
        FROM dbo.QL_ThuTien_CT CT
        INNER JOIN dbo.QL_ThuTien T ON T.IDCSKCB=CT.IDCSKCB AND T.ID=CT.IDThuTien
        WHERE T.IDCSKCB=@IDCSKCB AND T.IDVaoVien=@IDVaoVien;

        DELETE dbo.QL_ThuTien WHERE IDCSKCB=@IDCSKCB AND IDVaoVien=@IDVaoVien;

        DELETE CT
        FROM dbo.QL_CongKham_CT CT
        INNER JOIN dbo.QL_CongKham C ON C.IDCSKCB=CT.IDCSKCB AND C.ID=CT.IDCongKham
        WHERE C.IDCSKCB=@IDCSKCB AND C.IDVaoVien=@IDVaoVien;

        DELETE dbo.QL_CongKham WHERE IDCSKCB=@IDCSKCB AND IDVaoVien=@IDVaoVien;

        UPDATE dbo.QL_VaoVien
        SET TrangThaiKham=3,Active=0,NgayCapNhat=SYSDATETIME()
        WHERE IDCSKCB=@IDCSKCB AND ID=@IDVaoVien;

        COMMIT;
        SELECT 200 AS Status,N'Đã hủy lượt tiếp nhận chưa phát sinh dữ liệu khám.' AS Message;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK;
        SELECT 500 AS Status,ERROR_MESSAGE() AS Message;
    END CATCH
END;
GO

/* ==================== STO_QL_TiepNhan_ChuyenKham ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_TiepNhan_ChuyenKham
    @IDCSKCB BIGINT,@IDVaoVien BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @IDBenhNhan BIGINT,@Ngay DATE,@NgayGioVaoVien DATETIME2(0),@TrangThaiKham TINYINT,@DaChuyenKham BIT;
    SELECT @IDBenhNhan=V.IDBenhNhan,@Ngay=V.Ngay,@NgayGioVaoVien=V.NgayGioVaoVien,
           @TrangThaiKham=V.TrangThaiKham,@DaChuyenKham=V.DaChuyenKham
    FROM dbo.QL_VaoVien V
    WHERE V.IDCSKCB=@IDCSKCB AND V.ID=@IDVaoVien AND V.Active=1;

    IF @IDBenhNhan IS NULL
    BEGIN SELECT 404 AS Status,N'Không tìm thấy lượt khám.' AS Message,@IDVaoVien AS IDVaoVien; RETURN; END;

    IF @TrangThaiKham>=2
    BEGIN SELECT 409 AS Status,N'Lượt khám đã hoàn tất hoặc đã hủy, không thể chuyển khám lại.' AS Message,@IDVaoVien AS IDVaoVien; RETURN; END;

    DECLARE @IDVaoVienTruoc BIGINT;
    SELECT TOP(1) @IDVaoVienTruoc=V.ID
    FROM dbo.QL_VaoVien V
    WHERE V.IDCSKCB=@IDCSKCB
      AND V.IDBenhNhan=@IDBenhNhan
      AND V.Ngay=@Ngay
      AND V.Active=1
      AND V.TrangThaiKham IN(0,1)
      AND V.ID<>@IDVaoVien
      AND (V.NgayGioVaoVien<@NgayGioVaoVien OR (V.NgayGioVaoVien=@NgayGioVaoVien AND V.ID<@IDVaoVien))
    ORDER BY V.NgayGioVaoVien,V.ID;

    IF @IDVaoVienTruoc IS NOT NULL
    BEGIN
        SELECT 409 AS Status,
               N'Bệnh nhân đã có một lượt khám trước đó trong ngày chưa hoàn tất. Không thể chuyển lượt tiếp nhận trùng; hãy tiếp tục lượt trước.' AS Message,
               @IDVaoVienTruoc AS IDVaoVien;
        RETURN;
    END;

    IF ISNULL(@DaChuyenKham,0)=1
    BEGIN SELECT 200 AS Status,N'Lượt khám đã được chuyển trước đó.' AS Message,@IDVaoVien AS IDVaoVien; RETURN; END;

    IF NOT EXISTS(SELECT 1 FROM dbo.QL_CongKham C JOIN dbo.QL_CongKham_CT CT ON CT.IDCSKCB=C.IDCSKCB AND CT.IDCongKham=C.ID AND CT.Active=1 WHERE C.IDCSKCB=@IDCSKCB AND C.IDVaoVien=@IDVaoVien)
    BEGIN SELECT 400 AS Status,N'Chưa chọn công khám.' AS Message,@IDVaoVien AS IDVaoVien; RETURN; END;

    UPDATE dbo.QL_VaoVien
    SET DaChuyenKham=1,ThoiGianChuyenKham=ISNULL(ThoiGianChuyenKham,SYSDATETIME()),NgayCapNhat=SYSDATETIME()
    WHERE IDCSKCB=@IDCSKCB AND ID=@IDVaoVien AND Active=1 AND TrangThaiKham IN(0,1);

    SELECT 200 AS Status,N'Chuyển khám thành công.' AS Message,@IDVaoVien AS IDVaoVien;
END;
GO

/* ==================== STO_QL_TiepNhan_DanhSach ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_TiepNhan_DanhSach
    @IDCSKCB BIGINT,
    @TuNgay DATE=NULL,
    @DenNgay DATE=NULL,
    @DaChuyenKham BIT=NULL,
    @TuKhoa NVARCHAR(200)=NULL,
    @Trang INT=1,
    @KichThuocTrang INT=25
AS
BEGIN
    SET NOCOUNT ON;
    SET @TuKhoa=NULLIF(LTRIM(RTRIM(@TuKhoa)),N'');
    IF @Trang IS NULL OR @Trang<1 SET @Trang=1;
    IF @KichThuocTrang IS NULL OR @KichThuocTrang<1 SET @KichThuocTrang=25;
    IF @KichThuocTrang>100 SET @KichThuocTrang=100;
    DECLARE @Offset BIGINT=(CONVERT(BIGINT,@Trang)-1)*@KichThuocTrang;

    IF @TuKhoa IS NOT NULL
    BEGIN
        ;WITH TimBN AS
        (
            SELECT TOP(500)
                B.*,
                CASE
                    WHEN B.MaBN=@TuKhoa OR B.SoCCCD=@TuKhoa OR B.DienThoai=@TuKhoa THEN 0
                    WHEN B.MaBN LIKE @TuKhoa+N'%' OR B.SoCCCD LIKE @TuKhoa+N'%' OR B.DienThoai LIKE @TuKhoa+N'%' THEN 1
                    WHEN B.HoTen LIKE @TuKhoa+N'%' THEN 2
                    ELSE 3
                END AS DiemTim
            FROM dbo.QL_BenhNhan B
            WHERE B.IDCSKCB=@IDCSKCB AND B.Active=1
              AND
              (
                  B.MaBN=@TuKhoa OR B.SoCCCD=@TuKhoa OR B.DienThoai=@TuKhoa
                  OR B.MaBN LIKE @TuKhoa+N'%'
                  OR B.SoCCCD LIKE @TuKhoa+N'%'
                  OR B.DienThoai LIKE @TuKhoa+N'%'
                  OR B.HoTen LIKE N'%'+@TuKhoa+N'%'
              )
            ORDER BY
                CASE
                    WHEN B.MaBN=@TuKhoa OR B.SoCCCD=@TuKhoa OR B.DienThoai=@TuKhoa THEN 0
                    WHEN B.MaBN LIKE @TuKhoa+N'%' OR B.SoCCCD LIKE @TuKhoa+N'%' OR B.DienThoai LIKE @TuKhoa+N'%' THEN 1
                    WHEN B.HoTen LIKE @TuKhoa+N'%' THEN 2
                    ELSE 3
                END,
                B.NgayTao DESC,B.ID DESC
        ),
        X AS
        (
            SELECT
                VV.ID AS IDVaoVien,VV.MaVaoVien,VV.NgayGioVaoVien,VV.Ngay,VV.SoThuTu,
                ISNULL(VV.DaChuyenKham,0) AS DaChuyenKham,ISNULL(VV.TrangThaiKham,0) AS TrangThaiKham,
                ISNULL(VV.SinhHieu,0) AS SinhHieu,ISNULL(VV.Kham,0) AS Kham,ISNULL(VV.KeToa,0) AS KeToa,
                VV.IDNguoiTiepNhan,
                B.ID AS IDBenhNhan,B.MaBN,B.HoTen,B.NgaySinh,B.IDGioiTinh,GT.TenGioiTinh,B.SoCCCD,B.DienThoai,B.DiaChi,
                B.IDDanToc,B.IDTinhThanh,B.IDPhuongXa,B.SoNhaTenDuong,B.QuocTich,B.NgheNghiep,
                B.GiamHo_MoiQuanHe,B.GiamHo_HoTen,B.GiamHo_DienThoai,B.GiamHo_SoCCCD,
                B.GhiChu AS GhiChuBenhNhan,VV.GhiChu AS GhiChuLanKham,
                CASE WHEN NULLIF(LTRIM(RTRIM(B.GhiChu)),N'') IS NULL THEN 0 ELSE 1 END AS CoGhiChu,
                B.DiemTim,
                COUNT(*) OVER() AS TongSoDong
            FROM TimBN B
            INNER JOIN dbo.DM_GioiTinh GT ON GT.ID=B.IDGioiTinh AND GT.Active=1
            OUTER APPLY
            (
                SELECT TOP(1)
                    V.ID,V.MaVaoVien,V.NgayGioVaoVien,V.Ngay,V.SoThuTu,V.DaChuyenKham,V.TrangThaiKham,
                    V.SinhHieu,V.Kham,V.KeToa,V.GhiChu,V.IDNguoiTiepNhan
                FROM dbo.QL_VaoVien V
                WHERE V.IDCSKCB=@IDCSKCB AND V.IDBenhNhan=B.ID AND V.Active=1
                ORDER BY V.NgayGioVaoVien DESC,V.ID DESC
            ) VV
        )
        SELECT *
        FROM X
        ORDER BY DiemTim,ISNULL(NgayGioVaoVien,CONVERT(DATETIME2(0),'19000101')) DESC,IDBenhNhan DESC
        OFFSET @Offset ROWS FETCH NEXT @KichThuocTrang ROWS ONLY
        OPTION(RECOMPILE);
        RETURN;
    END;

    SET @TuNgay=ISNULL(@TuNgay,CONVERT(DATE,SYSDATETIME()));
    SET @DenNgay=ISNULL(@DenNgay,@TuNgay);

    ;WITH X AS
    (
        SELECT
            VV.ID AS IDVaoVien,VV.MaVaoVien,VV.NgayGioVaoVien,VV.Ngay,VV.SoThuTu,
            VV.DaChuyenKham,VV.TrangThaiKham,VV.SinhHieu,VV.Kham,VV.KeToa,VV.IDNguoiTiepNhan,
            B.ID AS IDBenhNhan,B.MaBN,B.HoTen,B.NgaySinh,B.IDGioiTinh,GT.TenGioiTinh,B.SoCCCD,B.DienThoai,B.DiaChi,
            B.IDDanToc,B.IDTinhThanh,B.IDPhuongXa,B.SoNhaTenDuong,B.QuocTich,B.NgheNghiep,
            B.GiamHo_MoiQuanHe,B.GiamHo_HoTen,B.GiamHo_DienThoai,B.GiamHo_SoCCCD,
            B.GhiChu AS GhiChuBenhNhan,VV.GhiChu AS GhiChuLanKham,
            CASE WHEN NULLIF(LTRIM(RTRIM(B.GhiChu)),N'') IS NULL THEN 0 ELSE 1 END AS CoGhiChu,
            COUNT(*) OVER() AS TongSoDong
        FROM dbo.QL_VaoVien VV
        INNER JOIN dbo.QL_BenhNhan B ON B.IDCSKCB=VV.IDCSKCB AND B.ID=VV.IDBenhNhan
        INNER JOIN dbo.DM_GioiTinh GT ON GT.ID=B.IDGioiTinh AND GT.Active=1
        WHERE VV.IDCSKCB=@IDCSKCB
          AND VV.Active=1
          AND VV.Ngay BETWEEN @TuNgay AND @DenNgay
          AND (@DaChuyenKham IS NULL OR VV.DaChuyenKham=@DaChuyenKham)
    )
    SELECT *
    FROM X
    ORDER BY NgayGioVaoVien DESC,IDVaoVien DESC
    OFFSET @Offset ROWS FETCH NEXT @KichThuocTrang ROWS ONLY
    OPTION(RECOMPILE);
END;
GO

/* ==================== STO_QL_TiepNhan_LayCongKham ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_TiepNhan_LayCongKham
    @IDCSKCB BIGINT,
    @IDVaoVien BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT CKC.ID AS IDCongKhamCT,
           CKC.IDCongKham,
           CKC.IDDichVu,
           DV.MaDichVu,
           DV.TenDichVu,
           CKC.SoLuong,
           CKC.DonGia,
           CKC.ThanhTien,
           CKC.GhiChu,
           VV.DaChuyenKham,
           VV.TrangThaiKham,
           ISNULL(TT.DaThu, 0) AS DaThu
    FROM dbo.QL_CongKham_CT CKC
    JOIN dbo.QL_CongKham CK ON CK.IDCSKCB = CKC.IDCSKCB AND CK.ID = CKC.IDCongKham
    JOIN dbo.QL_VaoVien VV ON VV.IDCSKCB = CK.IDCSKCB AND VV.ID = CK.IDVaoVien
    JOIN dbo.DM_DichVu DV ON DV.IDCSKCB = CKC.IDCSKCB AND DV.ID = CKC.IDDichVu
    LEFT JOIN dbo.QL_ThuTien TT ON TT.IDCSKCB = VV.IDCSKCB AND TT.IDVaoVien = VV.ID
    WHERE CKC.IDCSKCB = @IDCSKCB AND CK.IDVaoVien = @IDVaoVien AND CKC.Active = 1
    ORDER BY CKC.ID;
END;
GO

/* ==================== STO_QL_BenhNhan_KiemTraTrung ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_BenhNhan_KiemTraTrung
    @IDCSKCB BIGINT,
    @IDBenhNhan BIGINT=NULL,
    @HoTen NVARCHAR(150),
    @NgaySinh DATE=NULL,
    @GioiTinh TINYINT=NULL,
    @SoCCCD NVARCHAR(20)=NULL,
    @DienThoai NVARCHAR(20)=NULL,
    @DiaChi NVARCHAR(500)=NULL
AS
BEGIN
    SET NOCOUNT ON;

    SET @HoTen=NULLIF(LTRIM(RTRIM(@HoTen)),N'');
    SET @SoCCCD=NULLIF(REPLACE(REPLACE(LTRIM(RTRIM(@SoCCCD)),N' ',N''),N'.',N''),N'');
    SET @DienThoai=NULLIF(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(@DienThoai)),N' ',N''),N'.',N''),N'-',N''),N'');
    SET @DiaChi=NULLIF(LTRIM(RTRIM(@DiaChi)),N'');

    ;WITH X AS
    (
        SELECT
            B.ID AS IDBenhNhan,B.MaBN,B.HoTen,B.NgaySinh,B.IDGioiTinh,B.SoCCCD,B.DienThoai,B.DiaChi,
            CAST
            (
                CASE
                    WHEN @SoCCCD IS NOT NULL
                     AND NULLIF(REPLACE(REPLACE(LTRIM(RTRIM(B.SoCCCD)),N' ',N''),N'.',N''),N'')=@SoCCCD
                        THEN 3
                    WHEN @HoTen IS NOT NULL AND @NgaySinh IS NOT NULL
                     AND LTRIM(RTRIM(B.HoTen))=@HoTen AND B.NgaySinh=@NgaySinh
                     AND @DienThoai IS NOT NULL
                     AND NULLIF(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(B.DienThoai)),N' ',N''),N'.',N''),N'-',N''),N'')=@DienThoai
                        THEN 2
                    WHEN @HoTen IS NOT NULL AND @NgaySinh IS NOT NULL AND @GioiTinh IS NOT NULL
                     AND LTRIM(RTRIM(B.HoTen))=@HoTen AND B.NgaySinh=@NgaySinh AND B.IDGioiTinh=@GioiTinh
                     AND @DiaChi IS NOT NULL AND LTRIM(RTRIM(ISNULL(B.DiaChi,N'')))=@DiaChi
                        THEN 2
                    WHEN @HoTen IS NOT NULL AND @NgaySinh IS NOT NULL AND @GioiTinh IS NOT NULL
                     AND LTRIM(RTRIM(B.HoTen))=@HoTen AND B.NgaySinh=@NgaySinh AND B.IDGioiTinh=@GioiTinh
                        THEN 1
                    ELSE 0
                END AS TINYINT
            ) AS MucDo
        FROM dbo.QL_BenhNhan B
        WHERE B.IDCSKCB=@IDCSKCB
          AND B.Active=1
          AND (@IDBenhNhan IS NULL OR B.ID<>@IDBenhNhan)
    )
    SELECT TOP(20)
        IDBenhNhan,MaBN,HoTen,NgaySinh,IDGioiTinh,SoCCCD,DienThoai,DiaChi,
        MucDo,
        CASE MucDo WHEN 3 THEN N'CHAC' WHEN 2 THEN N'CAO' ELSE N'GOI_Y' END AS MaMucDo
    FROM X
    WHERE MucDo>0
    ORDER BY MucDo DESC,IDBenhNhan DESC;
END;
GO

/* ==================== STO_QL_TiepNhan_Luu ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_TiepNhan_Luu
    @IDCSKCB            BIGINT,
    @IDBenhNhan         BIGINT = NULL,
    @IDVaoVien          BIGINT = NULL,
    @HoTen              NVARCHAR(150),
    @NgaySinh           DATE = NULL,
    @GioiTinh           TINYINT = 1,
    @SoCCCD             NVARCHAR(20) = NULL,
    @DienThoai          NVARCHAR(20) = NULL,
    @SoNhaTenDuong      NVARCHAR(255) = NULL,
    @IDPhuongXa         BIGINT = NULL,
    @IDTinhThanh        BIGINT = NULL,
    @DiaChi             NVARCHAR(500) = NULL,
    @IDDanToc            BIGINT = NULL,
    @QuocTich           NVARCHAR(50) = NULL,
    @NgheNghiep         NVARCHAR(100) = NULL,
    @GhiChuBenhNhan     NVARCHAR(500) = NULL,
    @GiamHo_MoiQuanHe   NVARCHAR(50) = NULL,
    @GiamHo_HoTen       NVARCHAR(150) = NULL,
    @GiamHo_DienThoai   NVARCHAR(20) = NULL,
    @GiamHo_SoCCCD      NVARCHAR(20) = NULL,
    @IDNguoiTiepNhan    BIGINT = NULL,
    @GhiChuLanKham      NVARCHAR(500) = NULL,
    @SoThuTu            INT = NULL,
    @ChuyenKham         BIT = 0,
    @CongKhamJson       NVARCHAR(MAX) = NULL,
    @TaoVaoVien         BIT = 1,
    @BoQuaCanhBaoTrung  BIT = 0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRAN;

        SET @HoTen=NULLIF(LTRIM(RTRIM(@HoTen)),N'');
        SET @SoCCCD=NULLIF(REPLACE(REPLACE(LTRIM(RTRIM(@SoCCCD)),N' ',N''),N'.',N''),N'');
        SET @DienThoai=NULLIF(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(@DienThoai)),N' ',N''),N'.',N''),N'-',N''),N'');
        SET @DiaChi=NULLIF(LTRIM(RTRIM(@DiaChi)),N'');

        IF @HoTen IS NULL THROW 56000,N'Họ tên bệnh nhân là bắt buộc.',1;
        SET @GioiTinh=ISNULL(@GioiTinh,1);
        IF NOT EXISTS(SELECT 1 FROM dbo.DM_GioiTinh WHERE ID=@GioiTinh AND Active=1)
            THROW 56000,N'Giới tính không hợp lệ.',1;

        IF @NgaySinh IS NOT NULL AND @NgaySinh>CONVERT(DATE,SYSDATETIME())
            THROW 56000,N'Ngày sinh không được lớn hơn ngày hiện tại.',1;

        IF @IDBenhNhan IS NULL OR @IDBenhNhan<=0
        BEGIN
            DECLARE @IDBenhNhanTrung BIGINT,@MucDoTrung TINYINT;

            ;WITH X AS
            (
                SELECT
                    B.ID,
                    CAST
                    (
                        CASE
                            WHEN @SoCCCD IS NOT NULL
                             AND NULLIF(REPLACE(REPLACE(LTRIM(RTRIM(B.SoCCCD)),N' ',N''),N'.',N''),N'')=@SoCCCD
                                THEN 3
                            WHEN @NgaySinh IS NOT NULL
                             AND LTRIM(RTRIM(B.HoTen))=@HoTen AND B.NgaySinh=@NgaySinh
                             AND @DienThoai IS NOT NULL
                             AND NULLIF(REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(B.DienThoai)),N' ',N''),N'.',N''),N'-',N''),N'')=@DienThoai
                                THEN 2
                            WHEN @NgaySinh IS NOT NULL
                             AND LTRIM(RTRIM(B.HoTen))=@HoTen AND B.NgaySinh=@NgaySinh AND B.IDGioiTinh=@GioiTinh
                             AND @DiaChi IS NOT NULL AND LTRIM(RTRIM(ISNULL(B.DiaChi,N'')))=@DiaChi
                                THEN 2
                            WHEN @NgaySinh IS NOT NULL
                             AND LTRIM(RTRIM(B.HoTen))=@HoTen AND B.NgaySinh=@NgaySinh AND B.IDGioiTinh=@GioiTinh
                                THEN 1
                            ELSE 0
                        END AS TINYINT
                    ) AS MucDo
                FROM dbo.QL_BenhNhan B WITH(UPDLOCK,HOLDLOCK)
                WHERE B.IDCSKCB=@IDCSKCB AND B.Active=1
            )
            SELECT TOP(1) @IDBenhNhanTrung=ID,@MucDoTrung=MucDo
            FROM X WHERE MucDo>0
            ORDER BY MucDo DESC,ID DESC;

            IF @MucDoTrung=3
            BEGIN
                ROLLBACK;
                SELECT 409 AS Status,
                       N'CCCD đã tồn tại ở một hồ sơ bệnh nhân khác. Hãy chọn hồ sơ hiện có.' AS Message,
                       @IDBenhNhanTrung AS IDBenhNhan,
                       CAST(NULL AS BIGINT) AS IDVaoVien,
                       CAST(0 AS BIT) AS CanhBaoTrung,
                       N'CHAC' AS MucDoTrung;
                RETURN;
            END;

            IF @MucDoTrung=2 AND ISNULL(@BoQuaCanhBaoTrung,0)=0
            BEGIN
                ROLLBACK;
                SELECT 409 AS Status,
                       N'Có hồ sơ rất giống (họ tên + ngày sinh + SĐT hoặc địa chỉ). Hãy đối chiếu trước khi tạo hồ sơ mới.' AS Message,
                       @IDBenhNhanTrung AS IDBenhNhan,
                       CAST(NULL AS BIGINT) AS IDVaoVien,
                       CAST(1 AS BIT) AS CanhBaoTrung,
                       N'CAO' AS MucDoTrung;
                RETURN;
            END;

            DECLARE @SeqBN BIGINT=NEXT VALUE FOR dbo.SEQ_MaBN;
            DECLARE @MaBN NVARCHAR(30)=dbo.FN_QLPM_FormatMaBN(@SeqBN);

            INSERT dbo.QL_BenhNhan
            (
                IDCSKCB,MaBN,HoTen,NgaySinh,IDGioiTinh,SoCCCD,DienThoai,
                SoNhaTenDuong,IDPhuongXa,IDTinhThanh,DiaChi,IDDanToc,QuocTich,NgheNghiep,GhiChu,
                GiamHo_MoiQuanHe,GiamHo_HoTen,GiamHo_DienThoai,GiamHo_SoCCCD,Active
            )
            VALUES
            (
                @IDCSKCB,@MaBN,@HoTen,@NgaySinh,@GioiTinh,@SoCCCD,@DienThoai,
                @SoNhaTenDuong,@IDPhuongXa,@IDTinhThanh,@DiaChi,@IDDanToc,@QuocTich,@NgheNghiep,@GhiChuBenhNhan,
                @GiamHo_MoiQuanHe,@GiamHo_HoTen,@GiamHo_DienThoai,@GiamHo_SoCCCD,1
            );
            SET @IDBenhNhan=SCOPE_IDENTITY();
        END
        ELSE
        BEGIN
            UPDATE dbo.QL_BenhNhan
            SET HoTen=@HoTen,NgaySinh=@NgaySinh,IDGioiTinh=@GioiTinh,
                SoCCCD=@SoCCCD,DienThoai=@DienThoai,
                SoNhaTenDuong=@SoNhaTenDuong,IDPhuongXa=@IDPhuongXa,IDTinhThanh=@IDTinhThanh,DiaChi=@DiaChi,
                IDDanToc=@IDDanToc,QuocTich=COALESCE(NULLIF(@QuocTich,N''),QuocTich),
                NgheNghiep=COALESCE(NULLIF(@NgheNghiep,N''),NgheNghiep),
                GhiChu=@GhiChuBenhNhan,GiamHo_MoiQuanHe=@GiamHo_MoiQuanHe,GiamHo_HoTen=@GiamHo_HoTen,
                GiamHo_DienThoai=@GiamHo_DienThoai,GiamHo_SoCCCD=@GiamHo_SoCCCD,NgayCapNhat=SYSDATETIME()
            WHERE IDCSKCB=@IDCSKCB AND ID=@IDBenhNhan AND Active=1;

            IF @@ROWCOUNT=0 THROW 56000,N'Không tìm thấy bệnh nhân.',1;
        END;

        IF (@IDVaoVien IS NULL OR @IDVaoVien<=0) AND @TaoVaoVien=0
        BEGIN
            COMMIT;
            SELECT 200 AS Status,N'Lưu thông tin bệnh nhân thành công.' AS Message,@IDBenhNhan AS IDBenhNhan,
                   CAST(NULL AS BIGINT) AS IDVaoVien,CAST(0 AS BIT) AS CanhBaoTrung,CAST(NULL AS NVARCHAR(20)) AS MucDoTrung;
            RETURN;
        END;

        DECLARE @NgayHienTai DATE=CONVERT(DATE,SYSDATETIME());

        IF @IDVaoVien IS NULL OR @IDVaoVien<=0
        BEGIN
            DECLARE @IDVaoVienDangMo BIGINT;
            SELECT TOP(1) @IDVaoVienDangMo=V.ID
            FROM dbo.QL_VaoVien V WITH(UPDLOCK,HOLDLOCK)
            WHERE V.IDCSKCB=@IDCSKCB
              AND V.IDBenhNhan=@IDBenhNhan
              AND V.Ngay=@NgayHienTai
              AND V.Active=1
              AND V.TrangThaiKham IN(0,1)
            ORDER BY V.NgayGioVaoVien,V.ID;

            IF @IDVaoVienDangMo IS NOT NULL
            BEGIN
                ROLLBACK;
                SELECT 409 AS Status,
                       N'Bệnh nhân đã có lượt khám chưa hoàn tất trong ngày. Không được tiếp nhận lại; hãy tiếp tục lượt hiện tại.' AS Message,
                       @IDBenhNhan AS IDBenhNhan,@IDVaoVienDangMo AS IDVaoVien,
                       CAST(0 AS BIT) AS CanhBaoTrung,CAST(NULL AS NVARCHAR(20)) AS MucDoTrung;
                RETURN;
            END;

            IF @SoThuTu IS NULL OR @SoThuTu<=0
            BEGIN
                DECLARE @LockResult INT;
                DECLARE @LockName NVARCHAR(255)=N'QLPM_STT_'+CONVERT(NVARCHAR(30),@IDCSKCB)+N'_'+CONVERT(NVARCHAR(8),@NgayHienTai,112);
                EXEC @LockResult=sys.sp_getapplock @Resource=@LockName,@LockMode='Exclusive',@LockOwner='Transaction',@LockTimeout=5000;
                IF @LockResult<0 THROW 56000,N'Không thể cấp số thứ tự tiếp nhận, vui lòng thử lại.',1;

                SELECT @SoThuTu=ISNULL(MAX(SoThuTu),0)+1
                FROM dbo.QL_VaoVien
                WHERE IDCSKCB=@IDCSKCB AND Ngay=@NgayHienTai;
            END;

            DECLARE @SeqVV BIGINT=NEXT VALUE FOR dbo.SEQ_MaVaoVien;
            DECLARE @MaVV NVARCHAR(30)=N'VV'+CASE
                WHEN @SeqVV<1000000 THEN RIGHT(N'000000'+CONVERT(NVARCHAR(20),@SeqVV),6)
                ELSE CONVERT(NVARCHAR(20),@SeqVV) END;

            INSERT dbo.QL_VaoVien
            (
                IDCSKCB,MaVaoVien,IDBenhNhan,Ngay,NgayGioVaoVien,SoThuTu,
                IDNguoiTiepNhan,GhiChu,DaChuyenKham,ThoiGianChuyenKham,TrangThaiKham,Active
            )
            VALUES
            (
                @IDCSKCB,@MaVV,@IDBenhNhan,@NgayHienTai,SYSDATETIME(),@SoThuTu,
                @IDNguoiTiepNhan,@GhiChuLanKham,0,NULL,0,1
            );
            SET @IDVaoVien=SCOPE_IDENTITY();

            INSERT dbo.QL_CongKham(IDCSKCB,IDVaoVien,IDNguoiTao) VALUES(@IDCSKCB,@IDVaoVien,@IDNguoiTiepNhan);
            INSERT dbo.QL_ThuTien(IDCSKCB,IDVaoVien) VALUES(@IDCSKCB,@IDVaoVien);
        END
        ELSE
        BEGIN
            DECLARE @DaChuyen BIT,@TrangThai TINYINT,@DaThu BIT;
            SELECT @DaChuyen=V.DaChuyenKham,@TrangThai=V.TrangThaiKham
            FROM dbo.QL_VaoVien V WITH(UPDLOCK,HOLDLOCK)
            WHERE V.IDCSKCB=@IDCSKCB AND V.ID=@IDVaoVien AND V.IDBenhNhan=@IDBenhNhan AND V.Active=1;

            IF @TrangThai IS NULL THROW 56000,N'Không tìm thấy lượt khám.',1;

            SELECT @DaThu=T.DaThu FROM dbo.QL_ThuTien T
            WHERE T.IDCSKCB=@IDCSKCB AND T.IDVaoVien=@IDVaoVien;

            IF ISNULL(@DaThu,0)=1 AND @CongKhamJson IS NOT NULL
                THROW 56000,N'Lượt khám đã thu tiền, không được thay đổi công khám.',1;

            IF ISNULL(@DaChuyen,0)=1 AND @CongKhamJson IS NOT NULL
                THROW 56000,N'Lượt khám đã chuyển khám, không được sửa công khám tại tiếp nhận.',1;

            UPDATE dbo.QL_VaoVien
            SET SoThuTu=COALESCE(@SoThuTu,SoThuTu),GhiChu=@GhiChuLanKham,NgayCapNhat=SYSDATETIME()
            WHERE IDCSKCB=@IDCSKCB AND ID=@IDVaoVien;
        END;

        DECLARE @IDCongKham BIGINT=(SELECT ID FROM dbo.QL_CongKham WHERE IDCSKCB=@IDCSKCB AND IDVaoVien=@IDVaoVien);
        DECLARE @IDThuTien BIGINT=(SELECT ID FROM dbo.QL_ThuTien WHERE IDCSKCB=@IDCSKCB AND IDVaoVien=@IDVaoVien);

        IF @CongKhamJson IS NOT NULL
        BEGIN
            IF ISJSON(@CongKhamJson)<>1 THROW 56000,N'Dữ liệu công khám không hợp lệ.',1;

            DECLARE @CK TABLE(IDDichVu BIGINT PRIMARY KEY,SoLuong DECIMAL(10,2),GhiChu NVARCHAR(500));
            INSERT @CK(IDDichVu,SoLuong,GhiChu)
            SELECT
                COALESCE(J.IDDichVu,J.id_dich_vu),
                COALESCE(J.SoLuong,J.so_luong,1),
                COALESCE(J.GhiChu,J.ghi_chu)
            FROM OPENJSON(@CongKhamJson)
            WITH
            (
                IDDichVu BIGINT '$.IDDichVu',id_dich_vu BIGINT '$.id_dich_vu',
                SoLuong DECIMAL(10,2) '$.SoLuong',so_luong DECIMAL(10,2) '$.so_luong',
                GhiChu NVARCHAR(500) '$.GhiChu',ghi_chu NVARCHAR(500) '$.ghi_chu'
            ) J
            WHERE COALESCE(J.IDDichVu,J.id_dich_vu) IS NOT NULL;

            IF EXISTS(SELECT 1 FROM @CK WHERE SoLuong<=0)
                THROW 56000,N'Số lượng công khám phải lớn hơn 0.',1;

            IF EXISTS
            (
                SELECT 1 FROM @CK X
                WHERE NOT EXISTS(SELECT 1 FROM dbo.DM_DichVu D WHERE D.IDCSKCB=@IDCSKCB AND D.ID=X.IDDichVu AND D.Active=1)
            )
                THROW 56000,N'Có công khám không tồn tại hoặc đã ngừng hoạt động.',1;

            DELETE T
            FROM dbo.QL_ThuTien_CT T
            INNER JOIN dbo.QL_CongKham_CT C ON C.IDCSKCB=T.IDCSKCB AND C.ID=T.IDCongKhamCT
            WHERE T.IDCSKCB=@IDCSKCB AND T.IDThuTien=@IDThuTien AND C.IDCongKham=@IDCongKham;

            DELETE dbo.QL_CongKham_CT WHERE IDCSKCB=@IDCSKCB AND IDCongKham=@IDCongKham;

            INSERT dbo.QL_CongKham_CT(IDCSKCB,IDCongKham,IDDichVu,SoLuong,DonGia,ThanhTien,GhiChu,Active)
            SELECT @IDCSKCB,@IDCongKham,D.ID,X.SoLuong,D.DonGia,X.SoLuong*D.DonGia,X.GhiChu,1
            FROM @CK X
            INNER JOIN dbo.DM_DichVu D ON D.IDCSKCB=@IDCSKCB AND D.ID=X.IDDichVu AND D.Active=1;

            INSERT dbo.QL_ThuTien_CT(IDCSKCB,IDThuTien,IDCongKhamCT,SoLuong,DonGia,ThanhTien,TienGiam,ThucThu,DaThu)
            SELECT @IDCSKCB,@IDThuTien,ID,SoLuong,DonGia,ThanhTien,0,ThanhTien,0
            FROM dbo.QL_CongKham_CT
            WHERE IDCSKCB=@IDCSKCB AND IDCongKham=@IDCongKham AND Active=1;

            EXEC dbo.STO_QL_ThuTien_CapNhatTong @IDCSKCB,@IDVaoVien;
        END;

        IF @ChuyenKham=1
        BEGIN
            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.QL_CongKham C
                INNER JOIN dbo.QL_CongKham_CT CT
                  ON CT.IDCSKCB=C.IDCSKCB AND CT.IDCongKham=C.ID AND CT.Active=1
                WHERE C.IDCSKCB=@IDCSKCB AND C.IDVaoVien=@IDVaoVien
            )
                THROW 56000,N'Phải chọn ít nhất một công khám trước khi chuyển khám.',1;

            UPDATE dbo.QL_VaoVien
            SET DaChuyenKham=1,
                ThoiGianChuyenKham=COALESCE(ThoiGianChuyenKham,SYSDATETIME()),
                NgayCapNhat=SYSDATETIME()
            WHERE IDCSKCB=@IDCSKCB AND ID=@IDVaoVien;
        END;

        COMMIT;
        SELECT 200 AS Status,
               CASE WHEN @ChuyenKham=1 THEN N'Tiếp nhận và chuyển khám thành công.' ELSE N'Lưu tiếp nhận thành công.' END AS Message,
               @IDBenhNhan AS IDBenhNhan,@IDVaoVien AS IDVaoVien,
               CAST(0 AS BIT) AS CanhBaoTrung,CAST(NULL AS NVARCHAR(20)) AS MucDoTrung;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK;
        SELECT 400 AS Status,ERROR_MESSAGE() AS Message,
               @IDBenhNhan AS IDBenhNhan,@IDVaoVien AS IDVaoVien,
               CAST(0 AS BIT) AS CanhBaoTrung,CAST(NULL AS NVARCHAR(20)) AS MucDoTrung;
    END CATCH
END;

GO

/* ==================== STO_QL_Kham_CapNhatDangKham ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_Kham_CapNhatDangKham
    @IDCSKCB BIGINT,
    @IDVaoVien BIGINT,
    @IDBacSi BIGINT,
    @LaQuanTri BIT=0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRAN;

        DECLARE @TrangThai TINYINT,@Active BIT,@DaChuyen BIT,@BSDangKham BIGINT;
        SELECT @TrangThai=TrangThaiKham,@Active=Active,@DaChuyen=DaChuyenKham,@BSDangKham=IDBacSiKham
        FROM dbo.QL_VaoVien WITH(UPDLOCK,HOLDLOCK)
        WHERE IDCSKCB=@IDCSKCB AND ID=@IDVaoVien;

        IF @Active IS NULL OR @Active=0
        BEGIN ROLLBACK; SELECT 404 AS Status,N'Không tìm thấy lượt khám.' AS Message; RETURN; END;
        IF ISNULL(@DaChuyen,0)<>1
        BEGIN ROLLBACK; SELECT 409 AS Status,N'Lượt khám chưa được chuyển khám.' AS Message; RETURN; END;
        IF @TrangThai=3
           OR (@TrangThai=2 AND ISNULL(@LaQuanTri,0)=0)
        BEGIN ROLLBACK; SELECT 409 AS Status,N'Lượt khám đã kết thúc hoặc đã hủy.' AS Message; RETURN; END;
        IF ISNULL(@LaQuanTri,0)=0
           AND @TrangThai=1
           AND @BSDangKham IS NOT NULL
           AND @BSDangKham<>@IDBacSi
        BEGIN ROLLBACK; SELECT 409 AS Status,N'Bệnh nhân đang được bác sĩ khác khám.' AS Message; RETURN; END;

        UPDATE dbo.QL_VaoVien
        SET TrangThaiKham=CASE
                WHEN @TrangThai=2 AND ISNULL(@LaQuanTri,0)=1 THEN 2
                ELSE 1
            END,
            IDBacSiKham=CASE
                WHEN ISNULL(@LaQuanTri,0)=1 AND @BSDangKham IS NOT NULL THEN @BSDangKham
                ELSE COALESCE(IDBacSiKham,@IDBacSi)
            END,
            BatDauKhamLuc=COALESCE(BatDauKhamLuc,SYSDATETIME()),
            NgayCapNhat=SYSDATETIME()
        WHERE IDCSKCB=@IDCSKCB AND ID=@IDVaoVien;

        COMMIT;
        SELECT 200 AS Status,
               CASE WHEN @TrangThai=2 AND ISNULL(@LaQuanTri,0)=1
                    THEN N'Đã mở lượt đã khám cho quản trị chỉnh sửa.'
                    ELSE N'Đã cập nhật trạng thái đang khám.'
               END AS Message;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK;
        SELECT 409 AS Status,ERROR_MESSAGE() AS Message;
    END CATCH
END;

GO

/* ==================== STO_QL_Kham_ChiTietLanKhamCu ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_Kham_ChiTietLanKhamCu
    @IDCSKCB BIGINT,
    @IDVaoVienCu BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT ID, MaVaoVien, TrieuChung, HuongDieuTri, GhiChu, NgayTaiKham, IDPhacDo, MaPDGoc
    FROM dbo.QL_VaoVien
    WHERE IDCSKCB = @IDCSKCB AND ID = @IDVaoVienCu;

    DECLARE @IDPhieu BIGINT =
    (
        SELECT TOP 1 ID
        FROM dbo.QL_PhieuSinhHieu
        WHERE IDCSKCB = @IDCSKCB AND IDVaoVien = @IDVaoVienCu
        ORDER BY NgayGioDo DESC, ID DESC
    );

    SELECT CT.IDTriSoSinhHieu, DM.MaTriSo, DM.TenTriSo, DM.DonViTinh, CT.GiaTri
    FROM dbo.QL_PhieuSinhHieu_CT CT
    JOIN dbo.DM_TriSoSinhHieu DM ON DM.IDCSKCB = CT.IDCSKCB AND DM.ID = CT.IDTriSoSinhHieu
    WHERE CT.IDCSKCB = @IDCSKCB AND CT.IDPhieuSinhHieu = @IDPhieu
    ORDER BY ISNULL(DM.ThuTu, 999), DM.ID;

    SELECT CD.IDICD10, CD.MaBenh, CD.TenBenh, CD.BanDau, CD.BenhChinh, CD.BenhKhac, CD.GhiChu
    FROM dbo.QL_ChanDoan_CT CD
    WHERE CD.IDCSKCB = @IDCSKCB AND CD.IDVaoVien = @IDVaoVienCu
    ORDER BY ISNULL(CD.ThuTu, 999), CD.ID;

    SELECT
        C.ID AS IDChiDinhCT,C.IDDichVu,D.MaDichVu,D.TenDichVu,C.SoLuong,C.DonGia,
        C.GuiNgoai,C.NoiGuiNgoai,C.GhiChu,
        ISNULL(P.TrangThai,0) AS TrangThaiKetQua,
        COALESCE(P.LoaiKetQua,D.LoaiKetQua,0) AS LoaiKetQua,
        P.ID AS IDPhieuKetQua,P.NgayGioKetQua,
        CASE
            WHEN P.LoaiKetQua=1 THEN
                ISNULL
                (
                    (
                        SELECT STRING_AGG
                        (
                            CONCAT(T.TenTriSo,N': ',K.GiaTri,
                                CASE WHEN NULLIF(K.DonViTinh,N'') IS NULL THEN N'' ELSE N' '+K.DonViTinh END,
                                CASE K.DanhGia WHEN 1 THEN N' ↓' WHEN 2 THEN N' ↑' WHEN 3 THEN N' !' ELSE N'' END
                            ),N'; '
                        )
                        FROM dbo.QL_CLS_KetQuaXN_CT K
                        INNER JOIN dbo.QL_CLS_DM_TriSoXN T
                          ON T.IDCSKCB=K.IDCSKCB AND T.ID=K.IDTriSoXN
                        WHERE K.IDCSKCB=P.IDCSKCB AND K.IDPhieuKetQua=P.ID
                    ),N''
                )
            ELSE COALESCE(NULLIF(P.KetLuan,N''),NULLIF(P.MoTa,N''),N'')
        END AS TomTatKetQua
    FROM dbo.QL_ChiDinh_CT C
    JOIN dbo.DM_DichVu D ON D.IDCSKCB = C.IDCSKCB AND D.ID = C.IDDichVu
    LEFT JOIN dbo.QL_CLS_PhieuKetQua P
      ON P.IDCSKCB=C.IDCSKCB AND P.IDChiDinhCT=C.ID AND P.Active=1
    WHERE C.IDCSKCB = @IDCSKCB AND C.IDVaoVien = @IDVaoVienCu AND C.Active = 1
    ORDER BY C.ID;

    SELECT
        T.IDThuoc, M.MaThuoc, M.TenThuoc, COALESCE(DVT.TenDVT,M.DonViTinh) AS DonViTinh, M.HamLuong, M.HoatChat,
        T.SoNgay, T.Sang, T.Trua, T.Chieu, T.Toi, T.LieuDung, T.CachDung,
        T.SoLuong, T.DonGia, T.ThanhTien, T.ID AS IDToaThuocCTGoc
    FROM dbo.QL_ToaThuoc_CT T
    JOIN dbo.DM_Thuoc M ON M.IDCSKCB = T.IDCSKCB AND M.ID = T.IDThuoc
    LEFT JOIN dbo.DM_DonViTinh DVT ON DVT.IDCSKCB=M.IDCSKCB AND DVT.ID=M.IDDonViTinh
    WHERE T.IDCSKCB = @IDCSKCB AND T.IDVaoVien = @IDVaoVienCu AND T.Active = 1
    ORDER BY ISNULL(T.ThuTu, 999), T.ID;
END;
GO

/* ==================== STO_QL_Kham_ChonBenhNhan ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_Kham_ChonBenhNhan
    @IDCSKCB BIGINT,
    @IDVaoVien BIGINT,
    @IDBacSi BIGINT,
    @LaQuanTri BIT=0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRAN;

        DECLARE @TrangThai TINYINT,@DaChuyen BIT,@BSDangKham BIGINT;
        SELECT @TrangThai=TrangThaiKham,@DaChuyen=DaChuyenKham,@BSDangKham=IDBacSiKham
        FROM dbo.QL_VaoVien WITH(UPDLOCK,HOLDLOCK)
        WHERE IDCSKCB=@IDCSKCB AND ID=@IDVaoVien AND Active=1;

        IF @TrangThai IS NULL
        BEGIN ROLLBACK; SELECT 404 AS Status,N'Không tìm thấy lượt khám.' AS Message; RETURN; END;
        IF ISNULL(@DaChuyen,0)=0
        BEGIN ROLLBACK; SELECT 409 AS Status,N'Bệnh nhân chưa được chuyển khám.' AS Message; RETURN; END;
        IF @TrangThai=3
        BEGIN ROLLBACK; SELECT 409 AS Status,N'Lượt khám đã bị hủy.' AS Message; RETURN; END;

        IF ISNULL(@LaQuanTri,0)=0
           AND @TrangThai=1
           AND @BSDangKham IS NOT NULL
           AND @BSDangKham<>@IDBacSi
        BEGIN ROLLBACK; SELECT 409 AS Status,N'Bệnh nhân đang được bác sĩ khác khám.' AS Message; RETURN; END;

        IF @TrangThai=0
        BEGIN
            UPDATE dbo.QL_VaoVien
            SET TrangThaiKham=1,
                IDBacSiKham=@IDBacSi,
                BatDauKhamLuc=COALESCE(BatDauKhamLuc,SYSDATETIME()),
                NgayCapNhat=SYSDATETIME()
            WHERE IDCSKCB=@IDCSKCB AND ID=@IDVaoVien;
        END
        ELSE IF @TrangThai=1 AND @BSDangKham IS NULL
        BEGIN
            UPDATE dbo.QL_VaoVien
            SET IDBacSiKham=@IDBacSi,
                BatDauKhamLuc=COALESCE(BatDauKhamLuc,SYSDATETIME()),
                NgayCapNhat=SYSDATETIME()
            WHERE IDCSKCB=@IDCSKCB AND ID=@IDVaoVien;
        END;

        COMMIT;

        SELECT 200 AS Status,N'Tải bệnh nhân thành công.' AS Message;

        SELECT VV.*,BN.MaBN,BN.HoTen,BN.NgaySinh,BN.IDGioiTinh,GT.TenGioiTinh,BN.SoCCCD,BN.DienThoai,BN.DiaChi,BN.GhiChu AS GhiChuBenhNhan
        FROM dbo.QL_VaoVien VV
        INNER JOIN dbo.QL_BenhNhan BN ON BN.IDCSKCB=VV.IDCSKCB AND BN.ID=VV.IDBenhNhan
        INNER JOIN dbo.DM_GioiTinh GT ON GT.ID=BN.IDGioiTinh AND GT.Active=1
        WHERE VV.IDCSKCB=@IDCSKCB AND VV.ID=@IDVaoVien;

        DECLARE @IDPhieu BIGINT=
        (
            SELECT TOP(1) ID
            FROM dbo.QL_PhieuSinhHieu
            WHERE IDCSKCB=@IDCSKCB AND IDVaoVien=@IDVaoVien
            ORDER BY NgayGioDo DESC,ID DESC
        );

        SELECT P.ID AS IDPhieuSinhHieu,P.NgayGioDo,CT.IDTriSoSinhHieu,DM.MaTriSo,DM.TenTriSo,DM.DonViTinh,CT.GiaTri
        FROM dbo.QL_PhieuSinhHieu P
        INNER JOIN dbo.QL_PhieuSinhHieu_CT CT ON CT.IDCSKCB=P.IDCSKCB AND CT.IDPhieuSinhHieu=P.ID
        INNER JOIN dbo.DM_TriSoSinhHieu DM ON DM.IDCSKCB=CT.IDCSKCB AND DM.ID=CT.IDTriSoSinhHieu
        WHERE P.IDCSKCB=@IDCSKCB AND P.ID=@IDPhieu
        ORDER BY ISNULL(DM.ThuTu,999),DM.ID;

        SELECT * FROM dbo.QL_ChanDoan_CT
        WHERE IDCSKCB=@IDCSKCB AND IDVaoVien=@IDVaoVien
        ORDER BY ISNULL(ThuTu,999),ID;

        SELECT
            C.*,D.MaDichVu,D.TenDichVu,D.DonViTinh,
            ISNULL(P.TrangThai,0) AS TrangThaiKetQua,
            COALESCE(P.LoaiKetQua,D.LoaiKetQua,0) AS LoaiKetQua,
            P.ID AS IDPhieuKetQua,P.NgayGioKetQua,
            CASE
                WHEN P.LoaiKetQua=1 THEN ISNULL
                (
                    (
                        SELECT STRING_AGG
                        (
                            CONCAT(T.TenTriSo,N': ',K.GiaTri,
                                CASE WHEN NULLIF(K.DonViTinh,N'') IS NULL THEN N'' ELSE N' '+K.DonViTinh END,
                                CASE K.DanhGia WHEN 1 THEN N' ↓' WHEN 2 THEN N' ↑' WHEN 3 THEN N' !' ELSE N'' END
                            ),N'; '
                        )
                        FROM dbo.QL_CLS_KetQuaXN_CT K
                        INNER JOIN dbo.QL_CLS_DM_TriSoXN T ON T.IDCSKCB=K.IDCSKCB AND T.ID=K.IDTriSoXN
                        WHERE K.IDCSKCB=P.IDCSKCB AND K.IDPhieuKetQua=P.ID
                    ),N''
                )
                ELSE COALESCE(NULLIF(P.KetLuan,N''),NULLIF(P.MoTa,N''),N'')
            END AS TomTatKetQua
        FROM dbo.QL_ChiDinh_CT C
        INNER JOIN dbo.DM_DichVu D ON D.IDCSKCB=C.IDCSKCB AND D.ID=C.IDDichVu
        LEFT JOIN dbo.QL_CLS_PhieuKetQua P
          ON P.IDCSKCB=C.IDCSKCB AND P.IDChiDinhCT=C.ID AND P.Active=1
        WHERE C.IDCSKCB=@IDCSKCB AND C.IDVaoVien=@IDVaoVien AND C.Active=1
        ORDER BY C.ID;

        SELECT T.*,DM.MaThuoc,DM.TenThuoc,COALESCE(DVT.TenDVT,DM.DonViTinh) AS DonViTinh,DM.HamLuong,DM.HoatChat
        FROM dbo.QL_ToaThuoc_CT T
        INNER JOIN dbo.DM_Thuoc DM ON DM.IDCSKCB=T.IDCSKCB AND DM.ID=T.IDThuoc
        LEFT JOIN dbo.DM_DonViTinh DVT ON DVT.IDCSKCB=DM.IDCSKCB AND DVT.ID=DM.IDDonViTinh
        WHERE T.IDCSKCB=@IDCSKCB AND T.IDVaoVien=@IDVaoVien AND T.Active=1
        ORDER BY ISNULL(T.ThuTu,999),T.ID;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK;
        SELECT 409 AS Status,ERROR_MESSAGE() AS Message;
    END CATCH
END;

GO

/* ==================== STO_QL_Kham_DanhSach ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_Kham_DanhSach
    @IDCSKCB BIGINT,
    @Ngay DATE=NULL,
    @TrangThaiKham TINYINT=NULL,
    @TuKhoa NVARCHAR(200)=NULL,
    @Trang INT=1,
    @KichThuocTrang INT=25
AS
BEGIN
    SET NOCOUNT ON;
    SET @Ngay=ISNULL(@Ngay,CONVERT(DATE,SYSDATETIME()));
    SET @TuKhoa=NULLIF(LTRIM(RTRIM(@TuKhoa)),N'');
    IF @Trang IS NULL OR @Trang<1 SET @Trang=1;
    IF @KichThuocTrang IS NULL OR @KichThuocTrang<1 SET @KichThuocTrang=25;
    IF @KichThuocTrang>100 SET @KichThuocTrang=100;
    DECLARE @Offset BIGINT=(CONVERT(BIGINT,@Trang)-1)*@KichThuocTrang;

    ;WITH X AS
    (
        SELECT
            VV.ID AS IDVaoVien,VV.SoThuTu,VV.MaVaoVien,VV.NgayGioVaoVien,VV.ThoiGianChuyenKham,
            VV.TrangThaiKham,VV.SinhHieu,VV.Kham,VV.KeToa,VV.IDBacSiKham,
            B.ID AS IDBenhNhan,B.MaBN,B.HoTen,B.NgaySinh,B.IDGioiTinh,GT.TenGioiTinh,B.SoCCCD,B.DienThoai,
            B.GhiChu AS GhiChuBenhNhan,VV.GhiChu AS GhiChuLanKham,
            CASE WHEN NULLIF(LTRIM(RTRIM(B.GhiChu)),N'') IS NULL THEN 0 ELSE 1 END AS CoGhiChu,
            CASE VV.TrangThaiKham WHEN 0 THEN N'CHUA_KHAM' WHEN 1 THEN N'DANG_KHAM' WHEN 2 THEN N'DA_KHAM' ELSE N'KHAC' END AS MaTrangThaiMau,
            CASE VV.TrangThaiKham WHEN 0 THEN N'#DDF4FF' WHEN 1 THEN N'#FFF3BF' WHEN 2 THEN N'#111827' ELSE N'#F3F4F6' END AS MauNen,
            CASE VV.TrangThaiKham WHEN 2 THEN N'#FFFFFF' ELSE N'#111827' END AS MauChu,
            COUNT(*) OVER() AS TongSoDong
        FROM dbo.QL_VaoVien VV
        INNER JOIN dbo.QL_BenhNhan B ON B.IDCSKCB=VV.IDCSKCB AND B.ID=VV.IDBenhNhan
        INNER JOIN dbo.DM_GioiTinh GT ON GT.ID=B.IDGioiTinh AND GT.Active=1
        WHERE VV.IDCSKCB=@IDCSKCB
          AND VV.Ngay=@Ngay
          AND VV.DaChuyenKham=1
          AND VV.Active=1
          AND VV.TrangThaiKham IN(0,1,2)
          AND (@TrangThaiKham IS NULL OR VV.TrangThaiKham=@TrangThaiKham)
          AND
          (
              @TuKhoa IS NULL
              OR B.MaBN=@TuKhoa OR B.SoCCCD=@TuKhoa OR B.DienThoai=@TuKhoa
              OR B.MaBN LIKE @TuKhoa+N'%' OR B.SoCCCD LIKE @TuKhoa+N'%' OR B.DienThoai LIKE @TuKhoa+N'%'
              OR B.HoTen LIKE N'%'+@TuKhoa+N'%'
          )
    )
    SELECT *
    FROM X
    ORDER BY CASE TrangThaiKham WHEN 0 THEN 0 WHEN 1 THEN 1 WHEN 2 THEN 2 ELSE 3 END,
             ISNULL(ThoiGianChuyenKham,NgayGioVaoVien) DESC,IDVaoVien DESC
    OFFSET @Offset ROWS FETCH NEXT @KichThuocTrang ROWS ONLY
    OPTION(RECOMPILE);
END;
GO

/* ==================== STO_QL_Kham_HuyDangKham ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_Kham_HuyDangKham
    @IDCSKCB BIGINT,
    @IDVaoVien BIGINT,
    @IDBacSi BIGINT,
    @LaQuanTri BIT=0
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS
    (
        SELECT 1
        FROM dbo.QL_VaoVien V
        WHERE V.IDCSKCB=@IDCSKCB AND V.ID=@IDVaoVien
          AND V.Active=1 AND V.TrangThaiKham=1 AND ISNULL(V.Kham,0)=0
          AND ISNULL(@LaQuanTri,0)=0
          AND V.IDBacSiKham IS NOT NULL AND V.IDBacSiKham<>@IDBacSi
    )
    BEGIN
        SELECT 409 AS Status,N'Bệnh nhân đang được bác sĩ khác khám.' AS Message;
        RETURN;
    END;

    IF EXISTS(SELECT 1 FROM dbo.QL_PhieuSinhHieu WHERE IDCSKCB=@IDCSKCB AND IDVaoVien=@IDVaoVien)
       OR EXISTS(SELECT 1 FROM dbo.QL_ChanDoan_CT WHERE IDCSKCB=@IDCSKCB AND IDVaoVien=@IDVaoVien)
       OR EXISTS(SELECT 1 FROM dbo.QL_ChiDinh_CT WHERE IDCSKCB=@IDCSKCB AND IDVaoVien=@IDVaoVien AND Active=1)
       OR EXISTS(SELECT 1 FROM dbo.QL_ToaThuoc_CT WHERE IDCSKCB=@IDCSKCB AND IDVaoVien=@IDVaoVien AND Active=1)
    BEGIN
        SELECT 409 AS Status,N'Lượt khám đã có dữ liệu được lưu, không thể trả về Chưa khám.' AS Message;
        RETURN;
    END;

    UPDATE dbo.QL_VaoVien
    SET TrangThaiKham=0,
        IDBacSiKham=NULL,
        BatDauKhamLuc=NULL,
        NgayCapNhat=SYSDATETIME()
    WHERE IDCSKCB=@IDCSKCB AND ID=@IDVaoVien
      AND ISNULL(Kham,0)=0 AND TrangThaiKham=1 AND Active=1
      AND (ISNULL(@LaQuanTri,0)=1 OR IDBacSiKham IS NULL OR IDBacSiKham=@IDBacSi);

    SELECT CASE WHEN @@ROWCOUNT>0 THEN 200 ELSE 409 END AS Status,
           CASE WHEN @@ROWCOUNT>0 THEN N'Đã trả lượt khám về trạng thái Chưa khám.'
                ELSE N'Không thể hủy trạng thái đang khám.' END AS Message;
END;

GO

/* ==================== STO_QL_Kham_LayToaCu ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_Kham_LayToaCu
    @IDCSKCB BIGINT,
    @IDVaoVienCu BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT T.ID AS IDToaThuocCTGoc, T.IDThuoc, DM.MaThuoc, DM.TenThuoc, COALESCE(DVT.TenDVT,DM.DonViTinh) AS DonViTinh, DM.HamLuong, DM.HoatChat,
           T.SoNgay, T.Sang, T.Trua, T.Chieu, T.Toi, T.LieuDung, T.CachDung, T.SoLuong, T.DonGia, T.ThanhTien, T.ThuTu
    FROM dbo.QL_ToaThuoc_CT T
    JOIN dbo.DM_Thuoc DM ON DM.IDCSKCB = T.IDCSKCB AND DM.ID = T.IDThuoc
    LEFT JOIN dbo.DM_DonViTinh DVT ON DVT.IDCSKCB=DM.IDCSKCB AND DVT.ID=DM.IDDonViTinh
    WHERE T.IDCSKCB = @IDCSKCB AND T.IDVaoVien = @IDVaoVienCu AND T.Active = 1
    ORDER BY ISNULL(T.ThuTu, 999), T.ID;
END;
GO

/* ==================== STO_QL_Kham_LichSu ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_Kham_LichSu
    @IDCSKCB BIGINT,
    @IDBenhNhan BIGINT,
    @IDVaoVienHienTai BIGINT = NULL,
    @TuKhoa NVARCHAR(200) = NULL,
    @Trang INT = 1,
    @KichThuocTrang INT = 10
AS
BEGIN
    SET NOCOUNT ON;

    SET @TuKhoa = NULLIF(LTRIM(RTRIM(@TuKhoa)), N'');
    SET @Trang = CASE WHEN @Trang < 1 THEN 1 ELSE @Trang END;
    SET @KichThuocTrang = CASE
        WHEN @KichThuocTrang < 10 THEN 10
        WHEN @KichThuocTrang > 100 THEN 100
        ELSE @KichThuocTrang
    END;

    SELECT
        VV.ID AS IDVaoVien,
        VV.MaVaoVien,
        VV.NgayGioVaoVien,
        VV.BatDauKhamLuc,
        VV.KetThucKhamLuc,
        VV.TrieuChung,
        VV.HuongDieuTri,
        VV.NgayTaiKham,
        VV.GhiChu,
        NV.HoTen AS BacSiKham,
        STRING_AGG(
            (CASE WHEN CD.BanDau = 1 THEN N'[BĐ] ' ELSE N'' END) +
            (CASE WHEN CD.BenhChinh = 1 THEN N'[Chính] ' ELSE N'' END) +
            (CASE WHEN CD.BenhKhac = 1 THEN N'[#] ' ELSE N'' END) +
            CD.MaBenh + N' - ' + CD.TenBenh,
            N'; '
        ) AS ChanDoan,
        (SELECT COUNT(1)
         FROM dbo.QL_ToaThuoc_CT T
         WHERE T.IDCSKCB = VV.IDCSKCB
           AND T.IDVaoVien = VV.ID
           AND T.Active = 1) AS SoLuongThuoc,
        (SELECT COUNT(1)
         FROM dbo.QL_ChiDinh_CT C
         WHERE C.IDCSKCB = VV.IDCSKCB
           AND C.IDVaoVien = VV.ID
           AND C.Active = 1) AS SoLuongChiDinh,
        COUNT(*) OVER() AS TongSoDong
    FROM dbo.QL_VaoVien VV
    LEFT JOIN dbo.DM_NhanVien NV
      ON NV.IDCSKCB = VV.IDCSKCB
     AND NV.ID = VV.IDBacSiKham
    LEFT JOIN dbo.QL_ChanDoan_CT CD
      ON CD.IDCSKCB = VV.IDCSKCB
     AND CD.IDVaoVien = VV.ID
    WHERE VV.IDCSKCB = @IDCSKCB
      AND VV.IDBenhNhan = @IDBenhNhan
      AND (VV.TrangThaiKham = 2 OR VV.Kham = 1 OR VV.KeToa = 1)
      AND (@IDVaoVienHienTai IS NULL OR VV.ID <> @IDVaoVienHienTai)
      AND VV.Active = 1
      AND
      (
          @TuKhoa IS NULL
          OR NV.HoTen LIKE N'%' + @TuKhoa + N'%'
          OR VV.TrieuChung LIKE N'%' + @TuKhoa + N'%'
          OR CONVERT(NVARCHAR(10), VV.NgayGioVaoVien, 103) LIKE N'%' + @TuKhoa + N'%'
          OR EXISTS
          (
              SELECT 1
              FROM dbo.QL_ChanDoan_CT X
              WHERE X.IDCSKCB = VV.IDCSKCB
                AND X.IDVaoVien = VV.ID
                AND
                (
                    X.MaBenh LIKE N'%' + @TuKhoa + N'%'
                    OR X.TenBenh LIKE N'%' + @TuKhoa + N'%'
                )
          )
      )
    GROUP BY
        VV.ID, VV.MaVaoVien, VV.NgayGioVaoVien, VV.BatDauKhamLuc, VV.KetThucKhamLuc,
        VV.TrieuChung, VV.HuongDieuTri, VV.NgayTaiKham, VV.GhiChu, NV.HoTen, VV.IDCSKCB
    ORDER BY VV.NgayGioVaoVien DESC, VV.ID DESC
    OFFSET (@Trang - 1) * @KichThuocTrang ROWS
    FETCH NEXT @KichThuocTrang ROWS ONLY;
END;
GO

/* ==================== STO_QL_Kham_Luu ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_Kham_Luu
    @IDCSKCB BIGINT,
    @IDVaoVien BIGINT,
    @IDBacSi BIGINT,
    @HoTen NVARCHAR(200)=NULL,
    @NgaySinh DATE=NULL,
    @GioiTinh TINYINT=NULL,
    @TrieuChung NVARCHAR(2000)=NULL,
    @IDPhacDo BIGINT=NULL,
    @MaPDGoc NVARCHAR(50)=NULL,
    @HuongDieuTri NVARCHAR(2000)=NULL,
    @NgayTaiKham DATE=NULL,
    @GhiChu NVARCHAR(1000)=NULL,
    @SinhHieuJson NVARCHAR(MAX)=NULL,
    @ChanDoanJson NVARCHAR(MAX)=NULL,
    @ChiDinhJson NVARCHAR(MAX)=NULL,
    @ToaThuocJson NVARCHAR(MAX)=NULL,
    @KhamXong BIT=0,
    @LaQuanTri BIT=0
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRAN;

        DECLARE @TrangThaiHienTai TINYINT,@IDBenhNhan BIGINT,@IDThuTien BIGINT,@BSDangKham BIGINT,@IDBacSiNghiepVu BIGINT;
        SELECT @TrangThaiHienTai=V.TrangThaiKham,@IDBenhNhan=V.IDBenhNhan,@BSDangKham=V.IDBacSiKham
        FROM dbo.QL_VaoVien V WITH(UPDLOCK,HOLDLOCK)
        WHERE V.IDCSKCB=@IDCSKCB AND V.ID=@IDVaoVien AND V.Active=1 AND V.DaChuyenKham=1;

        IF @TrangThaiHienTai IS NULL THROW 57000,N'Không tìm thấy lượt khám hoặc chưa chuyển khám.',1;
        IF @TrangThaiHienTai=3 THROW 57000,N'Lượt khám đã bị hủy.',1;
        IF ISNULL(@LaQuanTri,0)=0
           AND @BSDangKham IS NOT NULL
           AND @BSDangKham<>@IDBacSi
            THROW 57000,N'Bệnh nhân đang thuộc phiên khám của bác sĩ khác.',1;

        SET @IDBacSiNghiepVu=CASE
            WHEN ISNULL(@LaQuanTri,0)=1 AND @BSDangKham IS NOT NULL THEN @BSDangKham
            ELSE @IDBacSi
        END;

        SELECT @IDThuTien=ID FROM dbo.QL_ThuTien WHERE IDCSKCB=@IDCSKCB AND IDVaoVien=@IDVaoVien;
        IF EXISTS(SELECT 1 FROM dbo.QL_ThuTien WHERE IDCSKCB=@IDCSKCB AND ID=@IDThuTien AND DaThu=1)
            THROW 57000,N'Lượt khám đã thu tiền, không thể thay đổi dữ liệu.',1;

        IF @GioiTinh IS NOT NULL
           AND NOT EXISTS(SELECT 1 FROM dbo.DM_GioiTinh WHERE ID=@GioiTinh AND Active=1)
            THROW 57000,N'Giới tính không hợp lệ.',1;

        IF @IDBenhNhan IS NOT NULL
        BEGIN
            UPDATE dbo.QL_BenhNhan
            SET HoTen=ISNULL(NULLIF(LTRIM(RTRIM(@HoTen)),N''),HoTen),
                NgaySinh=ISNULL(@NgaySinh,NgaySinh),
                IDGioiTinh=ISNULL(@GioiTinh,IDGioiTinh),
                NgayCapNhat=SYSDATETIME()
            WHERE IDCSKCB=@IDCSKCB AND ID=@IDBenhNhan;
        END;

        IF @IDPhacDo IS NOT NULL
           AND NOT EXISTS(SELECT 1 FROM dbo.DM_PhacDo WHERE IDCSKCB=@IDCSKCB AND ID=@IDPhacDo AND Active=1)
            THROW 57000,N'Phác đồ không hợp lệ.',1;

        UPDATE dbo.QL_VaoVien
        SET IDBacSiKham=@IDBacSiNghiepVu,
            TrieuChung=@TrieuChung,IDPhacDo=@IDPhacDo,
            MaPDGoc=NULLIF(LTRIM(RTRIM(@MaPDGoc)),N''),HuongDieuTri=@HuongDieuTri,
            NgayTaiKham=@NgayTaiKham,GhiChu=@GhiChu,Kham=1,
            BatDauKhamLuc=COALESCE(BatDauKhamLuc,SYSDATETIME()),NgayCapNhat=SYSDATETIME()
        WHERE IDCSKCB=@IDCSKCB AND ID=@IDVaoVien;

        /* NULL = khong sua; [] = khong tao phieu sinh hieu moi. */
        IF @SinhHieuJson IS NOT NULL
        BEGIN
            IF ISJSON(@SinhHieuJson)<>1 THROW 57000,N'Dữ liệu sinh hiệu không hợp lệ.',1;
            IF EXISTS
            (
                SELECT 1 FROM OPENJSON(@SinhHieuJson)
                WITH(GiaTri NVARCHAR(100) '$.GiaTri')
                WHERE NULLIF(LTRIM(RTRIM(GiaTri)),N'') IS NOT NULL
            )
            BEGIN
                DECLARE @IDPhieuSH BIGINT;
                INSERT dbo.QL_PhieuSinhHieu(IDCSKCB,IDVaoVien,IDNhanVien,NgayGioDo)
                VALUES(@IDCSKCB,@IDVaoVien,@IDBacSi,SYSDATETIME());
                SET @IDPhieuSH=SCOPE_IDENTITY();

                INSERT dbo.QL_PhieuSinhHieu_CT(IDCSKCB,IDPhieuSinhHieu,IDTriSoSinhHieu,GiaTri)
                SELECT @IDCSKCB,@IDPhieuSH,J.IDTriSoSinhHieu,J.GiaTri
                FROM OPENJSON(@SinhHieuJson)
                WITH(IDTriSoSinhHieu BIGINT '$.IDTriSoSinhHieu',GiaTri NVARCHAR(100) '$.GiaTri') J
                INNER JOIN dbo.DM_TriSoSinhHieu D ON D.IDCSKCB=@IDCSKCB AND D.ID=J.IDTriSoSinhHieu AND D.Active=1
                WHERE NULLIF(LTRIM(RTRIM(J.GiaTri)),N'') IS NOT NULL;

                IF EXISTS(SELECT 1 FROM dbo.QL_PhieuSinhHieu_CT WHERE IDCSKCB=@IDCSKCB AND IDPhieuSinhHieu=@IDPhieuSH)
                    UPDATE dbo.QL_VaoVien SET SinhHieu=1 WHERE IDCSKCB=@IDCSKCB AND ID=@IDVaoVien;
            END;
        END;

        /* Chan doan: NULL = giu nguyen; [] = xoa het. */
        IF @ChanDoanJson IS NOT NULL
        BEGIN
            IF ISJSON(@ChanDoanJson)<>1 THROW 57000,N'Dữ liệu chẩn đoán không hợp lệ.',1;
            DECLARE @CD TABLE(IDICD10 BIGINT PRIMARY KEY,BanDau BIT,BenhChinh BIT,BenhKhac BIT,ThuTu INT,GhiChu NVARCHAR(500));
            INSERT @CD
            SELECT IDICD10,ISNULL(BanDau,0),ISNULL(BenhChinh,0),ISNULL(BenhKhac,0),ThuTu,GhiChu
            FROM OPENJSON(@ChanDoanJson)
            WITH(IDICD10 BIGINT '$.IDICD10',BanDau BIT '$.BanDau',BenhChinh BIT '$.BenhChinh',BenhKhac BIT '$.BenhKhac',ThuTu INT '$.ThuTu',GhiChu NVARCHAR(500) '$.GhiChu')
            WHERE IDICD10 IS NOT NULL;

            IF (SELECT COUNT(*) FROM @CD WHERE BenhChinh=1)<>1
            BEGIN
                ROLLBACK;
                SELECT 400 AS Status,N'Chẩn đoán bắt buộc phải có đúng 1 bệnh chính.' AS Message,
                       @IDVaoVien AS IDVaoVien,CAST(NULL AS TINYINT) AS TrangThaiKham;
                RETURN;
            END;
            IF EXISTS
            (
                SELECT 1 FROM @CD C
                WHERE NOT EXISTS(SELECT 1 FROM dbo.DM_ICD10 I WHERE I.IDCSKCB=@IDCSKCB AND I.ID=C.IDICD10)
            )
                THROW 57000,N'Có mã ICD-10 không hợp lệ.',1;

            DELETE dbo.QL_ChanDoan_CT WHERE IDCSKCB=@IDCSKCB AND IDVaoVien=@IDVaoVien;
            INSERT dbo.QL_ChanDoan_CT(IDCSKCB,IDVaoVien,IDICD10,MaBenh,TenBenh,BanDau,BenhChinh,BenhKhac,ThuTu,IDBacSi,GhiChu)
            SELECT @IDCSKCB,@IDVaoVien,I.ID,I.MaBenh,I.TenBenh,C.BanDau,C.BenhChinh,C.BenhKhac,C.ThuTu,@IDBacSiNghiepVu,C.GhiChu
            FROM @CD C INNER JOIN dbo.DM_ICD10 I ON I.IDCSKCB=@IDCSKCB AND I.ID=C.IDICD10;
        END
        ELSE IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.QL_ChanDoan_CT
            WHERE IDCSKCB=@IDCSKCB AND IDVaoVien=@IDVaoVien AND BenhChinh=1
        )
        BEGIN
            ROLLBACK;
            SELECT 400 AS Status,N'Chẩn đoán bắt buộc phải có đúng 1 bệnh chính.' AS Message,
                   @IDVaoVien AS IDVaoVien,CAST(NULL AS TINYINT) AS TrangThaiKham;
            RETURN;
        END;

        /* Chi dinh: giu ID de ket qua/file CLS khong bi dut lien ket. */
        IF @ChiDinhJson IS NOT NULL
        BEGIN
            IF ISJSON(@ChiDinhJson)<>1 THROW 57000,N'Dữ liệu chỉ định không hợp lệ.',1;

            DECLARE @CI TABLE
            (
                ID BIGINT NULL,IDDichVu BIGINT NOT NULL,SoLuong DECIMAL(10,2) NOT NULL,
                DonGia DECIMAL(18,2) NULL,GuiNgoai BIT NOT NULL,NoiGuiNgoai NVARCHAR(300) NULL,GhiChu NVARCHAR(500) NULL
            );

            INSERT @CI(ID,IDDichVu,SoLuong,DonGia,GuiNgoai,NoiGuiNgoai,GhiChu)
            SELECT COALESCE(J.ID,J.id),J.IDDichVu,COALESCE(J.SoLuong,1),NULL,ISNULL(J.GuiNgoai,0),J.NoiGuiNgoai,J.GhiChu
            FROM OPENJSON(@ChiDinhJson)
            WITH
            (
                ID BIGINT '$.ID',id BIGINT '$.id',IDDichVu BIGINT '$.IDDichVu',
                SoLuong DECIMAL(10,2) '$.SoLuong',DonGia DECIMAL(18,2) '$.DonGia',
                GuiNgoai BIT '$.GuiNgoai',NoiGuiNgoai NVARCHAR(300) '$.NoiGuiNgoai',GhiChu NVARCHAR(500) '$.GhiChu'
            ) J
            WHERE J.IDDichVu IS NOT NULL;

            IF EXISTS(SELECT 1 FROM @CI WHERE SoLuong<=0)
                THROW 57000,N'Số lượng chỉ định CLS phải lớn hơn 0.',1;

            IF EXISTS(SELECT ID FROM @CI WHERE ID IS NOT NULL AND ID>0 GROUP BY ID HAVING COUNT(*)>1)
                THROW 57000,N'Danh sách chỉ định có ID bị lặp.',1;

            IF EXISTS
            (
                SELECT 1 FROM @CI X
                WHERE NOT EXISTS(SELECT 1 FROM dbo.DM_DichVu D WHERE D.IDCSKCB=@IDCSKCB AND D.ID=X.IDDichVu AND D.Active=1 AND D.LoaiDichVu<>1)
            )
                THROW 57000,N'Có dịch vụ CLS không hợp lệ.',1;

            IF EXISTS
            (
                SELECT 1 FROM @CI X
                WHERE X.ID>0 AND NOT EXISTS
                (
                    SELECT 1 FROM dbo.QL_ChiDinh_CT C
                    WHERE C.IDCSKCB=@IDCSKCB AND C.IDVaoVien=@IDVaoVien AND C.ID=X.ID AND C.Active=1
                )
            )
                THROW 57000,N'Có chỉ định không thuộc lượt khám hiện tại.',1;

            IF EXISTS
            (
                SELECT 1
                FROM dbo.QL_ChiDinh_CT C
                WHERE C.IDCSKCB=@IDCSKCB AND C.IDVaoVien=@IDVaoVien AND C.Active=1
                  AND NOT EXISTS(SELECT 1 FROM @CI X WHERE X.ID=C.ID)
                  AND EXISTS(SELECT 1 FROM dbo.QL_CLS_PhieuKetQua K WHERE K.IDCSKCB=C.IDCSKCB AND K.IDChiDinhCT=C.ID AND K.Active=1)
            )
                THROW 57000,N'Không thể xóa chỉ định đã có kết quả CLS.',1;

            DELETE T
            FROM dbo.QL_ThuTien_CT T
            INNER JOIN dbo.QL_ChiDinh_CT C ON C.IDCSKCB=T.IDCSKCB AND C.ID=T.IDChiDinhCT
            WHERE T.IDCSKCB=@IDCSKCB AND T.IDThuTien=@IDThuTien AND C.IDVaoVien=@IDVaoVien;

            UPDATE C
            SET Active=0
            FROM dbo.QL_ChiDinh_CT C
            WHERE C.IDCSKCB=@IDCSKCB AND C.IDVaoVien=@IDVaoVien AND C.Active=1
              AND NOT EXISTS(SELECT 1 FROM @CI X WHERE X.ID=C.ID);

            UPDATE C
            SET IDDichVu=X.IDDichVu,SoLuong=X.SoLuong,DonGia=D.DonGia,
                ThanhTien=X.SoLuong*D.DonGia,GuiNgoai=X.GuiNgoai,
                NoiGuiNgoai=CASE WHEN X.GuiNgoai=1 THEN X.NoiGuiNgoai END,GhiChu=X.GhiChu
            FROM dbo.QL_ChiDinh_CT C
            INNER JOIN @CI X ON X.ID=C.ID
            INNER JOIN dbo.DM_DichVu D ON D.IDCSKCB=@IDCSKCB AND D.ID=X.IDDichVu
            WHERE C.IDCSKCB=@IDCSKCB AND C.IDVaoVien=@IDVaoVien AND C.Active=1;

            INSERT dbo.QL_ChiDinh_CT
            (
                IDCSKCB,IDVaoVien,IDDichVu,SoLuong,DonGia,ThanhTien,GuiNgoai,NoiGuiNgoai,IDBacSiChiDinh,TrangThai,GhiChu,Active
            )
            SELECT @IDCSKCB,@IDVaoVien,D.ID,X.SoLuong,D.DonGia,
                   X.SoLuong*D.DonGia,X.GuiNgoai,
                   CASE WHEN X.GuiNgoai=1 THEN X.NoiGuiNgoai END,@IDBacSiNghiepVu,0,X.GhiChu,1
            FROM @CI X
            INNER JOIN dbo.DM_DichVu D ON D.IDCSKCB=@IDCSKCB AND D.ID=X.IDDichVu
            WHERE ISNULL(X.ID,0)<=0;

            IF @IDThuTien IS NOT NULL
                INSERT dbo.QL_ThuTien_CT(IDCSKCB,IDThuTien,IDChiDinhCT,SoLuong,DonGia,ThanhTien,TienGiam,ThucThu,DaThu)
                SELECT @IDCSKCB,@IDThuTien,C.ID,C.SoLuong,C.DonGia,C.ThanhTien,0,C.ThanhTien,0
                FROM dbo.QL_ChiDinh_CT C
                WHERE C.IDCSKCB=@IDCSKCB AND C.IDVaoVien=@IDVaoVien AND C.Active=1;
        END;

        /* Toa: diff/upsert de giu ID, NULL = giu nguyen. */
        IF @ToaThuocJson IS NOT NULL
        BEGIN
            IF ISJSON(@ToaThuocJson)<>1 THROW 57000,N'Dữ liệu toa thuốc không hợp lệ.',1;

            DECLARE @TT TABLE
            (
                ID BIGINT NULL,IDThuoc BIGINT NOT NULL,SoNgay INT NULL,Sang NVARCHAR(50) NULL,Trua NVARCHAR(50) NULL,
                Chieu NVARCHAR(50) NULL,Toi NVARCHAR(50) NULL,LieuDung NVARCHAR(300) NULL,CachDung NVARCHAR(500) NULL,
                SoLuong DECIMAL(10,2) NOT NULL,DonGia DECIMAL(18,2) NULL,ThuTu INT NULL,IDToaThuocCTGoc BIGINT NULL
            );

            IF EXISTS
            (
                SELECT 1
                FROM OPENJSON(@ToaThuocJson)
                WITH(IDThuoc BIGINT '$.IDThuoc',SoLuong DECIMAL(10,2) '$.SoLuong')
                WHERE IDThuoc IS NOT NULL AND ISNULL(SoLuong,0)<=0
            )
                THROW 57000,N'Số lượng thuốc phải lớn hơn 0.',1;

            INSERT @TT
            SELECT COALESCE(J.ID,J.id),J.IDThuoc,J.SoNgay,J.Sang,J.Trua,J.Chieu,J.Toi,J.LieuDung,J.CachDung,
                   J.SoLuong,NULL,J.ThuTu,J.IDToaThuocCTGoc
            FROM OPENJSON(@ToaThuocJson)
            WITH
            (
                ID BIGINT '$.ID',id BIGINT '$.id',IDThuoc BIGINT '$.IDThuoc',SoNgay INT '$.SoNgay',
                Sang NVARCHAR(50) '$.Sang',Trua NVARCHAR(50) '$.Trua',Chieu NVARCHAR(50) '$.Chieu',Toi NVARCHAR(50) '$.Toi',
                LieuDung NVARCHAR(300) '$.LieuDung',CachDung NVARCHAR(500) '$.CachDung',SoLuong DECIMAL(10,2) '$.SoLuong',
                DonGia DECIMAL(18,2) '$.DonGia',ThuTu INT '$.ThuTu',IDToaThuocCTGoc BIGINT '$.IDToaThuocCTGoc'
            ) J
            WHERE J.IDThuoc IS NOT NULL AND J.SoLuong>0;

            IF EXISTS(SELECT ID FROM @TT WHERE ID IS NOT NULL AND ID>0 GROUP BY ID HAVING COUNT(*)>1)
                THROW 57000,N'Danh sách toa có ID bị lặp.',1;
            IF EXISTS
            (
                SELECT 1 FROM @TT X
                WHERE NOT EXISTS(SELECT 1 FROM dbo.DM_Thuoc D WHERE D.IDCSKCB=@IDCSKCB AND D.ID=X.IDThuoc AND D.Active=1)
            )
                THROW 57000,N'Có thuốc không hợp lệ.',1;
            IF EXISTS
            (
                SELECT 1 FROM @TT X
                WHERE X.ID>0 AND NOT EXISTS
                (
                    SELECT 1 FROM dbo.QL_ToaThuoc_CT T
                    WHERE T.IDCSKCB=@IDCSKCB AND T.IDVaoVien=@IDVaoVien AND T.ID=X.ID AND T.Active=1
                )
            )
                THROW 57000,N'Có dòng toa không thuộc lượt khám hiện tại.',1;

            DELETE X
            FROM dbo.QL_ThuTien_CT X
            INNER JOIN dbo.QL_ToaThuoc_CT T ON T.IDCSKCB=X.IDCSKCB AND T.ID=X.IDToaThuocCT
            WHERE X.IDCSKCB=@IDCSKCB AND X.IDThuTien=@IDThuTien AND T.IDVaoVien=@IDVaoVien;

            UPDATE T
            SET Active=0
            FROM dbo.QL_ToaThuoc_CT T
            WHERE T.IDCSKCB=@IDCSKCB AND T.IDVaoVien=@IDVaoVien AND T.Active=1
              AND NOT EXISTS(SELECT 1 FROM @TT X WHERE X.ID=T.ID);

            UPDATE T
            SET IDThuoc=X.IDThuoc,IDBacSiKe=@IDBacSiNghiepVu,SoNgay=X.SoNgay,Sang=X.Sang,Trua=X.Trua,
                Chieu=X.Chieu,Toi=X.Toi,LieuDung=X.LieuDung,CachDung=X.CachDung,SoLuong=X.SoLuong,
                DonGia=D.GiaBan,ThanhTien=X.SoLuong*D.GiaBan,
                ThuTu=X.ThuTu,IDToaThuocCTGoc=X.IDToaThuocCTGoc
            FROM dbo.QL_ToaThuoc_CT T
            INNER JOIN @TT X ON X.ID=T.ID
            INNER JOIN dbo.DM_Thuoc D ON D.IDCSKCB=@IDCSKCB AND D.ID=X.IDThuoc
            WHERE T.IDCSKCB=@IDCSKCB AND T.IDVaoVien=@IDVaoVien AND T.Active=1;

            INSERT dbo.QL_ToaThuoc_CT
            (
                IDCSKCB,IDVaoVien,IDThuoc,NgayKe,IDBacSiKe,SoNgay,Sang,Trua,Chieu,Toi,LieuDung,CachDung,
                SoLuong,DonGia,ThanhTien,ThuTu,IDToaThuocCTGoc,Active
            )
            SELECT @IDCSKCB,@IDVaoVien,D.ID,SYSDATETIME(),@IDBacSiNghiepVu,X.SoNgay,X.Sang,X.Trua,X.Chieu,X.Toi,X.LieuDung,X.CachDung,
                   X.SoLuong,D.GiaBan,X.SoLuong*D.GiaBan,X.ThuTu,X.IDToaThuocCTGoc,1
            FROM @TT X
            INNER JOIN dbo.DM_Thuoc D ON D.IDCSKCB=@IDCSKCB AND D.ID=X.IDThuoc
            WHERE ISNULL(X.ID,0)<=0;

            IF @IDThuTien IS NOT NULL
                INSERT dbo.QL_ThuTien_CT(IDCSKCB,IDThuTien,IDToaThuocCT,SoLuong,DonGia,ThanhTien,TienGiam,ThucThu,DaThu)
                SELECT @IDCSKCB,@IDThuTien,T.ID,T.SoLuong,T.DonGia,T.ThanhTien,0,T.ThanhTien,0
                FROM dbo.QL_ToaThuoc_CT T
                WHERE T.IDCSKCB=@IDCSKCB AND T.IDVaoVien=@IDVaoVien AND T.Active=1;

            UPDATE dbo.QL_VaoVien
            SET KeToa=CASE WHEN EXISTS(SELECT 1 FROM dbo.QL_ToaThuoc_CT WHERE IDCSKCB=@IDCSKCB AND IDVaoVien=@IDVaoVien AND Active=1) THEN 1 ELSE 0 END
            WHERE IDCSKCB=@IDCSKCB AND ID=@IDVaoVien;
        END;

        IF @IDThuTien IS NOT NULL EXEC dbo.STO_QL_ThuTien_CapNhatTong @IDCSKCB,@IDVaoVien;

        DECLARE @CoToa BIT=CASE WHEN EXISTS
        (
            SELECT 1
            FROM dbo.QL_ToaThuoc_CT
            WHERE IDCSKCB=@IDCSKCB AND IDVaoVien=@IDVaoVien AND Active=1
        ) THEN 1 ELSE 0 END;

        DECLARE @TrangThaiMoi TINYINT=CASE
            WHEN @CoToa=1 OR @KhamXong=1 OR @TrangThaiHienTai=2 THEN 2
            ELSE 1
        END;

        UPDATE dbo.QL_VaoVien
        SET TrangThaiKham=@TrangThaiMoi,
            KetThucKhamLuc=CASE WHEN @TrangThaiMoi=2 THEN COALESCE(KetThucKhamLuc,SYSDATETIME()) ELSE NULL END,
            NgayCapNhat=SYSDATETIME()
        WHERE IDCSKCB=@IDCSKCB AND ID=@IDVaoVien;

        COMMIT;
        SELECT 200 AS Status,
               CASE WHEN @TrangThaiMoi=2 THEN N'Khám bệnh hoàn tất thành công.' ELSE N'Lưu dữ liệu khám thành công.' END AS Message,
               @IDVaoVien AS IDVaoVien,@TrangThaiMoi AS TrangThaiKham;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK;
        SELECT 400 AS Status,N'Không thể lưu khám bệnh do dữ liệu không hợp lệ hoặc đã thay đổi.' AS Message,
               @IDVaoVien AS IDVaoVien,CAST(NULL AS TINYINT) AS TrangThaiKham;
    END CATCH
END;

GO

/* ==================== STO_QL_CLS_CauHinh_ChiTiet ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_CLS_CauHinh_ChiTiet
    @IDCSKCB BIGINT,
    @IDDichVu BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT TOP 1
        D.ID AS IDDichVu,D.MaDichVu,D.TenDichVu,D.DonViTinh,D.LoaiDichVu,
        ISNULL(D.LoaiKetQua,0) AS LoaiKetQua,D.IDFormKQ AS IDForm,
        F.MaForm,F.TenForm
    FROM dbo.DM_DichVu D
    LEFT JOIN dbo.QL_CLS_FormKQXN F
      ON F.IDCSKCB=D.IDCSKCB AND F.ID=D.IDFormKQ AND F.Active=1
    WHERE D.IDCSKCB=@IDCSKCB AND D.ID=@IDDichVu AND D.Active=1;

    SELECT
        T.ID AS IDTriSoXN,T.MaTriSo,COALESCE(NULLIF(C.TenHienThi,N''),T.TenTriSo) AS TenTriSo,C.DonViTinh,
        C.DinhLuong,C.LuongDinhTinh,C.TuyetDoi,
        C.TriSoBinhThuong1,C.GHMin1,C.GHMax1,C.MacDinh1,
        C.TriSoBinhThuong2,C.GHMin2,C.GHMax2,C.MacDinh2,
        C.DonViTinh2,C.TiLeQuyDoi,
        C.IDGioiTinh,GT.TenGioiTinh,
        C.GHTuoi,C.TuoiMin,C.TuoiMax,C.LamTron,C.Nguong,C.Tieude,
        C.CongThuc,C.CongThucMoi,
        C.STT,T.Active
    FROM dbo.DM_DichVu D
    INNER JOIN dbo.QL_CLS_FormKQXN_CT C
      ON C.IDCSKCB=D.IDCSKCB AND C.IDForm=D.IDFormKQ AND C.Active=1
    INNER JOIN dbo.QL_CLS_DM_TriSoXN T
      ON T.IDCSKCB=C.IDCSKCB AND T.ID=C.IDTriSoXN AND T.Active=1
    LEFT JOIN dbo.DM_GioiTinh GT
      ON GT.ID=C.IDGioiTinh AND GT.Active=1
    WHERE D.IDCSKCB=@IDCSKCB AND D.ID=@IDDichVu AND D.Active=1
    ORDER BY C.STT,T.ID;
END;
GO

/* ==================== STO_QL_CLS_CauHinh_DichVu_DanhSach ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_CLS_CauHinh_DichVu_DanhSach
    @IDCSKCB BIGINT,@TuKhoa NVARCHAR(200)=NULL,@Trang INT=1,@KichThuocTrang INT=25
AS
BEGIN
    SET NOCOUNT ON;
    SET @TuKhoa=NULLIF(LTRIM(RTRIM(@TuKhoa)),N'');
    SET @Trang=CASE WHEN @Trang<1 THEN 1 ELSE @Trang END;
    SET @KichThuocTrang=CASE WHEN @KichThuocTrang<10 THEN 10 WHEN @KichThuocTrang>100 THEN 100 ELSE @KichThuocTrang END;
    ;WITH X AS
    (
        SELECT D.ID IDDichVu,D.MaDichVu,D.TenDichVu,D.DonViTinh,D.LoaiDichVu,D.Active,
               D.LoaiKetQua,D.IDFormKQ IDForm,F.MaForm,F.TenForm,
               ISNULL((SELECT COUNT(*) FROM dbo.QL_CLS_FormKQXN_CT C
                       WHERE C.IDCSKCB=D.IDCSKCB AND C.IDForm=D.IDFormKQ AND C.Active=1),0) SoTriSo
        FROM dbo.DM_DichVu D
        LEFT JOIN dbo.QL_CLS_FormKQXN F ON F.IDCSKCB=D.IDCSKCB AND F.ID=D.IDFormKQ AND F.Active=1
        WHERE D.IDCSKCB=@IDCSKCB AND D.Active=1 AND D.LoaiDichVu<>1
          AND (@TuKhoa IS NULL OR D.MaDichVu LIKE N'%'+@TuKhoa+N'%' OR D.TenDichVu LIKE N'%'+@TuKhoa+N'%')
    )
    SELECT X.*,COUNT(*) OVER() TongSoDong FROM X
    ORDER BY TenDichVu,IDDichVu
    OFFSET (@Trang-1)*@KichThuocTrang ROWS FETCH NEXT @KichThuocTrang ROWS ONLY;
END;
GO

/* ==================== STO_QL_CLS_CauHinh_Luu ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_CLS_CauHinh_Luu
    @IDCSKCB BIGINT,
    @IDDichVu BIGINT,
    @LoaiKetQua TINYINT,
    @TenForm NVARCHAR(1000)=NULL,
    @TriSoJson NVARCHAR(MAX)=N'[]'
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRAN;

        IF @LoaiKetQua NOT IN (1,2)
            THROW 58100,N'Loại kết quả không hợp lệ.',1;

        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.DM_DichVu
            WHERE IDCSKCB=@IDCSKCB AND ID=@IDDichVu AND Active=1 AND LoaiDichVu<>1
        )
            THROW 58100,N'Dịch vụ cận lâm sàng không hợp lệ.',1;

        IF ISJSON(ISNULL(@TriSoJson,N''))<>1
            THROW 58100,N'Danh sách trị số không hợp lệ.',1;

        DECLARE @IDForm BIGINT=
        (
            SELECT IDFormKQ FROM dbo.DM_DichVu
            WHERE IDCSKCB=@IDCSKCB AND ID=@IDDichVu
        );

        IF @LoaiKetQua=1
        BEGIN
            SET @TenForm=NULLIF(LTRIM(RTRIM(@TenForm)),N'');
            IF @TenForm IS NULL
                THROW 58100,N'Tên form xét nghiệm là bắt buộc.',1;

            IF @IDForm IS NULL
            BEGIN
                DECLARE @MaForm NVARCHAR(100),@SeqForm BIGINT;
                WHILE 1=1
                BEGIN
                    SET @SeqForm=NEXT VALUE FOR dbo.SEQ_CLS_MaForm;
                    SET @MaForm=N'F'+CASE
                        WHEN @SeqForm<10000 THEN RIGHT(N'0000'+CONVERT(NVARCHAR(20),@SeqForm),4)
                        ELSE CONVERT(NVARCHAR(20),@SeqForm) END;
                    IF NOT EXISTS
                    (
                        SELECT 1 FROM dbo.QL_CLS_FormKQXN
                        WHERE IDCSKCB=@IDCSKCB AND MaForm=@MaForm
                    ) BREAK;
                END;

                INSERT dbo.QL_CLS_FormKQXN(IDCSKCB,MaForm,TenForm,Active)
                VALUES(@IDCSKCB,@MaForm,@TenForm,1);
                SET @IDForm=SCOPE_IDENTITY();
            END
            ELSE
            BEGIN
                UPDATE dbo.QL_CLS_FormKQXN
                SET TenForm=@TenForm,Active=1,NgayCapNhat=SYSDATETIME()
                WHERE IDCSKCB=@IDCSKCB AND ID=@IDForm;
            END;

            DECLARE @TS TABLE
            (
                RowNo INT IDENTITY(1,1) PRIMARY KEY,
                IDTriSoXN BIGINT NULL,
                TenTriSo NVARCHAR(1000) NOT NULL,
                DonViTinh NVARCHAR(1000) NULL,
                DinhLuong BIT NOT NULL,
                LuongDinhTinh BIT NOT NULL,
                TuyetDoi BIT NOT NULL,
                TriSoBinhThuong1 NVARCHAR(1000) NULL,
                GHMin1 DECIMAL(18,6) NULL,
                GHMax1 DECIMAL(18,6) NULL,
                MacDinh1 NVARCHAR(1000) NULL,
                TriSoBinhThuong2 NVARCHAR(1000) NULL,
                GHMin2 DECIMAL(18,6) NULL,
                GHMax2 DECIMAL(18,6) NULL,
                MacDinh2 NVARCHAR(1000) NULL,
                DonViTinh2 NVARCHAR(1000) NULL,
                TiLeQuyDoi DECIMAL(18,6) NULL,
                IDGioiTinh TINYINT NULL,
                GHTuoi BIT NOT NULL,
                TuoiMin DECIMAL(10,2) NULL,
                TuoiMax DECIMAL(10,2) NULL,
                LamTron INT NULL,
                Nguong INT NULL,
                Tieude INT NULL,
                CongThuc NVARCHAR(MAX) NULL,
                CongThucMoi BIT NOT NULL,
                STT INT NOT NULL
            );

            INSERT @TS
            (
                IDTriSoXN,TenTriSo,DonViTinh,DinhLuong,LuongDinhTinh,TuyetDoi,
                TriSoBinhThuong1,GHMin1,GHMax1,MacDinh1,
                TriSoBinhThuong2,GHMin2,GHMax2,MacDinh2,DonViTinh2,TiLeQuyDoi,
                IDGioiTinh,GHTuoi,TuoiMin,TuoiMax,LamTron,Nguong,Tieude,
                CongThuc,CongThucMoi,STT
            )
            SELECT
                IDTriSoXN,
                NULLIF(LTRIM(RTRIM(TenTriSo)),N''),
                NULLIF(LTRIM(RTRIM(DonViTinh)),N''),
                ISNULL(DinhLuong,1),
                ISNULL(LuongDinhTinh,0),
                ISNULL(TuyetDoi,0),
                NULLIF(LTRIM(RTRIM(TriSoBinhThuong1)),N''),GHMin1,GHMax1,NULLIF(LTRIM(RTRIM(MacDinh1)),N''),
                NULLIF(LTRIM(RTRIM(TriSoBinhThuong2)),N''),GHMin2,GHMax2,NULLIF(LTRIM(RTRIM(MacDinh2)),N''),
                NULLIF(LTRIM(RTRIM(DonViTinh2)),N''),TiLeQuyDoi,
                NULLIF(IDGioiTinh,0),ISNULL(GHTuoi,0),TuoiMin,TuoiMax,LamTron,Nguong,Tieude,
                NULLIF(LTRIM(RTRIM(CongThuc)),N''),ISNULL(CongThucMoi,0),ISNULL(STT,999)
            FROM OPENJSON(@TriSoJson)
            WITH
            (
                IDTriSoXN BIGINT '$.id_tri_so',
                TenTriSo NVARCHAR(1000) '$.ten_tri_so',
                DonViTinh NVARCHAR(1000) '$.don_vi_tinh',
                DinhLuong BIT '$.dinh_luong',
                LuongDinhTinh BIT '$.luong_dinh_tinh',
                TuyetDoi BIT '$.tuyet_doi',
                TriSoBinhThuong1 NVARCHAR(1000) '$.tri_so_binh_thuong_1',
                GHMin1 DECIMAL(18,6) '$.gh_min_1',
                GHMax1 DECIMAL(18,6) '$.gh_max_1',
                MacDinh1 NVARCHAR(1000) '$.mac_dinh_1',
                TriSoBinhThuong2 NVARCHAR(1000) '$.tri_so_binh_thuong_2',
                GHMin2 DECIMAL(18,6) '$.gh_min_2',
                GHMax2 DECIMAL(18,6) '$.gh_max_2',
                MacDinh2 NVARCHAR(1000) '$.mac_dinh_2',
                DonViTinh2 NVARCHAR(1000) '$.don_vi_tinh_2',
                TiLeQuyDoi DECIMAL(18,6) '$.ti_le_quy_doi',
                IDGioiTinh TINYINT '$.id_gioi_tinh',
                GHTuoi BIT '$.gh_tuoi',
                TuoiMin DECIMAL(10,2) '$.tuoi_min',
                TuoiMax DECIMAL(10,2) '$.tuoi_max',
                LamTron INT '$.lam_tron',
                Nguong INT '$.nguong',
                Tieude INT '$.tieu_de',
                CongThuc NVARCHAR(MAX) '$.cong_thuc',
                CongThucMoi BIT '$.cong_thuc_moi',
                STT INT '$.stt'
            );

            IF NOT EXISTS(SELECT 1 FROM @TS)
                THROW 58100,N'Form xét nghiệm phải có ít nhất một trị số.',1;
            IF EXISTS(SELECT 1 FROM @TS WHERE TenTriSo IS NULL)
                THROW 58100,N'Tên trị số là bắt buộc.',1;
            IF EXISTS(SELECT 1 FROM @TS WHERE GHMin1 IS NOT NULL AND GHMax1 IS NOT NULL AND GHMin1>GHMax1)
                THROW 58100,N'Giới hạn Min 1 không được lớn hơn Max 1.',1;
            IF EXISTS(SELECT 1 FROM @TS WHERE GHMin2 IS NOT NULL AND GHMax2 IS NOT NULL AND GHMin2>GHMax2)
                THROW 58100,N'Giới hạn Min 2 không được lớn hơn Max 2.',1;
            IF EXISTS(SELECT 1 FROM @TS WHERE TuoiMin IS NOT NULL AND TuoiMax IS NOT NULL AND TuoiMin>TuoiMax)
                THROW 58100,N'Tuổi Min không được lớn hơn Tuổi Max.',1;
            IF EXISTS
            (
                SELECT 1 FROM @TS S
                WHERE S.IDGioiTinh IS NOT NULL
                  AND NOT EXISTS(SELECT 1 FROM dbo.DM_GioiTinh G WHERE G.ID=S.IDGioiTinh AND G.Active=1)
            )
                THROW 58100,N'Có giới tính cấu hình không hợp lệ.',1;
            IF EXISTS
            (
                SELECT 1 FROM @TS S
                WHERE S.IDTriSoXN IS NOT NULL
                  AND NOT EXISTS
                  (
                      SELECT 1 FROM dbo.QL_CLS_DM_TriSoXN T
                      WHERE T.IDCSKCB=@IDCSKCB AND T.ID=S.IDTriSoXN
                  )
            )
                THROW 58100,N'Có trị số không thuộc cơ sở khám chữa bệnh.',1;

            /* Master trị số chỉ giữ danh tính. Không ghi range/ĐVT/công thức của form ngược vào master. */
            DECLARE @R INT=(SELECT MIN(RowNo) FROM @TS),@RMax INT=(SELECT MAX(RowNo) FROM @TS);
            WHILE @R IS NOT NULL AND @R<=@RMax
            BEGIN
                IF EXISTS(SELECT 1 FROM @TS WHERE RowNo=@R AND IDTriSoXN IS NULL)
                BEGIN
                    DECLARE @SeqTS BIGINT,@MaTS NVARCHAR(100);
                    WHILE 1=1
                    BEGIN
                        SET @SeqTS=NEXT VALUE FOR dbo.SEQ_CLS_MaTriSo;
                        SET @MaTS=N'TS'+CASE
                            WHEN @SeqTS<10000 THEN RIGHT(N'0000'+CONVERT(NVARCHAR(20),@SeqTS),4)
                            ELSE CONVERT(NVARCHAR(20),@SeqTS) END;
                        IF NOT EXISTS
                        (
                            SELECT 1 FROM dbo.QL_CLS_DM_TriSoXN
                            WHERE IDCSKCB=@IDCSKCB AND MaTriSo=@MaTS
                        ) BREAK;
                    END;

                    INSERT dbo.QL_CLS_DM_TriSoXN
                    (
                        IDCSKCB,MaTriSo,TenTriSo,LoaiDuLieu,Active
                    )
                    SELECT
                        @IDCSKCB,@MaTS,TenTriSo,
                        CASE
                            WHEN DinhLuong=1 OR TuyetDoi=1 THEN N'NUMBER'
                            WHEN LuongDinhTinh=1 THEN N'TEXT'
                            ELSE N'TEXT'
                        END,
                        1
                    FROM @TS WHERE RowNo=@R;

                    UPDATE @TS SET IDTriSoXN=SCOPE_IDENTITY() WHERE RowNo=@R;
                END;
                SET @R=@R+1;
            END;

            UPDATE dbo.QL_CLS_FormKQXN_CT
            SET Active=0
            WHERE IDCSKCB=@IDCSKCB AND IDForm=@IDForm;

            /* Mỗi dòng @TS là một cấu hình sử dụng trị số trong form.
               Insert dòng mới để cho phép cùng master trị số có nhiều range theo giới/tuổi. */
            INSERT dbo.QL_CLS_FormKQXN_CT
            (
                IDCSKCB,IDForm,IDTriSoXN,TenHienThi,DonViTinh,
                DinhLuong,LuongDinhTinh,TuyetDoi,
                TriSoBinhThuong1,GHMin1,GHMax1,MacDinh1,
                TriSoBinhThuong2,GHMin2,GHMax2,MacDinh2,DonViTinh2,TiLeQuyDoi,
                IDGioiTinh,GHTuoi,TuoiMin,TuoiMax,LamTron,Nguong,Tieude,
                CongThuc,CongThucMoi,STT,Active
            )
            SELECT
                @IDCSKCB,@IDForm,S.IDTriSoXN,S.TenTriSo,S.DonViTinh,
                S.DinhLuong,S.LuongDinhTinh,S.TuyetDoi,
                S.TriSoBinhThuong1,S.GHMin1,S.GHMax1,S.MacDinh1,
                S.TriSoBinhThuong2,S.GHMin2,S.GHMax2,S.MacDinh2,S.DonViTinh2,S.TiLeQuyDoi,
                S.IDGioiTinh,S.GHTuoi,S.TuoiMin,S.TuoiMax,S.LamTron,S.Nguong,S.Tieude,
                S.CongThuc,S.CongThucMoi,S.STT,1
            FROM @TS S;
        END
        ELSE
        BEGIN
            SET @IDForm=NULL;
        END;

        UPDATE dbo.DM_DichVu
        SET LoaiKetQua=@LoaiKetQua,IDFormKQ=@IDForm
        WHERE IDCSKCB=@IDCSKCB AND ID=@IDDichVu;

        COMMIT;
        SELECT 200 AS Status,N'Đã lưu cấu hình kết quả CLS.' AS Message,@IDForm AS IDForm;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK;
        SELECT 400 AS Status,ERROR_MESSAGE() AS Message,CAST(NULL AS BIGINT) AS IDForm;
    END CATCH;
END;

GO

/* ==================== STO_QL_CLS_DM_TriSo_DanhSach ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_CLS_DM_TriSo_DanhSach
    @IDCSKCB BIGINT,
    @TuKhoa NVARCHAR(200)=NULL,
    @Trang INT=1,
    @KichThuocTrang INT=100
AS
BEGIN
    SET NOCOUNT ON;
    SET @TuKhoa=NULLIF(LTRIM(RTRIM(@TuKhoa)),N'');
    SET @Trang=CASE WHEN @Trang<1 THEN 1 ELSE @Trang END;
    SET @KichThuocTrang=CASE WHEN @KichThuocTrang<10 THEN 10 WHEN @KichThuocTrang>200 THEN 200 ELSE @KichThuocTrang END;

    ;WITH S AS
    (
        SELECT
            T.ID,T.MaTriSo,T.TenTriSo,T.TenVietTat,T.LOINCCode,
            T.LOINCComponent,T.LOINCProperty,T.LOINCTimeAspect,T.LOINCSystem,T.LOINCScale,T.LOINCMethod,
            T.LoaiDuLieu,T.Active,T.NgayTao,T.NgayCapNhat,
            COUNT(*) OVER() TongSoDong
        FROM dbo.QL_CLS_DM_TriSoXN T
        WHERE T.IDCSKCB=@IDCSKCB
          AND
          (
              @TuKhoa IS NULL
              OR T.MaTriSo LIKE N'%'+@TuKhoa+N'%'
              OR T.TenTriSo LIKE N'%'+@TuKhoa+N'%'
              OR T.TenVietTat LIKE N'%'+@TuKhoa+N'%'
              OR T.LOINCCode LIKE N'%'+@TuKhoa+N'%'
          )
    )
    SELECT *
    FROM S
    ORDER BY Active DESC,TenTriSo,ID
    OFFSET (@Trang-1)*@KichThuocTrang ROWS
    FETCH NEXT @KichThuocTrang ROWS ONLY;
END;
GO

/* ==================== STO_QL_CLS_DM_TriSo_Import ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_CLS_DM_TriSo_Import
    @IDCSKCB BIGINT,
    @DuLieuJson NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @IDCSKCB<=0
    BEGIN
        SELECT 400 Status,N'Thieu co so kham chua benh.' Message,0 SoDong,0 SoThem,0 SoCapNhat,N'[]' LoiJson;
        RETURN;
    END;

    IF ISJSON(ISNULL(@DuLieuJson,N''))<>1
    BEGIN
        SELECT 400 Status,N'Du lieu import khong dung JSON.' Message,0 SoDong,0 SoThem,0 SoCapNhat,N'[]' LoiJson;
        RETURN;
    END;

    DECLARE @D TABLE
    (
        DongExcel INT NOT NULL,
        MaTriSo NVARCHAR(100) NULL,
        TenTriSo NVARCHAR(1000) NULL,
        TenVietTat NVARCHAR(255) NULL,
        LOINCCode NVARCHAR(50) NULL,
        LOINCComponent NVARCHAR(255) NULL,
        LOINCProperty NVARCHAR(255) NULL,
        LOINCTimeAspect NVARCHAR(255) NULL,
        LOINCSystem NVARCHAR(255) NULL,
        LOINCScale NVARCHAR(255) NULL,
        LOINCMethod NVARCHAR(255) NULL,
        LoaiDuLieu NVARCHAR(20) NULL,
        Active BIT NOT NULL,
        LaMoi BIT NULL,
        Loi NVARCHAR(2000) NULL
    );

    INSERT @D
    (
        DongExcel,MaTriSo,TenTriSo,TenVietTat,LOINCCode,LOINCComponent,LOINCProperty,
        LOINCTimeAspect,LOINCSystem,LOINCScale,LOINCMethod,LoaiDuLieu,Active
    )
    SELECT
        ISNULL(J.DongExcel,0),NULLIF(LTRIM(RTRIM(J.MaTriSo)),N''),NULLIF(LTRIM(RTRIM(J.TenTriSo)),N''),
        NULLIF(LTRIM(RTRIM(J.TenVietTat)),N''),NULLIF(LTRIM(RTRIM(J.LOINCCode)),N''),
        NULLIF(LTRIM(RTRIM(J.LOINCComponent)),N''),NULLIF(LTRIM(RTRIM(J.LOINCProperty)),N''),
        NULLIF(LTRIM(RTRIM(J.LOINCTimeAspect)),N''),NULLIF(LTRIM(RTRIM(J.LOINCSystem)),N''),
        NULLIF(LTRIM(RTRIM(J.LOINCScale)),N''),NULLIF(LTRIM(RTRIM(J.LOINCMethod)),N''),
        UPPER(ISNULL(NULLIF(LTRIM(RTRIM(J.LoaiDuLieu)),N''),N'NUMBER')),ISNULL(J.Active,1)
    FROM OPENJSON(@DuLieuJson)
    WITH
    (
        DongExcel INT '$.dong_excel',
        MaTriSo NVARCHAR(100) '$.ma_tri_so',
        TenTriSo NVARCHAR(1000) '$.ten_tri_so',
        TenVietTat NVARCHAR(255) '$.ten_viet_tat',
        LOINCCode NVARCHAR(50) '$.loinc_code',
        LOINCComponent NVARCHAR(255) '$.loinc_component',
        LOINCProperty NVARCHAR(255) '$.loinc_property',
        LOINCTimeAspect NVARCHAR(255) '$.loinc_time_aspect',
        LOINCSystem NVARCHAR(255) '$.loinc_system',
        LOINCScale NVARCHAR(255) '$.loinc_scale',
        LOINCMethod NVARCHAR(255) '$.loinc_method',
        LoaiDuLieu NVARCHAR(20) '$.loai_du_lieu',
        Active BIT '$.active'
    ) J;

    IF NOT EXISTS(SELECT 1 FROM @D)
    BEGIN
        SELECT 400 Status,N'Excel khong co dong tri so de import.' Message,0 SoDong,0 SoThem,0 SoCapNhat,N'[]' LoiJson;
        RETURN;
    END;

    UPDATE D
    SET Loi=NULLIF(CONCAT_WS(N'; ',
        CASE WHEN DongExcel<=1 THEN N'So dong Excel khong hop le' END,
        CASE WHEN MaTriSo IS NULL THEN N'Thieu Ma tri so' END,
        CASE WHEN TenTriSo IS NULL THEN N'Thieu Ten tri so' END,
        CASE WHEN LEN(ISNULL(MaTriSo,N''))>100 THEN N'Ma tri so vuot 100 ky tu' END,
        CASE WHEN LEN(ISNULL(TenTriSo,N''))>1000 THEN N'Ten tri so vuot 1000 ky tu' END,
        CASE WHEN LEN(ISNULL(TenVietTat,N''))>255 THEN N'Ten viet tat vuot 255 ky tu' END,
        CASE WHEN LEN(ISNULL(LOINCCode,N''))>50 THEN N'LOINC vuot 50 ky tu' END,
        CASE WHEN LoaiDuLieu NOT IN(N'NUMBER',N'TEXT',N'CHOICE',N'BOOLEAN') THEN N'Loai du lieu chi nhan NUMBER/TEXT/CHOICE/BOOLEAN' END
    ),N'')
    FROM @D D;

    ;WITH Dup AS
    (
        SELECT MaTriSo FROM @D WHERE MaTriSo IS NOT NULL
        GROUP BY MaTriSo HAVING COUNT(*)>1
    )
    UPDATE D
    SET Loi=CONCAT_WS(N'; ',NULLIF(D.Loi,N''),N'Trung Ma tri so trong file Excel')
    FROM @D D
    INNER JOIN Dup X ON X.MaTriSo=D.MaTriSo;

    UPDATE D
    SET LaMoi=CASE WHEN EXISTS
    (
        SELECT 1 FROM dbo.QL_CLS_DM_TriSoXN T
        WHERE T.IDCSKCB=@IDCSKCB AND T.MaTriSo=D.MaTriSo
    ) THEN 0 ELSE 1 END
    FROM @D D
    WHERE D.MaTriSo IS NOT NULL;

    DECLARE @SoDong INT=(SELECT COUNT(*) FROM @D);
    DECLARE @SoLoi INT=(SELECT COUNT(*) FROM @D WHERE Loi IS NOT NULL);
    DECLARE @SoThem INT=(SELECT COUNT(*) FROM @D WHERE LaMoi=1);
    DECLARE @SoCapNhat INT=(SELECT COUNT(*) FROM @D WHERE LaMoi=0);

    IF @SoLoi>0
    BEGIN
        DECLARE @LoiJson NVARCHAR(MAX)=
        (
            SELECT DongExcel,MaTriSo,TenTriSo,Loi
            FROM @D WHERE Loi IS NOT NULL ORDER BY DongExcel
            FOR JSON PATH
        );
        SELECT 400 Status,
               CONCAT(N'Excel co ',@SoLoi,N' dong loi. Chua import du lieu nao.') Message,
               @SoDong SoDong,0 SoThem,0 SoCapNhat,ISNULL(@LoiJson,N'[]') LoiJson;
        RETURN;
    END;

    BEGIN TRY
        BEGIN TRAN;

        UPDATE T
        SET T.TenTriSo=D.TenTriSo,
            T.TenVietTat=D.TenVietTat,
            T.LOINCCode=D.LOINCCode,
            T.LOINCComponent=D.LOINCComponent,
            T.LOINCProperty=D.LOINCProperty,
            T.LOINCTimeAspect=D.LOINCTimeAspect,
            T.LOINCSystem=D.LOINCSystem,
            T.LOINCScale=D.LOINCScale,
            T.LOINCMethod=D.LOINCMethod,
            T.LoaiDuLieu=D.LoaiDuLieu,
            T.Active=D.Active,
            T.NgayCapNhat=SYSDATETIME()
        FROM dbo.QL_CLS_DM_TriSoXN T
        INNER JOIN @D D ON D.MaTriSo=T.MaTriSo
        WHERE T.IDCSKCB=@IDCSKCB AND D.LaMoi=0;

        INSERT dbo.QL_CLS_DM_TriSoXN
        (
            IDCSKCB,MaTriSo,TenTriSo,TenVietTat,LOINCCode,LOINCComponent,LOINCProperty,
            LOINCTimeAspect,LOINCSystem,LOINCScale,LOINCMethod,LoaiDuLieu,Active
        )
        SELECT
            @IDCSKCB,D.MaTriSo,D.TenTriSo,D.TenVietTat,D.LOINCCode,D.LOINCComponent,D.LOINCProperty,
            D.LOINCTimeAspect,D.LOINCSystem,D.LOINCScale,D.LOINCMethod,D.LoaiDuLieu,D.Active
        FROM @D D
        WHERE D.LaMoi=1;

        COMMIT;

        SELECT 200 Status,
               CONCAT(N'Import danh muc tri so thanh cong: them ',@SoThem,N', cap nhat ',@SoCapNhat,N'.') Message,
               @SoDong SoDong,@SoThem SoThem,@SoCapNhat SoCapNhat,N'[]' LoiJson;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK;
        SELECT 500 Status,ERROR_MESSAGE() Message,@SoDong SoDong,0 SoThem,0 SoCapNhat,N'[]' LoiJson;
    END CATCH;
END;
GO

/* ==================== STO_QL_CLS_KetQua_ChiTiet ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_CLS_KetQua_ChiTiet
    @IDCSKCB BIGINT,
    @IDChiDinhCT BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE
        @IDDichVu BIGINT,@IDBenhNhan BIGINT,@IDGioiTinh TINYINT,
        @NgaySinh DATE,@Tuoi DECIMAL(10,2),@LoaiKetQua TINYINT,
        @IDForm BIGINT,@IDPhieu BIGINT;

    SELECT @IDDichVu=C.IDDichVu,@IDBenhNhan=V.IDBenhNhan
    FROM dbo.QL_ChiDinh_CT C
    INNER JOIN dbo.QL_VaoVien V ON V.IDCSKCB=C.IDCSKCB AND V.ID=C.IDVaoVien
    WHERE C.IDCSKCB=@IDCSKCB AND C.ID=@IDChiDinhCT
      AND C.Active=1 AND V.Active=1 AND V.TrangThaiKham<>3;

    IF @IDDichVu IS NULL
    BEGIN
        SELECT 404 AS Status,N'Không tìm thấy chỉ định CLS hợp lệ.' AS Message;
        SELECT TOP 0 CAST(NULL AS BIGINT) AS IDTriSoXN;
        SELECT TOP 0 CAST(NULL AS BIGINT) AS ID;
        RETURN;
    END;

    SELECT @IDGioiTinh=IDGioiTinh,@NgaySinh=NgaySinh
    FROM dbo.QL_BenhNhan
    WHERE IDCSKCB=@IDCSKCB AND ID=@IDBenhNhan;

    SET @Tuoi=CASE WHEN @NgaySinh IS NULL THEN NULL
        ELSE CONVERT(DECIMAL(10,2),DATEDIFF(DAY,@NgaySinh,CONVERT(DATE,GETDATE())))/365.25 END;

    SELECT @LoaiKetQua=ISNULL(LoaiKetQua,0),@IDForm=IDFormKQ
    FROM dbo.DM_DichVu
    WHERE IDCSKCB=@IDCSKCB AND ID=@IDDichVu;

    SELECT @IDPhieu=ID
    FROM dbo.QL_CLS_PhieuKetQua
    WHERE IDCSKCB=@IDCSKCB AND IDChiDinhCT=@IDChiDinhCT AND Active=1;

    IF @IDPhieu IS NOT NULL
        SELECT @LoaiKetQua=P.LoaiKetQua,@IDForm=COALESCE(P.IDForm,@IDForm)
        FROM dbo.QL_CLS_PhieuKetQua P
        WHERE P.IDCSKCB=@IDCSKCB AND P.ID=@IDPhieu;

    IF @LoaiKetQua NOT IN(1,2)
    BEGIN
        SELECT 409 AS Status,N'Dịch vụ chưa cấu hình kết quả CLS. Hãy cấu hình trước khi nhập kết quả.' AS Message;
        SELECT TOP 0 CAST(NULL AS BIGINT) AS IDTriSoXN;
        SELECT TOP 0 CAST(NULL AS BIGINT) AS ID;
        RETURN;
    END;

    SELECT
        200 AS Status,N'Thành công.' AS Message,
        C.ID AS IDChiDinhCT,C.IDVaoVien,C.IDDichVu,
        D.MaDichVu,D.TenDichVu,D.DonViTinh,
        @LoaiKetQua AS LoaiKetQua,@IDForm AS IDForm,F.TenForm,
        P.ID AS IDPhieuKetQua,P.SoPhieu,P.NgayGioThucHien,P.NgayGioKetQua,
        P.IDNVThucHien,NV.HoTen AS NguoiThucHien,
        P.IDBSDoc,BS.HoTen AS BacSiDoc,
        P.MoTa,P.KetLuan,P.DeNghi,P.TenVungKhaoSat,
        ISNULL(P.TrangThai,0) AS TrangThai,
        B.ID AS IDBenhNhan,B.MaBN,B.HoTen,B.NgaySinh,B.IDGioiTinh,GT.TenGioiTinh,@Tuoi AS Tuoi
    FROM dbo.QL_ChiDinh_CT C
    INNER JOIN dbo.DM_DichVu D ON D.IDCSKCB=C.IDCSKCB AND D.ID=C.IDDichVu
    INNER JOIN dbo.QL_VaoVien V ON V.IDCSKCB=C.IDCSKCB AND V.ID=C.IDVaoVien
    INNER JOIN dbo.QL_BenhNhan B ON B.IDCSKCB=V.IDCSKCB AND B.ID=V.IDBenhNhan
    LEFT JOIN dbo.DM_GioiTinh GT ON GT.ID=B.IDGioiTinh
    LEFT JOIN dbo.QL_CLS_FormKQXN F ON F.IDCSKCB=@IDCSKCB AND F.ID=@IDForm
    LEFT JOIN dbo.QL_CLS_PhieuKetQua P
      ON P.IDCSKCB=C.IDCSKCB AND P.IDChiDinhCT=C.ID AND P.Active=1
    LEFT JOIN dbo.DM_NhanVien NV ON NV.IDCSKCB=P.IDCSKCB AND NV.ID=P.IDNVThucHien
    LEFT JOIN dbo.DM_NhanVien BS ON BS.IDCSKCB=P.IDCSKCB AND BS.ID=P.IDBSDoc
    WHERE C.IDCSKCB=@IDCSKCB AND C.ID=@IDChiDinhCT;

    ;WITH ConfigHopLe AS
    (
        SELECT
            C.*,
            ROW_NUMBER() OVER
            (
                PARTITION BY C.IDTriSoXN
                ORDER BY
                    CASE WHEN C.IDGioiTinh=@IDGioiTinh THEN 0 ELSE 1 END,
                    CASE WHEN C.GHTuoi=1 THEN 0 ELSE 1 END,
                    CASE WHEN C.GHTuoi=1
                         THEN ISNULL(C.TuoiMax,999.0)-ISNULL(C.TuoiMin,0.0)
                         ELSE 9999 END,
                    C.STT,C.ID
            ) AS rn
        FROM dbo.QL_CLS_FormKQXN_CT C
        WHERE C.IDCSKCB=@IDCSKCB
          AND C.IDForm=@IDForm
          AND C.Active=1
          AND (C.IDGioiTinh IS NULL OR C.IDGioiTinh=@IDGioiTinh)
          AND
          (
              C.GHTuoi=0
              OR
              (
                  @Tuoi IS NOT NULL
                  AND (C.TuoiMin IS NULL OR @Tuoi>=C.TuoiMin)
                  AND (C.TuoiMax IS NULL OR @Tuoi<=C.TuoiMax)
              )
          )
    )
    SELECT
        T.ID AS IDTriSoXN,T.MaTriSo,COALESCE(NULLIF(C.TenHienThi,N''),T.TenTriSo) AS TenTriSo,
        CASE WHEN @IDGioiTinh=2 AND NULLIF(C.DonViTinh2,N'') IS NOT NULL
             THEN C.DonViTinh2 ELSE C.DonViTinh END AS DonViTinh,
        C.DinhLuong,C.LuongDinhTinh,C.TuyetDoi,C.LamTron,C.Nguong,C.Tieude,
        C.CongThuc,C.CongThucMoi,
        CASE WHEN @IDGioiTinh=2 AND NULLIF(C.TriSoBinhThuong2,N'') IS NOT NULL
             THEN C.TriSoBinhThuong2 ELSE C.TriSoBinhThuong1 END AS TriSoBinhThuong,
        CASE WHEN @IDGioiTinh=2 AND (C.GHMin2 IS NOT NULL OR C.GHMax2 IS NOT NULL)
             THEN C.GHMin2 ELSE C.GHMin1 END AS GHMin,
        CASE WHEN @IDGioiTinh=2 AND (C.GHMin2 IS NOT NULL OR C.GHMax2 IS NOT NULL)
             THEN C.GHMax2 ELSE C.GHMax1 END AS GHMax,
        CASE WHEN @IDGioiTinh=2 AND NULLIF(C.MacDinh2,N'') IS NOT NULL
             THEN C.MacDinh2 ELSE C.MacDinh1 END AS MacDinh,
        C.IDGioiTinh,C.GHTuoi,C.TuoiMin,C.TuoiMax,C.STT,
        K.ID AS IDKetQuaCT,
        COALESCE
        (
            K.GiaTri,
            CASE WHEN @IDGioiTinh=2 AND NULLIF(C.MacDinh2,N'') IS NOT NULL
                 THEN C.MacDinh2 ELSE C.MacDinh1 END
        ) AS GiaTri,
        K.GiaTriSo,K.DanhGia,K.GhiChu,K.Trai,K.Phai,
        COALESCE(K.CongThuc,C.CongThuc) AS CongThucKetQua
    FROM ConfigHopLe C
    INNER JOIN dbo.QL_CLS_DM_TriSoXN T
      ON T.IDCSKCB=C.IDCSKCB AND T.ID=C.IDTriSoXN AND T.Active=1
    LEFT JOIN dbo.QL_CLS_KetQuaXN_CT K
      ON K.IDCSKCB=C.IDCSKCB AND K.IDPhieuKetQua=@IDPhieu AND K.IDTriSoXN=T.ID
    WHERE C.rn=1
    ORDER BY C.STT,T.ID;

    SELECT ID,TenFileGoc,DuongDanTuongDoi,MimeType,KichThuoc,NgayTaiLen,IDNhanVienTaiLen
    FROM dbo.QL_CLS_PhieuKetQua_File
    WHERE IDCSKCB=@IDCSKCB AND IDPhieuKetQua=@IDPhieu AND Active=1
    ORDER BY NgayTaiLen DESC,ID DESC;
END;
GO





/* ==================== STO_QL_CLS_KetQua_LayFile ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_CLS_KetQua_LayFile
    @IDCSKCB BIGINT,@IDFile BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT TOP 1 ID,TenFileGoc,DuongDanTuongDoi,MimeType,KichThuoc,IDNhanVienTaiLen,NgayTaiLen,IDPhieuKetQua
    FROM dbo.QL_CLS_PhieuKetQua_File WHERE IDCSKCB=@IDCSKCB AND ID=@IDFile AND Active=1;
END;
GO



CREATE OR ALTER PROCEDURE dbo.STO_QL_CLS_KetQua_Luot
    @IDCSKCB BIGINT,
    @IDVaoVien BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        P.ID AS IDPhieuKetQua,P.IDChiDinhCT,C.IDDichVu,D.MaDichVu,D.TenDichVu,
        P.LoaiKetQua,P.SoPhieu,P.NgayGioThucHien,P.NgayGioKetQua,
        P.MoTa,P.KetLuan,P.DeNghi,P.TenVungKhaoSat,P.TrangThai,
        NV.HoTen AS NguoiThucHien,BS.HoTen AS BacSiDoc,
        ISNULL
        (
            (
                SELECT STRING_AGG
                (
                    CONCAT
                    (
                        T.TenTriSo,N': ',K.GiaTri,
                        CASE WHEN NULLIF(K.DonViTinh,N'') IS NULL THEN N'' ELSE N' '+K.DonViTinh END,
                        CASE K.DanhGia WHEN 1 THEN N' ↓' WHEN 2 THEN N' ↑' WHEN 3 THEN N' !' ELSE N'' END
                    ),N'; '
                )
                FROM dbo.QL_CLS_KetQuaXN_CT K
                INNER JOIN dbo.QL_CLS_DM_TriSoXN T
                  ON T.IDCSKCB=K.IDCSKCB AND T.ID=K.IDTriSoXN
                WHERE K.IDCSKCB=P.IDCSKCB AND K.IDPhieuKetQua=P.ID
            ),N''
        ) AS TomTatXN
    FROM dbo.QL_CLS_PhieuKetQua P
    INNER JOIN dbo.QL_ChiDinh_CT C ON C.IDCSKCB=P.IDCSKCB AND C.ID=P.IDChiDinhCT
    INNER JOIN dbo.DM_DichVu D ON D.IDCSKCB=C.IDCSKCB AND D.ID=C.IDDichVu
    LEFT JOIN dbo.DM_NhanVien NV ON NV.IDCSKCB=P.IDCSKCB AND NV.ID=P.IDNVThucHien
    LEFT JOIN dbo.DM_NhanVien BS ON BS.IDCSKCB=P.IDCSKCB AND BS.ID=P.IDBSDoc
    WHERE P.IDCSKCB=@IDCSKCB AND C.IDVaoVien=@IDVaoVien AND P.Active=1
    ORDER BY P.ID;

    SELECT
        K.IDPhieuKetQua,K.IDTriSoXN,T.MaTriSo,T.TenTriSo,K.STT,
        K.GiaTri,K.GiaTriSo,K.DonViTinh,K.TriSoBinhThuong,
        K.GHMin,K.GHMax,K.DanhGia,K.GhiChu,K.Trai,K.Phai,K.CongThuc
    FROM dbo.QL_CLS_KetQuaXN_CT K
    INNER JOIN dbo.QL_CLS_DM_TriSoXN T ON T.IDCSKCB=K.IDCSKCB AND T.ID=K.IDTriSoXN
    INNER JOIN dbo.QL_CLS_PhieuKetQua P ON P.IDCSKCB=K.IDCSKCB AND P.ID=K.IDPhieuKetQua
    INNER JOIN dbo.QL_ChiDinh_CT C ON C.IDCSKCB=P.IDCSKCB AND C.ID=P.IDChiDinhCT
    WHERE P.IDCSKCB=@IDCSKCB AND C.IDVaoVien=@IDVaoVien AND P.Active=1
    ORDER BY K.IDPhieuKetQua,K.STT,K.ID;

    SELECT F.ID,F.IDPhieuKetQua,F.TenFileGoc,F.MimeType,F.KichThuoc,F.NgayTaiLen
    FROM dbo.QL_CLS_PhieuKetQua_File F
    INNER JOIN dbo.QL_CLS_PhieuKetQua P ON P.IDCSKCB=F.IDCSKCB AND P.ID=F.IDPhieuKetQua
    INNER JOIN dbo.QL_ChiDinh_CT C ON C.IDCSKCB=P.IDCSKCB AND C.ID=P.IDChiDinhCT
    WHERE P.IDCSKCB=@IDCSKCB AND C.IDVaoVien=@IDVaoVien
      AND P.Active=1 AND F.Active=1
    ORDER BY F.IDPhieuKetQua,F.NgayTaiLen DESC,F.ID DESC;
END;
GO

/* ==================== STO_QL_CLS_KetQua_Luu ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_CLS_KetQua_Luu
    @IDCSKCB BIGINT,
    @IDChiDinhCT BIGINT,
    @IDNhanVien BIGINT,
    @IDNVThucHien BIGINT=NULL,
    @IDBSDoc BIGINT=NULL,
    @NgayGioThucHien DATETIME2(0)=NULL,
    @MoTa NVARCHAR(MAX)=NULL,
    @KetLuan NVARCHAR(4000)=NULL,
    @DeNghi NVARCHAR(2000)=NULL,
    @TenVungKhaoSat NVARCHAR(1000)=NULL,
    @KetQuaJson NVARCHAR(MAX)=N'[]',
    @TrangThai TINYINT=2
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRAN;

        DECLARE
            @IDDichVu BIGINT,@IDBenhNhan BIGINT,@IDGioiTinh TINYINT,
            @NgaySinh DATE,@Tuoi DECIMAL(10,2),@LoaiKetQua TINYINT,
            @IDForm BIGINT,@IDPhieu BIGINT,
            @DuLieuCu NVARCHAR(MAX),@DuLieuMoi NVARCHAR(MAX);

        SELECT @IDDichVu=C.IDDichVu,@IDBenhNhan=V.IDBenhNhan
        FROM dbo.QL_ChiDinh_CT C WITH(UPDLOCK,HOLDLOCK)
        INNER JOIN dbo.QL_VaoVien V ON V.IDCSKCB=C.IDCSKCB AND V.ID=C.IDVaoVien
        WHERE C.IDCSKCB=@IDCSKCB AND C.ID=@IDChiDinhCT
          AND C.Active=1 AND V.Active=1 AND V.TrangThaiKham<>3;

        IF @IDDichVu IS NULL
            THROW 58200,N'Không tìm thấy chỉ định CLS hợp lệ.',1;

        SELECT @IDGioiTinh=IDGioiTinh,@NgaySinh=NgaySinh
        FROM dbo.QL_BenhNhan
        WHERE IDCSKCB=@IDCSKCB AND ID=@IDBenhNhan;

        SET @Tuoi=CASE WHEN @NgaySinh IS NULL THEN NULL
            ELSE CONVERT(DECIMAL(10,2),DATEDIFF(DAY,@NgaySinh,CONVERT(DATE,GETDATE())))/365.25 END;

        SELECT @LoaiKetQua=ISNULL(LoaiKetQua,0),@IDForm=IDFormKQ
        FROM dbo.DM_DichVu
        WHERE IDCSKCB=@IDCSKCB AND ID=@IDDichVu;

        IF @LoaiKetQua NOT IN(1,2)
            THROW 58200,N'Dịch vụ chưa cấu hình kết quả CLS. Hãy cấu hình trước khi nhập kết quả.',1;

        SELECT @IDPhieu=ID
        FROM dbo.QL_CLS_PhieuKetQua
        WHERE IDCSKCB=@IDCSKCB AND IDChiDinhCT=@IDChiDinhCT AND Active=1;
IF @LoaiKetQua=1 AND (@IDForm IS NULL OR ISJSON(ISNULL(@KetQuaJson,N''))<>1)
            THROW 58200,N'Dịch vụ xét nghiệm chưa có form hoặc dữ liệu kết quả không hợp lệ.',1;

        IF @IDPhieu IS NOT NULL
        BEGIN
            SELECT @DuLieuCu=
            (
                SELECT
                    P.ID,P.LoaiKetQua,P.NgayGioThucHien,P.NgayGioKetQua,
                    P.IDNVThucHien,P.IDBSDoc,P.MoTa,P.KetLuan,P.DeNghi,
                    P.TenVungKhaoSat,P.TrangThai,
                    JSON_QUERY
                    (
                        (
                            SELECT
                                K.IDTriSoXN,K.GiaTri,K.GiaTriSo,K.DonViTinh,
                                K.TriSoBinhThuong,K.GHMin,K.GHMax,K.DanhGia,
                                K.GhiChu,K.Trai,K.Phai,K.CongThuc
                            FROM dbo.QL_CLS_KetQuaXN_CT K
                            WHERE K.IDCSKCB=P.IDCSKCB AND K.IDPhieuKetQua=P.ID
                            ORDER BY K.STT,K.ID
                            FOR JSON PATH
                        )
                    ) AS ChiTiet
                FROM dbo.QL_CLS_PhieuKetQua P
                WHERE P.IDCSKCB=@IDCSKCB AND P.ID=@IDPhieu
                FOR JSON PATH,WITHOUT_ARRAY_WRAPPER
            );
        END;

        SET @IDNVThucHien=COALESCE(@IDNVThucHien,@IDNhanVien);
        SET @IDBSDoc=COALESCE(@IDBSDoc,@IDNhanVien);
        SET @NgayGioThucHien=COALESCE(@NgayGioThucHien,SYSDATETIME());
        SET @TrangThai=CASE WHEN @TrangThai=1 THEN 1 ELSE 2 END;

        IF @IDPhieu IS NULL
        BEGIN
            INSERT dbo.QL_CLS_PhieuKetQua
            (
                IDCSKCB,IDChiDinhCT,IDForm,LoaiKetQua,
                NgayGioThucHien,NgayGioKetQua,IDNVThucHien,IDBSDoc,
                MoTa,KetLuan,DeNghi,TenVungKhaoSat,TrangThai,Active
            )
            VALUES
            (
                @IDCSKCB,@IDChiDinhCT,@IDForm,@LoaiKetQua,
                @NgayGioThucHien,CASE WHEN @TrangThai=2 THEN SYSDATETIME() END,
                @IDNVThucHien,@IDBSDoc,
                NULLIF(@MoTa,N''),NULLIF(@KetLuan,N''),NULLIF(@DeNghi,N''),
                NULLIF(@TenVungKhaoSat,N''),@TrangThai,1
            );
            SET @IDPhieu=SCOPE_IDENTITY();

            UPDATE dbo.QL_CLS_PhieuKetQua
            SET SoPhieu=N'KQ'+CASE
                WHEN @IDPhieu<1000000 THEN RIGHT(N'000000'+CONVERT(NVARCHAR(20),@IDPhieu),6)
                ELSE CONVERT(NVARCHAR(20),@IDPhieu) END
            WHERE IDCSKCB=@IDCSKCB AND ID=@IDPhieu;
        END
        ELSE
        BEGIN
            UPDATE dbo.QL_CLS_PhieuKetQua
            SET
                IDForm=@IDForm,LoaiKetQua=@LoaiKetQua,
                NgayGioThucHien=@NgayGioThucHien,
                NgayGioKetQua=CASE WHEN @TrangThai=2 THEN COALESCE(NgayGioKetQua,SYSDATETIME()) ELSE NgayGioKetQua END,
                IDNVThucHien=@IDNVThucHien,IDBSDoc=@IDBSDoc,
                MoTa=NULLIF(@MoTa,N''),KetLuan=NULLIF(@KetLuan,N''),
                DeNghi=NULLIF(@DeNghi,N''),TenVungKhaoSat=NULLIF(@TenVungKhaoSat,N''),
                TrangThai=@TrangThai,NgayCapNhat=SYSDATETIME()
            WHERE IDCSKCB=@IDCSKCB AND ID=@IDPhieu;
        END;

        IF @LoaiKetQua=1
        BEGIN
            DECLARE @KQ TABLE
            (
                IDTriSoXN BIGINT PRIMARY KEY,
                GiaTri NVARCHAR(1000) NULL,
                DanhGiaManual TINYINT NULL,
                GhiChu NVARCHAR(1000) NULL,
                Trai NVARCHAR(200) NULL,
                Phai NVARCHAR(200) NULL,
                CongThuc NVARCHAR(MAX) NULL,
                STT INT NOT NULL
            );

            INSERT @KQ(IDTriSoXN,GiaTri,DanhGiaManual,GhiChu,Trai,Phai,CongThuc,STT)
            SELECT
                IDTriSoXN,
                NULLIF(LTRIM(RTRIM(GiaTri)),N''),
                DanhGia,
                NULLIF(LTRIM(RTRIM(GhiChu)),N''),
                NULLIF(LTRIM(RTRIM(Trai)),N''),
                NULLIF(LTRIM(RTRIM(Phai)),N''),
                NULLIF(LTRIM(RTRIM(CongThuc)),N''),
                ISNULL(STT,999)
            FROM OPENJSON(@KetQuaJson)
            WITH
            (
                IDTriSoXN BIGINT '$.id_tri_so',
                GiaTri NVARCHAR(1000) '$.gia_tri',
                DanhGia TINYINT '$.danh_gia',
                GhiChu NVARCHAR(1000) '$.ghi_chu',
                Trai NVARCHAR(200) '$.trai',
                Phai NVARCHAR(200) '$.phai',
                CongThuc NVARCHAR(MAX) '$.cong_thuc',
                STT INT '$.stt'
            )
            WHERE IDTriSoXN IS NOT NULL;

            IF EXISTS
            (
                SELECT 1
                FROM @KQ K
                WHERE NOT EXISTS
                (
                    SELECT 1
                    FROM dbo.QL_CLS_FormKQXN_CT F
                    WHERE F.IDCSKCB=@IDCSKCB AND F.IDForm=@IDForm
                      AND F.IDTriSoXN=K.IDTriSoXN AND F.Active=1
                )
            )
                THROW 58200,N'Có trị số không thuộc form xét nghiệm.',1;

            DELETE dbo.QL_CLS_KetQuaXN_CT
            WHERE IDCSKCB=@IDCSKCB AND IDPhieuKetQua=@IDPhieu;

            ;WITH S AS
            (
                SELECT
                    K.IDTriSoXN,K.GiaTri,K.DanhGiaManual,K.GhiChu,K.Trai,K.Phai,
                    COALESCE(K.CongThuc,C.CongThuc) AS CongThuc,K.STT,
                    C.DinhLuong,
                    CASE WHEN @IDGioiTinh=2 AND NULLIF(C.DonViTinh2,N'') IS NOT NULL
                         THEN C.DonViTinh2 ELSE C.DonViTinh END AS DonViTinh,
                    CASE WHEN @IDGioiTinh=2 AND NULLIF(C.TriSoBinhThuong2,N'') IS NOT NULL
                         THEN C.TriSoBinhThuong2 ELSE C.TriSoBinhThuong1 END AS TriSoBinhThuong,
                    CASE WHEN @IDGioiTinh=2 AND (C.GHMin2 IS NOT NULL OR C.GHMax2 IS NOT NULL)
                         THEN C.GHMin2 ELSE C.GHMin1 END AS GHMin,
                    CASE WHEN @IDGioiTinh=2 AND (C.GHMin2 IS NOT NULL OR C.GHMax2 IS NOT NULL)
                         THEN C.GHMax2 ELSE C.GHMax1 END AS GHMax,
                    TRY_CONVERT(DECIMAL(18,6),REPLACE(K.GiaTri,N',',N'.')) AS GiaTriSo
                FROM @KQ K
                INNER JOIN dbo.QL_CLS_DM_TriSoXN T
                  ON T.IDCSKCB=@IDCSKCB AND T.ID=K.IDTriSoXN AND T.Active=1
                CROSS APPLY
                (
                    SELECT TOP(1) C0.*
                    FROM dbo.QL_CLS_FormKQXN_CT C0
                    WHERE C0.IDCSKCB=@IDCSKCB
                      AND C0.IDForm=@IDForm
                      AND C0.IDTriSoXN=K.IDTriSoXN
                      AND C0.Active=1
                      AND (C0.IDGioiTinh IS NULL OR C0.IDGioiTinh=@IDGioiTinh)
                      AND
                      (
                          C0.GHTuoi=0
                          OR
                          (
                              @Tuoi IS NOT NULL
                              AND (C0.TuoiMin IS NULL OR @Tuoi>=C0.TuoiMin)
                              AND (C0.TuoiMax IS NULL OR @Tuoi<=C0.TuoiMax)
                          )
                      )
                    ORDER BY
                        CASE WHEN C0.IDGioiTinh=@IDGioiTinh THEN 0 ELSE 1 END,
                        CASE WHEN C0.GHTuoi=1 THEN 0 ELSE 1 END,
                        CASE WHEN C0.GHTuoi=1
                             THEN ISNULL(C0.TuoiMax,999.0)-ISNULL(C0.TuoiMin,0.0)
                             ELSE 9999 END,
                        C0.STT,C0.ID
                ) C
            )
            INSERT dbo.QL_CLS_KetQuaXN_CT
            (
                IDCSKCB,IDPhieuKetQua,IDTriSoXN,STT,
                GiaTri,GiaTriSo,DonViTinh,TriSoBinhThuong,GHMin,GHMax,
                DanhGia,GhiChu,Trai,Phai,CongThuc
            )
            SELECT
                @IDCSKCB,@IDPhieu,IDTriSoXN,STT,
                GiaTri,GiaTriSo,DonViTinh,TriSoBinhThuong,GHMin,GHMax,
                CASE
                    WHEN DinhLuong=1 AND GiaTriSo IS NOT NULL AND GHMin IS NOT NULL AND GiaTriSo<GHMin THEN 1
                    WHEN DinhLuong=1 AND GiaTriSo IS NOT NULL AND GHMax IS NOT NULL AND GiaTriSo>GHMax THEN 2
                    WHEN DinhLuong=1 AND GiaTriSo IS NOT NULL THEN 0
                    ELSE CASE WHEN ISNULL(DanhGiaManual,0) BETWEEN 0 AND 3 THEN ISNULL(DanhGiaManual,0) ELSE 0 END
                END,
                GhiChu,Trai,Phai,CongThuc
            FROM S
            WHERE GiaTri IS NOT NULL OR GhiChu IS NOT NULL OR Trai IS NOT NULL OR Phai IS NOT NULL;
        END;

        UPDATE dbo.QL_ChiDinh_CT
        SET TrangThai=CASE WHEN @TrangThai>=2 THEN 2 ELSE 1 END
        WHERE IDCSKCB=@IDCSKCB AND ID=@IDChiDinhCT;

        SELECT @DuLieuMoi=
        (
            SELECT
                P.ID,P.LoaiKetQua,P.NgayGioThucHien,P.NgayGioKetQua,
                P.IDNVThucHien,P.IDBSDoc,P.MoTa,P.KetLuan,P.DeNghi,
                P.TenVungKhaoSat,P.TrangThai,
                JSON_QUERY
                (
                    (
                        SELECT
                            K.IDTriSoXN,K.GiaTri,K.GiaTriSo,K.DonViTinh,
                            K.TriSoBinhThuong,K.GHMin,K.GHMax,K.DanhGia,
                            K.GhiChu,K.Trai,K.Phai,K.CongThuc
                        FROM dbo.QL_CLS_KetQuaXN_CT K
                        WHERE K.IDCSKCB=P.IDCSKCB AND K.IDPhieuKetQua=P.ID
                        ORDER BY K.STT,K.ID
                        FOR JSON PATH
                    )
                ) AS ChiTiet
            FROM dbo.QL_CLS_PhieuKetQua P
            WHERE P.IDCSKCB=@IDCSKCB AND P.ID=@IDPhieu
            FOR JSON PATH,WITHOUT_ARRAY_WRAPPER
        );

        INSERT dbo.QL_CLS_KetQua_LichSu
            (IDCSKCB,IDPhieuKetQua,HanhDong,DuLieuCu,DuLieuMoi,IDNhanVien)
        VALUES
            (@IDCSKCB,@IDPhieu,CASE WHEN @DuLieuCu IS NULL THEN N'TAO' ELSE N'SUA' END,
             @DuLieuCu,@DuLieuMoi,@IDNhanVien);

        COMMIT;
        SELECT 200 AS Status,
               CASE WHEN @TrangThai=1 THEN N'Đã lưu kết quả đang nhập.' ELSE N'Đã lưu kết quả CLS.' END AS Message,
               @IDPhieu AS IDPhieuKetQua;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK;
        SELECT 400 AS Status,ERROR_MESSAGE() AS Message,CAST(NULL AS BIGINT) AS IDPhieuKetQua;
    END CATCH;
END;

GO

/* ==================== STO_QL_CLS_KetQua_ThemFile ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_CLS_KetQua_ThemFile
    @IDCSKCB BIGINT,@IDChiDinhCT BIGINT,@TenFileGoc NVARCHAR(500),@DuongDanTuongDoi NVARCHAR(1000),
    @MimeType NVARCHAR(200)=NULL,@KichThuoc BIGINT,@IDNhanVien BIGINT=NULL
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;
    BEGIN TRY
        BEGIN TRAN;
        DECLARE @IDPhieu BIGINT,@IDDichVu BIGINT,@LoaiKetQua TINYINT,@IDForm BIGINT;
        SELECT @IDDichVu=C.IDDichVu FROM dbo.QL_ChiDinh_CT C
        INNER JOIN dbo.QL_VaoVien V ON V.IDCSKCB=C.IDCSKCB AND V.ID=C.IDVaoVien
        WHERE C.IDCSKCB=@IDCSKCB AND C.ID=@IDChiDinhCT AND C.Active=1 AND V.Active=1 AND V.TrangThaiKham<>3;
        IF @IDDichVu IS NULL THROW 58400,N'Không tìm thấy chỉ định CLS hợp lệ.',1;
        SELECT @IDPhieu=ID FROM dbo.QL_CLS_PhieuKetQua WHERE IDCSKCB=@IDCSKCB AND IDChiDinhCT=@IDChiDinhCT AND Active=1;
        IF @IDPhieu IS NULL
        BEGIN
            SELECT @LoaiKetQua=LoaiKetQua,@IDForm=IDFormKQ FROM dbo.DM_DichVu WHERE IDCSKCB=@IDCSKCB AND ID=@IDDichVu;
            SET @LoaiKetQua=ISNULL(@LoaiKetQua,0);
            IF @LoaiKetQua NOT IN(1,2)
                THROW 58400,N'Dịch vụ chưa cấu hình kết quả CLS. Hãy cấu hình trước khi tải file.',1;
            INSERT dbo.QL_CLS_PhieuKetQua
            (IDCSKCB,IDChiDinhCT,IDForm,LoaiKetQua,NgayGioThucHien,NgayGioKetQua,IDNVThucHien,IDBSDoc,TrangThai,Active)
            VALUES(@IDCSKCB,@IDChiDinhCT,@IDForm,@LoaiKetQua,SYSDATETIME(),SYSDATETIME(),@IDNhanVien,@IDNhanVien,2,1);
            SET @IDPhieu=SCOPE_IDENTITY();
            UPDATE dbo.QL_CLS_PhieuKetQua SET SoPhieu=N'KQ'+CASE WHEN @IDPhieu<1000000 THEN RIGHT(N'000000'+CONVERT(NVARCHAR(20),@IDPhieu),6) ELSE CONVERT(NVARCHAR(20),@IDPhieu) END
            WHERE IDCSKCB=@IDCSKCB AND ID=@IDPhieu;
        END;
        INSERT dbo.QL_CLS_PhieuKetQua_File
        (IDCSKCB,IDPhieuKetQua,TenFileGoc,DuongDanTuongDoi,MimeType,KichThuoc,IDNhanVienTaiLen,Active)
        VALUES(@IDCSKCB,@IDPhieu,@TenFileGoc,@DuongDanTuongDoi,@MimeType,@KichThuoc,@IDNhanVien,1);
        DECLARE @IDFile BIGINT=SCOPE_IDENTITY();
        UPDATE dbo.QL_ChiDinh_CT SET TrangThai=2 WHERE IDCSKCB=@IDCSKCB AND ID=@IDChiDinhCT;
        INSERT dbo.QL_CLS_KetQua_LichSu(IDCSKCB,IDPhieuKetQua,HanhDong,DuLieuMoi,IDNhanVien)
        VALUES(@IDCSKCB,@IDPhieu,N'THEM_FILE',(SELECT @IDFile IDFile,@TenFileGoc TenFile,@KichThuoc KichThuoc FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),@IDNhanVien);
        COMMIT;
        SELECT 200 Status,N'Đã tải file kết quả.' Message,@IDFile IDFile,@IDPhieu IDPhieuKetQua;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK;
        SELECT 400 Status,ERROR_MESSAGE() Message,CAST(NULL AS BIGINT) IDFile,CAST(NULL AS BIGINT) IDPhieuKetQua;
    END CATCH
END;

GO

/* ==================== STO_QL_CLS_KetQua_XoaFile ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_QL_CLS_KetQua_XoaFile
    @IDCSKCB BIGINT,@IDFile BIGINT,@IDNhanVien BIGINT=NULL
AS
BEGIN
    SET NOCOUNT ON; SET XACT_ABORT ON;
    BEGIN TRY
        BEGIN TRAN;
        DECLARE @IDPhieu BIGINT,@TenFile NVARCHAR(500);
        SELECT @IDPhieu=F.IDPhieuKetQua,@TenFile=F.TenFileGoc
        FROM dbo.QL_CLS_PhieuKetQua_File F INNER JOIN dbo.QL_CLS_PhieuKetQua P ON P.IDCSKCB=F.IDCSKCB AND P.ID=F.IDPhieuKetQua
        WHERE F.IDCSKCB=@IDCSKCB AND F.ID=@IDFile AND F.Active=1;
        IF @IDPhieu IS NULL THROW 58400,N'Không tìm thấy file.',1;
        UPDATE dbo.QL_CLS_PhieuKetQua_File SET Active=0 WHERE IDCSKCB=@IDCSKCB AND ID=@IDFile;
        INSERT dbo.QL_CLS_KetQua_LichSu(IDCSKCB,IDPhieuKetQua,HanhDong,DuLieuCu,IDNhanVien)
        VALUES(@IDCSKCB,@IDPhieu,N'XOA_FILE',(SELECT @IDFile IDFile,@TenFile TenFile FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),@IDNhanVien);
        COMMIT;
        SELECT 200 Status,N'Đã xóa file.' Message,@IDFile IDFile;
    END TRY
    BEGIN CATCH
        IF XACT_STATE()<>0 ROLLBACK;
        SELECT 400 Status,ERROR_MESSAGE() Message,@IDFile IDFile;
    END CATCH
END;
GO



/* ==================== STO_DM_VietTat_LayDanhSach ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_DM_VietTat_LayDanhSach
(
    @IDCSKCB BIGINT,
    @IDNhanVien BIGINT = NULL,
    @Loai NVARCHAR(50) = N'TRIEU_CHUNG'
)
AS
BEGIN
    SET NOCOUNT ON;
    SET @Loai=ISNULL(NULLIF(LTRIM(RTRIM(@Loai)),N''),N'TRIEU_CHUNG');

    IF @IDNhanVien IS NOT NULL AND @IDNhanVien>0
       AND EXISTS
       (
           SELECT 1 FROM dbo.DM_VietTat
           WHERE IDCSKCB=@IDCSKCB AND IDNhanVien=@IDNhanVien AND Loai=@Loai AND Active=1
       )
    BEGIN
        SELECT ID,IDCSKCB,IDNhanVien,Loai,
               MaVietTat AS ma,CumTuDayDu AS cum_tu,ThuTu AS thu_tu,Active AS active
        FROM dbo.DM_VietTat
        WHERE IDCSKCB=@IDCSKCB AND IDNhanVien=@IDNhanVien AND Loai=@Loai AND Active=1
        ORDER BY ThuTu,ID;
    END
    ELSE
    BEGIN
        SELECT ID,IDCSKCB,IDNhanVien,Loai,
               MaVietTat AS ma,CumTuDayDu AS cum_tu,ThuTu AS thu_tu,Active AS active
        FROM dbo.DM_VietTat
        WHERE IDCSKCB=@IDCSKCB AND IDNhanVien IS NULL AND Loai=@Loai AND Active=1
        ORDER BY ThuTu,ID;
    END;
END;
GO

/* ==================== STO_DM_VietTat_LuuDanhSach ==================== */
CREATE OR ALTER PROCEDURE dbo.STO_DM_VietTat_LuuDanhSach
(
    @IDCSKCB BIGINT,
    @IDNhanVien BIGINT = NULL,
    @Loai NVARCHAR(50) = N'TRIEU_CHUNG',
    @JsonDanhSach NVARCHAR(MAX) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY
        BEGIN TRANSACTION;
        SET @Loai=ISNULL(NULLIF(LTRIM(RTRIM(@Loai)),N''),N'TRIEU_CHUNG');

        IF @IDNhanVien IS NOT NULL AND @IDNhanVien>0
            DELETE dbo.DM_VietTat
            WHERE IDCSKCB=@IDCSKCB AND Loai=@Loai AND IDNhanVien=@IDNhanVien;
        ELSE
            DELETE dbo.DM_VietTat
            WHERE IDCSKCB=@IDCSKCB AND Loai=@Loai AND IDNhanVien IS NULL;

        IF @JsonDanhSach IS NOT NULL AND ISJSON(@JsonDanhSach)=1
        BEGIN
            INSERT dbo.DM_VietTat
                (IDCSKCB,IDNhanVien,Loai,MaVietTat,CumTuDayDu,ThuTu,Active,NgayTao)
            SELECT
                @IDCSKCB,@IDNhanVien,@Loai,
                LTRIM(RTRIM(JSON_VALUE(J.value,'$.ma'))),
                LTRIM(RTRIM(JSON_VALUE(J.value,'$.cum_tu'))),
                ISNULL(TRY_CAST(JSON_VALUE(J.value,'$.thu_tu') AS INT),
                       ROW_NUMBER() OVER(ORDER BY (SELECT NULL))),
                1,SYSDATETIME()
            FROM OPENJSON(@JsonDanhSach) J
            WHERE NULLIF(LTRIM(RTRIM(JSON_VALUE(J.value,'$.ma'))),N'') IS NOT NULL
               OR NULLIF(LTRIM(RTRIM(JSON_VALUE(J.value,'$.cum_tu'))),N'') IS NOT NULL;
        END;

        COMMIT TRANSACTION;
        SELECT 200 AS Status,N'Đã lưu danh sách cụm từ viết tắt thành công.' AS Message;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT>0 ROLLBACK TRANSACTION;
        SELECT 500 AS Status,ERROR_MESSAGE() AS Message;
    END CATCH;
END;
GO


PRINT N'===== KIEM TRA SAU REBUILD =====';
