/*
=====================================================================
05_kiem_tra_main.sql
Kiem tra schema CUOI CUNG cua nhanh main.
- Khong sua du lieu.
- Neu thieu/sai bat ky thanh phan bat buoc nao -> RAISERROR de sqlcmd -b dung ngay.
=====================================================================
*/
USE [QLPM];
GO
SET NOCOUNT ON;
GO

DECLARE @Loi NVARCHAR(MAX)=N'';

/* ---------- Core / tiep nhan ---------- */
IF OBJECT_ID(N'dbo.DM_GioiTinh',N'U') IS NULL
    SET @Loi = @Loi + N'- Thieu DM_GioiTinh.'+CHAR(13)+CHAR(10);
ELSE
BEGIN
    IF NOT EXISTS(SELECT 1 FROM dbo.DM_GioiTinh WHERE ID=1 AND Active=1)
        SET @Loi = @Loi + N'- DM_GioiTinh thieu dong active ID=1 (1).'+CHAR(13)+CHAR(10);
    IF NOT EXISTS(SELECT 1 FROM dbo.DM_GioiTinh WHERE ID=2 AND Active=1)
        SET @Loi = @Loi + N'- DM_GioiTinh thieu dong active ID=2 (2).'+CHAR(13)+CHAR(10);
    IF NOT EXISTS(SELECT 1 FROM dbo.DM_GioiTinh WHERE ID=3 AND Active=1)
        SET @Loi = @Loi + N'- DM_GioiTinh thieu dong active ID=3 (3).'+CHAR(13)+CHAR(10);
END;

IF COL_LENGTH (
    N'dbo.QL_BenhNhan',
    N'IDGioiTinh'
) IS NULL
SET
    @Loi = @Loi + N'- QL_BenhNhan thieu IDGioiTinh.' + CHAR(13) + CHAR(10);

IF COL_LENGTH (
    N'dbo.QL_BenhNhan',
    N'GioiTinh'
) IS NOT NULL
SET
    @Loi = @Loi + N'- QL_BenhNhan van con cot GioiTinh legacy.' + CHAR(13) + CHAR(10);

IF COL_LENGTH (
    N'dbo.QL_BenhNhan',
    N'GiamHo_MoiQuanHe'
) IS NULL
OR COL_LENGTH (
    N'dbo.QL_BenhNhan',
    N'GiamHo_HoTen'
) IS NULL
OR COL_LENGTH (
    N'dbo.QL_BenhNhan',
    N'GiamHo_DienThoai'
) IS NULL
OR COL_LENGTH (
    N'dbo.QL_BenhNhan',
    N'GiamHo_SoCCCD'
) IS NULL
SET
    @Loi = @Loi + N'- QL_BenhNhan thieu mot hoac nhieu cot GiamHo_*.' + CHAR(13) + CHAR(10);

IF COL_LENGTH (
    N'dbo.QL_BenhNhan',
    N'QuocTich'
) IS NULL
OR COL_LENGTH (
    N'dbo.QL_BenhNhan',
    N'NgheNghiep'
) IS NULL
SET
    @Loi = @Loi + N'- QL_BenhNhan thieu QuocTich/NgheNghiep.' + CHAR(13) + CHAR(10);

IF NOT EXISTS (
    SELECT 1
    FROM sys.foreign_keys
    WHERE
        parent_object_id = OBJECT_ID (N'dbo.QL_BenhNhan')
        AND name = N'FK_QL_BenhNhan_GioiTinh'
)
SET
    @Loi = @Loi + N'- Thieu FK_QL_BenhNhan_GioiTinh.' + CHAR(13) + CHAR(10);

/* ---------- Phac do ---------- */
IF OBJECT_ID (
    N'dbo.DM_PhacDo_ChanDoan',
    N'U'
) IS NULL
SET
    @Loi = @Loi + N'- Thieu DM_PhacDo_ChanDoan.' + CHAR(13) + CHAR(10);

IF OBJECT_ID (
    N'dbo.STO_DM_PhacDo_Luu',
    N'P'
) IS NULL
SET
    @Loi = @Loi + N'- Thieu STO_DM_PhacDo_Luu.' + CHAR(13) + CHAR(10);

ELSE IF NOT EXISTS (
    SELECT 1
    FROM sys.parameters
    WHERE
        object_id = OBJECT_ID (N'dbo.STO_DM_PhacDo_Luu')
        AND name = N'@ChanDoanJson'
)
SET
    @Loi = @Loi + N'- STO_DM_PhacDo_Luu chua ho tro nhieu ICD (@ChanDoanJson).' + CHAR(13) + CHAR(10);

IF OBJECT_ID (
    N'dbo.STO_DM_PhacDo_DanhSach',
    N'P'
) IS NULL
SET
    @Loi = @Loi + N'- Thieu STO_DM_PhacDo_DanhSach.' + CHAR(13) + CHAR(10);

ELSE IF NOT EXISTS (
    SELECT 1
    FROM sys.parameters
    WHERE
        object_id = OBJECT_ID (N'dbo.STO_DM_PhacDo_DanhSach')
        AND name = N'@KichThuocTrang'
)
SET
    @Loi = @Loi + N'- STO_DM_PhacDo_DanhSach chua server paging.' + CHAR(13) + CHAR(10);

/* ---------- CLS final schema ---------- */
IF OBJECT_ID (
    N'dbo.QL_CLS_DM_TriSoXN',
    N'U'
) IS NULL
SET
    @Loi = @Loi + N'- Thieu QL_CLS_DM_TriSoXN.' + CHAR(13) + CHAR(10);

IF OBJECT_ID (N'dbo.QL_CLS_FormKQXN', N'U') IS NULL
SET
    @Loi = @Loi + N'- Thieu QL_CLS_FormKQXN.' + CHAR(13) + CHAR(10);

IF OBJECT_ID (
    N'dbo.QL_CLS_FormKQXN_CT',
    N'U'
) IS NULL
SET
    @Loi = @Loi + N'- Thieu QL_CLS_FormKQXN_CT.' + CHAR(13) + CHAR(10);

IF OBJECT_ID (
    N'dbo.QL_CLS_PhieuKetQua',
    N'U'
) IS NULL
SET
    @Loi = @Loi + N'- Thieu QL_CLS_PhieuKetQua.' + CHAR(13) + CHAR(10);

IF OBJECT_ID (
    N'dbo.QL_CLS_KetQuaXN_CT',
    N'U'
) IS NULL
SET
    @Loi = @Loi + N'- Thieu QL_CLS_KetQuaXN_CT.' + CHAR(13) + CHAR(10);

IF OBJECT_ID (
    N'dbo.QL_CLS_PhieuKetQua_File',
    N'U'
) IS NULL
SET
    @Loi = @Loi + N'- Thieu QL_CLS_PhieuKetQua_File.' + CHAR(13) + CHAR(10);

IF OBJECT_ID (
    N'dbo.QL_CLS_KetQua_LichSu',
    N'U'
) IS NULL
SET
    @Loi = @Loi + N'- Thieu QL_CLS_KetQua_LichSu.' + CHAR(13) + CHAR(10);

IF COL_LENGTH (
    N'dbo.DM_DichVu',
    N'LoaiKetQua'
) IS NULL
OR COL_LENGTH (N'dbo.DM_DichVu', N'IDFormKQ') IS NULL
SET
    @Loi = @Loi + N'- DM_DichVu thieu LoaiKetQua/IDFormKQ.' + CHAR(13) + CHAR(10);

IF EXISTS(SELECT 1 FROM dbo.DM_DichVu WHERE LoaiKetQua NOT IN(0,1,2))
    SET @Loi=@Loi+N'- DM_DichVu.LoaiKetQua chi duoc 0=chua cau hinh, 1=XN, 2=CLS mo ta.'+CHAR(13)+CHAR(10);

IF OBJECT_ID(N'dbo.QL_CLS_PhieuKetQua',N'U') IS NOT NULL
AND EXISTS(SELECT 1 FROM dbo.QL_CLS_PhieuKetQua WHERE LoaiKetQua NOT IN(1,2))
    SET @Loi=@Loi+N'- QL_CLS_PhieuKetQua con loai ket qua legacy/tu do.'+CHAR(13)+CHAR(10);

/* Master tri so chi giu danh tinh + metadata; config nam o FormKQXN_CT. */
IF COL_LENGTH(N'dbo.QL_CLS_DM_TriSoXN',N'TenVietTat') IS NULL
OR COL_LENGTH(N'dbo.QL_CLS_DM_TriSoXN',N'LOINCCode') IS NULL
OR COL_LENGTH(N'dbo.QL_CLS_DM_TriSoXN',N'LoaiDuLieu') IS NULL
    SET @Loi=@Loi+N'- QL_CLS_DM_TriSoXN thieu metadata canonical.'+CHAR(13)+CHAR(10);

IF COL_LENGTH (
    N'dbo.QL_CLS_KetQuaXN_CT',
    N'Trai'
) IS NULL
OR COL_LENGTH (
    N'dbo.QL_CLS_KetQuaXN_CT',
    N'Phai'
) IS NULL
OR COL_LENGTH (
    N'dbo.QL_CLS_KetQuaXN_CT',
    N'CongThuc'
) IS NULL
SET
    @Loi = @Loi + N'- QL_CLS_KetQuaXN_CT thieu Trai/Phai/CongThuc snapshot.' + CHAR(13) + CHAR(10);

IF COL_LENGTH (
    N'dbo.QL_CLS_PhieuKetQua_File',
    N'TenFileLuu'
) IS NOT NULL
SET
    @Loi = @Loi + N'- QL_CLS_PhieuKetQua_File van con TenFileLuu legacy.' + CHAR(13) + CHAR(10);

IF NOT EXISTS (
    SELECT 1
    FROM sys.indexes
    WHERE
        object_id = OBJECT_ID (N'dbo.QL_CLS_KetQuaXN_CT')
        AND name = N'IX_QL_CLS_KQXN_Phieu'
)
SET
    @Loi = @Loi + N'- Thieu IX_QL_CLS_KQXN_Phieu.' + CHAR(13) + CHAR(10);

ELSE IF EXISTS (
    SELECT 1
    FROM sys.indexes i
        INNER JOIN sys.index_columns ic ON ic.object_id = i.object_id
        AND ic.index_id = i.index_id
        INNER JOIN sys.columns c ON c.object_id = ic.object_id
        AND c.column_id = ic.column_id
    WHERE
        i.object_id = OBJECT_ID (N'dbo.QL_CLS_KetQuaXN_CT')
        AND i.name = N'IX_QL_CLS_KQXN_Phieu'
        AND c.name IN (
            N'Duyet',
            N'HuyDuyet',
            N'Active'
        )
)
SET
    @Loi = @Loi + N'- IX_QL_CLS_KQXN_Phieu van phu thuoc cot legacy Duyet/HuyDuyet/Active.' + CHAR(13) + CHAR(10);

/* ---------- Main phai sach legacy / DSS ---------- */
DECLARE @ForbiddenTable TABLE(TableName SYSNAME PRIMARY KEY);
INSERT @ForbiddenTable(TableName) VALUES
(N'QL_CLS_DichVu_FormKQ'),(N'QL_KetQuaCLS'),(N'QL_KetQuaCLS_File'),
(N'QL_Thuoc_Di_Ung'),(N'sysdiagrams');

SELECT @Loi=@Loi+N'- Bang legacy/DSS van con: dbo.'+T.name+N'.'+CHAR(13)+CHAR(10)
FROM sys.tables T
WHERE SCHEMA_NAME(T.schema_id)=N'dbo'
  AND (T.name LIKE N'DSS[_]%' OR EXISTS(SELECT 1 FROM @ForbiddenTable F WHERE F.TableName=T.name));

DECLARE @ForbiddenColumn TABLE(TableName SYSNAME,ColumnName SYSNAME,PRIMARY KEY(TableName,ColumnName));
INSERT @ForbiddenColumn(TableName,ColumnName) VALUES
(N'DM_NhanVien',N'UserId'),
(N'DM_PhacDo',N'NoiDung'),(N'DM_PhacDo',N'IDICD10'),(N'DM_PhacDo',N'BanDau'),(N'DM_PhacDo',N'BenhChinh'),(N'DM_PhacDo',N'BenhKhac'),
(N'QL_BenhNhan',N'Tuoi'),
(N'QL_ChiDinh_CT',N'NgayGioThucHien'),(N'QL_ChiDinh_CT',N'NgayGioKetQua'),(N'QL_ChiDinh_CT',N'IDNhanVienThucHien'),(N'QL_ChiDinh_CT',N'IDBacSiThucHien'),(N'QL_ChiDinh_CT',N'IDPhieuKetQua'),
(N'QL_CLS_FormKQXN',N'STT'),
(N'QL_CLS_PhieuKetQua',N'Duyet'),(N'QL_CLS_PhieuKetQua',N'IDNhanVienDuyet'),(N'QL_CLS_PhieuKetQua',N'NgayGioDuyet'),(N'QL_CLS_PhieuKetQua',N'NgayGioHuyDuyet'),(N'QL_CLS_PhieuKetQua',N'IDNhanVienHuyDuyet'),(N'QL_CLS_PhieuKetQua',N'IDVaoVien'),(N'QL_CLS_PhieuKetQua',N'IDDichVu'),
(N'QL_CLS_KetQuaXN_CT',N'Active'),(N'QL_CLS_KetQuaXN_CT',N'Duyet'),(N'QL_CLS_KetQuaXN_CT',N'IDNhanVienDuyet'),(N'QL_CLS_KetQuaXN_CT',N'NgayGioDuyet'),(N'QL_CLS_KetQuaXN_CT',N'HuyDuyet'),(N'QL_CLS_KetQuaXN_CT',N'IDNhanVienHuy'),(N'QL_CLS_KetQuaXN_CT',N'NgayGioHuyDuyet'),
(N'QL_CLS_DM_TriSoXN',N'DonViTinh'),(N'QL_CLS_DM_TriSoXN',N'DinhLuong'),(N'QL_CLS_DM_TriSoXN',N'TriSoBinhThuong1'),(N'QL_CLS_DM_TriSoXN',N'GHMin1'),(N'QL_CLS_DM_TriSoXN',N'GHMax1'),(N'QL_CLS_DM_TriSoXN',N'MacDinh1'),
(N'QL_CLS_DM_TriSoXN',N'TriSoBinhThuong2'),(N'QL_CLS_DM_TriSoXN',N'GHMin2'),(N'QL_CLS_DM_TriSoXN',N'GHMax2'),(N'QL_CLS_DM_TriSoXN',N'MacDinh2'),(N'QL_CLS_DM_TriSoXN',N'IDGioiTinh'),(N'QL_CLS_DM_TriSoXN',N'TuoiMin'),(N'QL_CLS_DM_TriSoXN',N'TuoiMax'),(N'QL_CLS_DM_TriSoXN',N'LamTron'),(N'QL_CLS_DM_TriSoXN',N'ThuTu'),
(N'QL_CLS_DM_TriSoXN',N'LuongDinhTinh'),(N'QL_CLS_DM_TriSoXN',N'TuyetDoi'),(N'QL_CLS_DM_TriSoXN',N'DonViTinh2'),(N'QL_CLS_DM_TriSoXN',N'TiLeQuyDoi'),(N'QL_CLS_DM_TriSoXN',N'GHTuoi'),(N'QL_CLS_DM_TriSoXN',N'Nguong'),(N'QL_CLS_DM_TriSoXN',N'Tieude'),(N'QL_CLS_DM_TriSoXN',N'CongThuc'),(N'QL_CLS_DM_TriSoXN',N'CongThucMoi');

SELECT @Loi=@Loi+N'- Cot legacy van con: dbo.'+F.TableName+N'.'+F.ColumnName+N'.'+CHAR(13)+CHAR(10)
FROM @ForbiddenColumn F
WHERE COL_LENGTH(N'dbo.'+F.TableName,F.ColumnName) IS NOT NULL;

IF EXISTS
(
    SELECT 1 FROM sys.procedures
    WHERE name LIKE N'STO[_]DSS[_]%'
       OR name LIKE N'STO[_]QL[_]KetQuaCLS%'
       OR name LIKE N'STO[_]QL[_]CLS[_]%[_]V2'
       OR name LIKE N'STO[_]QL[_]CLS[_]KetQua[_]Duyet%'
)
    SET @Loi=@Loi+N'- Van con STO DSS/CLS legacy.'+CHAR(13)+CHAR(10);

/* ---------- Metadata phan quyen bat buoc ---------- */
IF EXISTS
(
    SELECT 1
    FROM dbo.DM_CSKCB CS
    WHERE CS.Active=1
      AND NOT EXISTS
      (
          SELECT 1
          FROM dbo.HT_Chuc_Nang C
          WHERE C.IDCSKCB=CS.ID
            AND C.Ma_Chuc_Nang=N'cls_cau_hinh'
            AND C.Ten_Chuc_Nang=N'Cấu hình kết quả CLS'
            AND C.Duong_Dan=N'/cls_ket_qua'
            AND C.Active=1
      )
)
    SET @Loi=@Loi+N'- Thieu metadata quyen cls_cau_hinh / Cấu hình kết quả CLS.'+CHAR(13)+CHAR(10);

/* ---------- Superuser ownership bypass ---------- */
DECLARE @AdminBypassProc TABLE(ProcName SYSNAME PRIMARY KEY);
INSERT @AdminBypassProc(ProcName) VALUES
(N'STO_QL_Kham_ChonBenhNhan'),
(N'STO_QL_Kham_CapNhatDangKham'),
(N'STO_QL_Kham_HuyDangKham'),
(N'STO_QL_Kham_Luu');

SELECT @Loi=@Loi+N'- STO thieu @LaQuanTri: '+P.ProcName+N'.'+CHAR(13)+CHAR(10)
FROM @AdminBypassProc P
WHERE OBJECT_ID(N'dbo.'+P.ProcName,N'P') IS NULL
   OR NOT EXISTS
      (
          SELECT 1 FROM sys.parameters
          WHERE object_id=OBJECT_ID(N'dbo.'+P.ProcName)
            AND name=N'@LaQuanTri'
      );

IF OBJECT_ID(N'dbo.STO_QL_Kham_Luu',N'P') IS NOT NULL
AND OBJECT_DEFINITION(OBJECT_ID(N'dbo.STO_QL_Kham_Luu')) LIKE N'%Tuoi=CASE WHEN @NgaySinh%'
    SET @Loi=@Loi+N'- STO_QL_Kham_Luu van ghi QL_BenhNhan.Tuoi da bi loai bo.'+CHAR(13)+CHAR(10);

IF OBJECT_ID(N'dbo.STO_QL_Kham_Luu',N'P') IS NULL
OR OBJECT_DEFINITION(OBJECT_ID(N'dbo.STO_QL_Kham_Luu')) NOT LIKE N'%Chẩn đoán bắt buộc phải có đúng 1 bệnh chính.%'
    SET @Loi=@Loi+N'- STO_QL_Kham_Luu chua bat buoc dung 1 benh chinh.'+CHAR(13)+CHAR(10);

IF OBJECT_ID(N'dbo.STO_DM_PhacDo_Luu',N'P') IS NULL
OR OBJECT_DEFINITION(OBJECT_ID(N'dbo.STO_DM_PhacDo_Luu')) NOT LIKE N'%Phác đồ bắt buộc phải có đúng 1 bệnh chính.%'
OR OBJECT_DEFINITION(OBJECT_ID(N'dbo.STO_DM_PhacDo_Luu')) NOT LIKE N'%@IDPhacDoTrung%'
    SET @Loi=@Loi+N'- STO_DM_PhacDo_Luu chua co rule benh chinh/khôi phuc ma phac do xoa mem.'+CHAR(13)+CHAR(10);

/* ---------- Admin support sua luot da kham ---------- */
IF OBJECT_ID(N'dbo.STO_QL_Kham_CapNhatDangKham',N'P') IS NOT NULL
AND
(
    OBJECT_DEFINITION(OBJECT_ID(N'dbo.STO_QL_Kham_CapNhatDangKham')) NOT LIKE N'%@TrangThai=2 AND ISNULL(@LaQuanTri,0)=0%'
 OR OBJECT_DEFINITION(OBJECT_ID(N'dbo.STO_QL_Kham_CapNhatDangKham')) NOT LIKE N'%WHEN @TrangThai=2 AND ISNULL(@LaQuanTri,0)=1 THEN 2%'
)
    SET @Loi=@Loi+N'- STO_QL_Kham_CapNhatDangKham chua cho admin sua luot da kham ma giu TrangThaiKham=2.'+CHAR(13)+CHAR(10);

IF OBJECT_ID(N'dbo.STO_QL_Kham_Luu',N'P') IS NOT NULL
AND
(
    OBJECT_DEFINITION(OBJECT_ID(N'dbo.STO_QL_Kham_Luu')) NOT LIKE N'%@IDBacSiNghiepVu%'
 OR OBJECT_DEFINITION(OBJECT_ID(N'dbo.STO_QL_Kham_Luu')) NOT LIKE N'%WHEN @CoToa=1 OR @KhamXong=1 OR @TrangThaiHienTai=2 THEN 2%'
)
    SET @Loi=@Loi+N'- STO_QL_Kham_Luu chua giu bac si nghiep vu/trang thai Da kham khi admin sua ho.'+CHAR(13)+CHAR(10);

/* ---------- Required STO / trigger ---------- */
IF OBJECT_ID (
    N'dbo.STO_QL_BenhNhan_KiemTraTrung',
    N'P'
) IS NULL
SET
    @Loi = @Loi + N'- Thieu STO_QL_BenhNhan_KiemTraTrung.' + CHAR(13) + CHAR(10);

IF OBJECT_ID (
    N'dbo.STO_QL_TiepNhan_Luu',
    N'P'
) IS NULL
SET
    @Loi = @Loi + N'- Thieu STO_QL_TiepNhan_Luu.' + CHAR(13) + CHAR(10);

IF OBJECT_ID (
    N'dbo.STO_QL_TiepNhan_DanhSach',
    N'P'
) IS NULL
SET
    @Loi = @Loi + N'- Thieu STO_QL_TiepNhan_DanhSach.' + CHAR(13) + CHAR(10);

ELSE IF NOT EXISTS (
    SELECT 1
    FROM sys.parameters
    WHERE
        object_id = OBJECT_ID (
            N'dbo.STO_QL_TiepNhan_DanhSach'
        )
        AND name = N'@KichThuocTrang'
)
SET
    @Loi = @Loi + N'- STO_QL_TiepNhan_DanhSach chua server paging.' + CHAR(13) + CHAR(10);

IF OBJECT_ID (
    N'dbo.STO_QL_Kham_DanhSach',
    N'P'
) IS NULL
SET
    @Loi = @Loi + N'- Thieu STO_QL_Kham_DanhSach.' + CHAR(13) + CHAR(10);

ELSE IF NOT EXISTS (
    SELECT 1
    FROM sys.parameters
    WHERE
        object_id = OBJECT_ID (N'dbo.STO_QL_Kham_DanhSach')
        AND name = N'@KichThuocTrang'
)
SET
    @Loi = @Loi + N'- STO_QL_Kham_DanhSach chua server paging.' + CHAR(13) + CHAR(10);

IF OBJECT_ID (
