SET
    @Loi = @Loi + N'- Thieu STO_QL_Kham_Luu.' + CHAR(13) + CHAR(10);

ELSE BEGIN IF NOT EXISTS (
    SELECT 1
    FROM sys.parameters
    WHERE
        object_id = OBJECT_ID (N'dbo.STO_QL_Kham_Luu')
        AND name = N'@GioiTinh'
)
SET
