SELECT @Loi = @Loi + N'- Thieu bang EF main: dbo.'+T.TableName+N'.'+CHAR(13)+CHAR(10)
FROM (SELECT DISTINCT TableName FROM @EfModelContract) T
WHERE OBJECT_ID(N'dbo.'+T.TableName,N'U') IS NULL;

SELECT @Loi = @Loi + N'- Lech EF main: dbo.'+E.TableName+N' thieu cot '+E.ColumnName+N'.'+CHAR(13)+CHAR(10)
FROM @EfModelContract E
WHERE OBJECT_ID(N'dbo.'+E.TableName,N'U') IS NOT NULL
  AND COL_LENGTH(N'dbo.'+E.TableName,E.ColumnName) IS NULL;

/* Type/nullability contract cua cac cot trong EF model nhanh main. */
