SELECT @Loi = @Loi + N'- Lech type/nullability EF main: dbo.'+E.TableName+N'.'+E.ColumnName+N'.'+CHAR(13)+CHAR(10)
FROM @EfTypeContract E
INNER JOIN sys.tables T ON T.name=E.TableName AND SCHEMA_NAME(T.schema_id)=N'dbo'
INNER JOIN sys.columns C ON C.object_id=T.object_id AND C.name=E.ColumnName
INNER JOIN sys.types TY ON TY.user_type_id=C.user_type_id
WHERE TY.name<>E.TypeName
   OR C.max_length<>E.MaxLength
   OR C.precision<>E.[Precision]
   OR C.scale<>E.Scale
   OR C.is_nullable<>E.IsNullable;

