SELECT @Loi = @Loi + N'- Thieu STO ma code main dang goi: dbo.'+X.ProcName+N'.'+CHAR(13)+CHAR(10)
FROM
(
    SELECT DISTINCT ProcName FROM @RuntimeContract
) X
WHERE OBJECT_ID(N'dbo.'+X.ProcName,N'P') IS NULL;

SELECT @Loi = @Loi + N'- Sai contract STO dbo.'+R.ProcName+N': thieu tham so '+R.ParamName+N'.'+CHAR(13)+CHAR(10)
FROM @RuntimeContract R
WHERE OBJECT_ID(N'dbo.'+R.ProcName,N'P') IS NOT NULL
  AND NOT EXISTS
  (
      SELECT 1
      FROM sys.parameters P
      WHERE P.object_id=OBJECT_ID(N'dbo.'+R.ProcName)
        AND P.name=R.ParamName
  );

/* Stored modules ghi vao bang co filtered index/computed index bat buoc
   duoc tao voi ANSI_NULLS ON va QUOTED_IDENTIFIER ON. */
;WITH ManagedProcedure AS
(
    SELECT DISTINCT ProcName
    FROM @RuntimeContract
    UNION
    SELECT N'STO_QL_ThuTien_CapNhatTong'
    UNION
    SELECT N'STO_QL_CLS_KetQua_XoaFile'
)
SELECT @Loi = @Loi
    + N'- STO dbo.'+P.ProcName
    + N' duoc tao voi ANSI_NULLS/QUOTED_IDENTIFIER sai; hay chay lai updater main.'
    + CHAR(13)+CHAR(10)
FROM ManagedProcedure P
INNER JOIN sys.sql_modules M
    ON M.object_id=OBJECT_ID(N'dbo.'+P.ProcName,N'P')
WHERE M.uses_ansi_nulls=0
   OR M.uses_quoted_identifier=0;

IF EXISTS
(
    SELECT 1
    FROM sys.sql_modules M
    WHERE M.object_id=OBJECT_ID(N'dbo.TR_QL_ChiDinh_CT_BaoVeKetQuaCLS',N'TR')
      AND (M.uses_ansi_nulls=0 OR M.uses_quoted_identifier=0)
)
    SET @Loi = @Loi + N'- Trigger dbo.TR_QL_ChiDinh_CT_BaoVeKetQuaCLS duoc tao voi ANSI_NULLS/QUOTED_IDENTIFIER sai; hay chay lai updater main.'+CHAR(13)+CHAR(10);

IF OBJECT_ID(N'dbo.STO_QL_TiepNhan_Luu',N'P') IS NOT NULL
AND NOT EXISTS
(
    SELECT 1 FROM sys.parameters
    WHERE object_id=OBJECT_ID(N'dbo.STO_QL_TiepNhan_Luu')
      AND name=N'@BoQuaCanhBaoTrung'
)
    SET @Loi = @Loi + N'- STO_QL_TiepNhan_Luu thieu @BoQuaCanhBaoTrung cho patient matching.'+CHAR(13)+CHAR(10);

IF OBJECT_ID(N'dbo.STO_QL_TiepNhan_Luu',N'P') IS NOT NULL
AND OBJECT_DEFINITION(OBJECT_ID(N'dbo.STO_QL_TiepNhan_Luu')) NOT LIKE N'%lượt khám chưa hoàn tất trong ngày%'
    SET @Loi = @Loi + N'- STO_QL_TiepNhan_Luu chua chan tao luot thu hai khi BN con luot chua hoan tat trong ngay.'+CHAR(13)+CHAR(10);

IF OBJECT_ID(N'dbo.STO_QL_TiepNhan_ChuyenKham',N'P') IS NOT NULL
AND OBJECT_DEFINITION(OBJECT_ID(N'dbo.STO_QL_TiepNhan_ChuyenKham')) NOT LIKE N'%lượt khám trước đó trong ngày chưa hoàn tất%'
    SET @Loi = @Loi + N'- STO_QL_TiepNhan_ChuyenKham chua chan chuyen kham tren luot tiep nhan trung trong ngay.'+CHAR(13)+CHAR(10);

IF OBJECT_ID(N'dbo.STO_QL_Kham_HuyDangKham',N'P') IS NOT NULL
AND NOT EXISTS
(
    SELECT 1 FROM sys.parameters
    WHERE object_id=OBJECT_ID(N'dbo.STO_QL_Kham_HuyDangKham')
      AND name=N'@IDBacSi'
)
    SET @Loi = @Loi + N'- STO_QL_Kham_HuyDangKham thieu @IDBacSi de bao ve phien kham.'+CHAR(13)+CHAR(10);

/* CLS main chi co mot contract canonical, khong co suffix V2 va khong co STO duyet. */
IF EXISTS
(
    SELECT 1
    FROM sys.procedures
    WHERE schema_id=SCHEMA_ID(N'dbo')
      AND name LIKE N'STO[_]QL[_]CLS%[_]V2'
)
    SET @Loi = @Loi + N'- Con STO CLS suffix V2; hay chay lai 20_REBUILD_ALL_STO_MAIN.sql.'+CHAR(13)+CHAR(10);

IF EXISTS
(
    SELECT 1
    FROM sys.procedures
    WHERE schema_id=SCHEMA_ID(N'dbo')
      AND name LIKE N'STO[_]QL[_]CLS[_]KetQua[_]Duyet%'
)
    SET @Loi = @Loi + N'- Con STO nghiep vu duyet/huy duyet CLS; main khong su dung luong nay.'+CHAR(13)+CHAR(10);

/* Upload canonical khong co tham so TenFileLuu legacy. */
IF OBJECT_ID(N'dbo.STO_QL_CLS_KetQua_ThemFile',N'P') IS NOT NULL
AND EXISTS
(
    SELECT 1 FROM sys.parameters
    WHERE object_id=OBJECT_ID(N'dbo.STO_QL_CLS_KetQua_ThemFile')
      AND name=N'@TenFileLuu'
)
    SET @Loi = @Loi + N'- STO_QL_CLS_KetQua_ThemFile van co @TenFileLuu legacy.'+CHAR(13)+CHAR(10);


/* ---------- Quan ly CSKCB common ---------- */
IF OBJECT_ID(N'dbo.STO_HT_CSKCB_Danh_Sach',N'P') IS NULL
    SET @Loi=@Loi+N'- Thieu STO_HT_CSKCB_Danh_Sach.'+CHAR(13)+CHAR(10);
IF OBJECT_ID(N'dbo.STO_HT_CSKCB_Luu',N'P') IS NULL
    SET @Loi=@Loi+N'- Thieu STO_HT_CSKCB_Luu.'+CHAR(13)+CHAR(10);
IF NOT EXISTS
(
    SELECT 1 FROM sys.parameters
    WHERE object_id=OBJECT_ID(N'dbo.STO_HT_CSKCB_Danh_Sach')
      AND name=N'@Trang'
)
 OR NOT EXISTS
(
    SELECT 1 FROM sys.parameters
    WHERE object_id=OBJECT_ID(N'dbo.STO_HT_CSKCB_Danh_Sach')
      AND name=N'@KichThuocTrang'
)
    SET @Loi=@Loi+N'- STO_HT_CSKCB_Danh_Sach chua server paging common.'+CHAR(13)+CHAR(10);

IF NOT EXISTS
(
    SELECT 1 FROM sys.parameters
    WHERE object_id=OBJECT_ID(N'dbo.STO_HT_CSKCB_Danh_Sach')
      AND name=N'@Active'
)
    SET @Loi=@Loi+N'- STO_HT_CSKCB_Danh_Sach chua ho tro loc trang thai @Active.'+CHAR(13)+CHAR(10);

IF NOT EXISTS
(
    SELECT 1 FROM sys.parameters
    WHERE object_id=OBJECT_ID(N'dbo.STO_HT_CSKCB_Danh_Sach')
      AND name=N'@MaCSKCB'
)
 OR NOT EXISTS
(
    SELECT 1 FROM sys.parameters
    WHERE object_id=OBJECT_ID(N'dbo.STO_HT_CSKCB_Danh_Sach')
      AND name=N'@TenCSKCB'
)
 OR NOT EXISTS
(
    SELECT 1 FROM sys.parameters
    WHERE object_id=OBJECT_ID(N'dbo.STO_HT_CSKCB_Danh_Sach')
      AND name=N'@MaTinh'
)
 OR NOT EXISTS
(
    SELECT 1 FROM sys.parameters
    WHERE object_id=OBJECT_ID(N'dbo.STO_HT_CSKCB_Danh_Sach')
      AND name=N'@MaPhuongXa'
)
    SET @Loi=@Loi+N'- STO_HT_CSKCB_Danh_Sach chua co bo loc MaCSKCB/TenCSKCB/MaTinh/MaPhuongXa.'+CHAR(13)+CHAR(10);

IF COL_LENGTH(N'dbo.DM_CSKCB',N'SoNhaTenDuong') IS NULL
 OR COL_LENGTH(N'dbo.DM_CSKCB',N'MaTinh') IS NULL
 OR COL_LENGTH(N'dbo.DM_CSKCB',N'MaPhuongXa') IS NULL
 OR COL_LENGTH(N'dbo.DM_NhanVien',N'SoNhaTenDuong') IS NULL
 OR COL_LENGTH(N'dbo.DM_NhanVien',N'DiaChi') IS NULL
 OR COL_LENGTH(N'dbo.DM_NhanVien',N'MaTinh') IS NULL
 OR COL_LENGTH(N'dbo.DM_NhanVien',N'MaPhuongXa') IS NULL
    SET @Loi=@Loi+N'- Thieu contract dia chi tach rieng tren DM_CSKCB hoac DM_NhanVien.'+CHAR(13)+CHAR(10);

IF OBJECT_ID(N'dbo.STO_HT_Nhan_Vien_Luu',N'P') IS NOT NULL
AND
(
    NOT EXISTS(SELECT 1 FROM sys.parameters WHERE object_id=OBJECT_ID(N'dbo.STO_HT_Nhan_Vien_Luu') AND name=N'@SoNhaTenDuong')
 OR NOT EXISTS(SELECT 1 FROM sys.parameters WHERE object_id=OBJECT_ID(N'dbo.STO_HT_Nhan_Vien_Luu') AND name=N'@MaTinh')
 OR NOT EXISTS(SELECT 1 FROM sys.parameters WHERE object_id=OBJECT_ID(N'dbo.STO_HT_Nhan_Vien_Luu') AND name=N'@MaPhuongXa')
)
    SET @Loi=@Loi+N'- STO_HT_Nhan_Vien_Luu chua nhan SoNhaTenDuong/MaTinh/MaPhuongXa.'+CHAR(13)+CHAR(10);

IF OBJECT_ID(N'dbo.STO_HT_CSKCB_Luu',N'P') IS NOT NULL
AND NOT EXISTS
(
    SELECT 1 FROM sys.parameters
    WHERE object_id=OBJECT_ID(N'dbo.STO_HT_CSKCB_Luu')
      AND name=N'@SoNhaTenDuong'
)
    SET @Loi=@Loi+N'- STO_HT_CSKCB_Luu chua nhan SoNhaTenDuong.'+CHAR(13)+CHAR(10);

/* ---------- Day du field quan tri he thong ---------- */
IF OBJECT_ID(N'dbo.STO_HT_CSKCB_Luu',N'P') IS NOT NULL
AND
(
    NOT EXISTS(SELECT 1 FROM sys.parameters WHERE object_id=OBJECT_ID(N'dbo.STO_HT_CSKCB_Luu') AND name=N'@MaST')
 OR NOT EXISTS(SELECT 1 FROM sys.parameters WHERE object_id=OBJECT_ID(N'dbo.STO_HT_CSKCB_Luu') AND name=N'@SoTK')
 OR NOT EXISTS(SELECT 1 FROM sys.parameters WHERE object_id=OBJECT_ID(N'dbo.STO_HT_CSKCB_Luu') AND name=N'@IDNganHang')
 OR NOT EXISTS(SELECT 1 FROM sys.parameters WHERE object_id=OBJECT_ID(N'dbo.STO_HT_CSKCB_Luu') AND name=N'@UrlLogo')
)
    SET @Loi=@Loi+N'- STO_HT_CSKCB_Luu chua du MaST/SoTK/IDNganHang/UrlLogo.'+CHAR(13)+CHAR(10);

IF OBJECT_ID(N'dbo.STO_HT_CSKCB_Danh_Sach',N'P') IS NOT NULL
AND
(
    OBJECT_DEFINITION(OBJECT_ID(N'dbo.STO_HT_CSKCB_Danh_Sach')) NOT LIKE N'%C.MaST%'
 OR OBJECT_DEFINITION(OBJECT_ID(N'dbo.STO_HT_CSKCB_Danh_Sach')) NOT LIKE N'%C.SoTK%'
 OR OBJECT_DEFINITION(OBJECT_ID(N'dbo.STO_HT_CSKCB_Danh_Sach')) NOT LIKE N'%C.IDNganHang%'
 OR OBJECT_DEFINITION(OBJECT_ID(N'dbo.STO_HT_CSKCB_Danh_Sach')) NOT LIKE N'%C.UrlLogo%'
)
    SET @Loi=@Loi+N'- STO_HT_CSKCB_Danh_Sach chua tra du field DM_CSKCB.'+CHAR(13)+CHAR(10);

/* ---------- Xoa quan tri he thong / reset password ---------- */
IF OBJECT_ID(N'dbo.STO_HT_CSKCB_Xoa',N'P') IS NULL
    SET @Loi=@Loi+N'- Thieu STO_HT_CSKCB_Xoa.'+CHAR(13)+CHAR(10);
IF OBJECT_ID(N'dbo.STO_HT_Nhan_Vien_Xoa',N'P') IS NULL
    SET @Loi=@Loi+N'- Thieu STO_HT_Nhan_Vien_Xoa.'+CHAR(13)+CHAR(10);
IF OBJECT_ID(N'dbo.STO_HT_Tai_Khoan_Lay_Theo_ID',N'P') IS NULL
    SET @Loi=@Loi+N'- Thieu STO_HT_Tai_Khoan_Lay_Theo_ID.'+CHAR(13)+CHAR(10);
IF OBJECT_ID(N'dbo.STO_HT_Tai_Khoan_Xoa',N'P') IS NULL
    SET @Loi=@Loi+N'- Thieu STO_HT_Tai_Khoan_Xoa.'+CHAR(13)+CHAR(10);
IF OBJECT_ID(N'dbo.STO_HT_Vai_Tro_Xoa',N'P') IS NULL
    SET @Loi=@Loi+N'- Thieu STO_HT_Vai_Tro_Xoa.'+CHAR(13)+CHAR(10);

IF OBJECT_ID(N'dbo.STO_HT_CSKCB_Xoa',N'P') IS NOT NULL
AND OBJECT_DEFINITION(OBJECT_ID(N'dbo.STO_HT_CSKCB_Xoa')) NOT LIKE N'%#TenantTables%'
    SET @Loi=@Loi+N'- STO_HT_CSKCB_Xoa chua phai hard-delete tenant.'+CHAR(13)+CHAR(10);

IF OBJECT_ID(N'dbo.STO_HT_Nhan_Vien_Xoa',N'P') IS NOT NULL
AND OBJECT_DEFINITION(OBJECT_ID(N'dbo.STO_HT_Nhan_Vien_Xoa')) NOT LIKE N'%#RefNhanVien%'
    SET @Loi=@Loi+N'- STO_HT_Nhan_Vien_Xoa chua go tham chieu va xoa hoan toan nhan vien.'+CHAR(13)+CHAR(10);

IF OBJECT_ID(N'dbo.STO_HT_Vai_Tro_Xoa',N'P') IS NOT NULL
AND OBJECT_DEFINITION(OBJECT_ID(N'dbo.STO_HT_Vai_Tro_Xoa')) LIKE N'%Hãy bỏ gán vai trò trước khi xóa%'
    SET @Loi=@Loi+N'- STO_HT_Vai_Tro_Xoa van chan mapping tai khoan; chua hard-delete.'+CHAR(13)+CHAR(10);

IF OBJECT_ID(N'dbo.STO_HT_Nhan_Vien_Import_Excel',N'P') IS NULL
    SET @Loi=@Loi+N'- Thieu STO_HT_Nhan_Vien_Import_Excel.'+CHAR(13)+CHAR(10);
ELSE IF OBJECT_DEFINITION(OBJECT_ID(N'dbo.STO_HT_Nhan_Vien_Import_Excel')) NOT LIKE N'%MaPhuongXa%'
    SET @Loi=@Loi+N'- STO_HT_Nhan_Vien_Import_Excel chua theo contract dia chi/import.'+CHAR(13)+CHAR(10);

/* ---------- He thong paging common ---------- */
IF NOT EXISTS
(
    SELECT 1 FROM sys.parameters
    WHERE object_id=OBJECT_ID(N'dbo.STO_HT_Nhan_Vien_Danh_Sach')
      AND name=N'@KichThuocTrang'
)
    SET @Loi=@Loi+N'- STO_HT_Nhan_Vien_Danh_Sach chua server paging common.'+CHAR(13)+CHAR(10);

IF NOT EXISTS
(
    SELECT 1 FROM sys.parameters
    WHERE object_id=OBJECT_ID(N'dbo.STO_HT_Tai_Khoan_Danh_Sach')
      AND name=N'@KichThuocTrang'
)
    SET @Loi=@Loi+N'- STO_HT_Tai_Khoan_Danh_Sach chua server paging common.'+CHAR(13)+CHAR(10);

IF NOT EXISTS
(
    SELECT 1 FROM sys.parameters
    WHERE object_id=OBJECT_ID(N'dbo.STO_HT_Vai_Tro_Danh_Sach')
      AND name=N'@KichThuocTrang'
)
    SET @Loi=@Loi+N'- STO_HT_Vai_Tro_Danh_Sach chua server paging common.'+CHAR(13)+CHAR(10);

/* ---------- Nhat ky he thong da duoc loai bo khoi main ---------- */
IF OBJECT_ID(N'dbo.STO_HT_Nhat_Ky_Danh_Sach',N'P') IS NOT NULL
    SET @Loi=@Loi+N'- STO_HT_Nhat_Ky_Danh_Sach legacy van con ton tai.'+CHAR(13)+CHAR(10);
IF OBJECT_ID(N'dbo.STO_HT_Nhat_Ky_Ghi',N'P') IS NOT NULL
    SET @Loi=@Loi+N'- STO_HT_Nhat_Ky_Ghi legacy van con ton tai.'+CHAR(13)+CHAR(10);
IF OBJECT_ID(N'dbo.HT_Nhat_Ky_He_Thong',N'U') IS NOT NULL
    SET @Loi=@Loi+N'- HT_Nhat_Ky_He_Thong legacy van con ton tai.'+CHAR(13)+CHAR(10);
IF EXISTS(SELECT 1 FROM dbo.HT_Chuc_Nang WHERE Ma_Chuc_Nang=N'he_thong_nhat_ky')
    SET @Loi=@Loi+N'- Metadata he_thong_nhat_ky legacy van con ton tai.'+CHAR(13)+CHAR(10);

/* ---------- CLS danh muc/import common ---------- */
IF OBJECT_ID(N'dbo.STO_QL_CLS_DM_TriSo_DanhSach',N'P') IS NULL
    SET @Loi=@Loi+N'- Thieu STO_QL_CLS_DM_TriSo_DanhSach.'+CHAR(13)+CHAR(10);
IF OBJECT_ID(N'dbo.STO_QL_CLS_DM_TriSo_Import',N'P') IS NULL
    SET @Loi=@Loi+N'- Thieu STO_QL_CLS_DM_TriSo_Import.'+CHAR(13)+CHAR(10);

/* ---------- Bootstrap lookup phai bi gioi han ---------- */
IF NOT EXISTS
(
    SELECT 1 FROM sys.parameters
    WHERE object_id=OBJECT_ID(N'dbo.STO_HT_Khoi_Tao_Thong_Tin')
      AND name=N'@Top'
)
 OR NOT EXISTS
(
    SELECT 1 FROM sys.parameters
    WHERE object_id=OBJECT_ID(N'dbo.STO_HT_Khoi_Tao_Thong_Tin')
      AND name=N'@TuKhoa'
)
    SET @Loi=@Loi+N'- STO_HT_Khoi_Tao_Thong_Tin chua co gioi han lookup.'+CHAR(13)+CHAR(10);

/* ---------- HT_Tai_Khoan / auth common ---------- */
IF OBJECT_ID(N'dbo.HT_Tai_Khoan',N'U') IS NULL
    SET @Loi=@Loi+N'- Thieu HT_Tai_Khoan.'+CHAR(13)+CHAR(10);
IF OBJECT_ID(N'dbo.HT_Quyen_Vai_Tro',N'U') IS NULL
    SET @Loi=@Loi+N'- Thieu HT_Quyen_Vai_Tro.'+CHAR(13)+CHAR(10);
IF OBJECT_ID(N'dbo.STO_HT_Dang_Nhap_Lay_Tai_Khoan',N'P') IS NULL
    SET @Loi=@Loi+N'- Thieu STO_HT_Dang_Nhap_Lay_Tai_Khoan.'+CHAR(13)+CHAR(10);
IF OBJECT_ID(N'dbo.STO_HT_Lay_Quyen_Tai_Khoan',N'P') IS NULL
    SET @Loi=@Loi+N'- Thieu STO_HT_Lay_Quyen_Tai_Khoan.'+CHAR(13)+CHAR(10);
IF OBJECT_ID(N'dbo.STO_HT_Quyen_Vai_Tro_Luu',N'P') IS NULL
    SET @Loi=@Loi+N'- Thieu STO_HT_Quyen_Vai_Tro_Luu.'+CHAR(13)+CHAR(10);

/* ---------- Global admin v73 ---------- */
IF COL_LENGTH(N'dbo.HT_Tai_Khoan',N'LaQuanTriHeThong') IS NULL
    SET @Loi=@Loi+N'- HT_Tai_Khoan thieu LaQuanTriHeThong.'+CHAR(13)+CHAR(10);
IF EXISTS
(
    SELECT 1 FROM sys.columns
    WHERE object_id=OBJECT_ID(N'dbo.HT_Tai_Khoan')
      AND name IN (N'IDCSKCB',N'IDNhanVien')
      AND is_nullable=0
)
    SET @Loi=@Loi+N'- HT_Tai_Khoan.IDCSKCB/IDNhanVien chua cho phep NULL cho global admin.'+CHAR(13)+CHAR(10);
IF OBJECT_ID(N'dbo.CK_HT_Tai_Khoan_PhamVi',N'C') IS NULL
    SET @Loi=@Loi+N'- Thieu CHECK pham vi tai khoan global/tenant.'+CHAR(13)+CHAR(10);
IF EXISTS(SELECT 1 FROM dbo.DM_Vai_Tro WHERE Ma_Vai_Tro=N'quan_tri_he_thong')
    SET @Loi=@Loi+N'- Con role quan_tri_he_thong theo tenant; global admin phai tach khoi DM_Vai_Tro.'+CHAR(13)+CHAR(10);
IF EXISTS
(
    SELECT 1
    FROM dbo.HT_Tai_Khoan
    WHERE LaQuanTriHeThong=1
      AND (IDCSKCB IS NOT NULL OR IDNhanVien IS NOT NULL)
)
    SET @Loi=@Loi+N'- Global admin van dang gan CSKCB/nhan vien.'+CHAR(13)+CHAR(10);
IF EXISTS
(
    SELECT 1
    FROM dbo.HT_Tai_Khoan
    WHERE LaQuanTriHeThong=0
      AND (IDCSKCB IS NULL OR IDNhanVien IS NULL)
)
    SET @Loi=@Loi+N'- Tai khoan tenant thieu CSKCB/nhan vien.'+CHAR(13)+CHAR(10);

/* ---------- Viet tat kham benh common ---------- */
IF OBJECT_ID(N'dbo.DM_VietTat',N'U') IS NULL
    SET @Loi=@Loi+N'- Thieu DM_VietTat.'+CHAR(13)+CHAR(10);
IF OBJECT_ID(N'dbo.STO_DM_VietTat_LayDanhSach',N'P') IS NULL
    SET @Loi=@Loi+N'- Thieu STO_DM_VietTat_LayDanhSach.'+CHAR(13)+CHAR(10);
IF OBJECT_ID(N'dbo.STO_DM_VietTat_LuuDanhSach',N'P') IS NULL
    SET @Loi=@Loi+N'- Thieu STO_DM_VietTat_LuuDanhSach.'+CHAR(13)+CHAR(10);

/* ---------- Ket qua ---------- */
IF OBJECT_ID(N'dbo.DM_Thuoc',N'U') IS NOT NULL
AND EXISTS
(
    SELECT 1
    FROM dbo.DM_Thuoc
    WHERE UPPER(LTRIM(RTRIM(ISNULL(MaThuoc,N'')))) LIKE N'TESTAHP%'
       OR CHARINDEX(N'[TEST-AHP]',UPPER(ISNULL(TenThuoc,N'')))>0
)
    SET @Loi=@Loi+N'- DM_Thuoc con du lieu TESTAHP production.'+CHAR(13)+CHAR(10);

IF @Loi<>N''
BEGIN
    PRINT N'============================================================';
    PRINT N'KIEM TRA SCHEMA MAIN: THAT BAI';
    PRINT N'============================================================';

    /* PRINT NVARCHAR bi gioi han 4000 ky tu; tach theo tung dong de khong mat loi. */
    DECLARE @PhanConLai NVARCHAR(MAX)=@Loi;
    DECLARE @ViTri INT;
    DECLARE @Dong NVARCHAR(4000);

    WHILE LEN(@PhanConLai)>0
    BEGIN
        SET @ViTri=CHARINDEX(CHAR(13)+CHAR(10),@PhanConLai);
        IF @ViTri=0
        BEGIN
            SET @Dong=LEFT(@PhanConLai,4000);
            SET @PhanConLai=SUBSTRING(@PhanConLai,LEN(@Dong)+1,LEN(@PhanConLai));
        END
        ELSE
        BEGIN
            SET @Dong=LEFT(@PhanConLai,@ViTri-1);
            SET @PhanConLai=SUBSTRING(@PhanConLai,@ViTri+2,LEN(@PhanConLai));
        END;

        IF NULLIF(@Dong,N'') IS NOT NULL PRINT @Dong;
    END;

    RAISERROR(
        N'KIEM TRA SCHEMA MAIN THAT BAI. Xem danh sach loi phia tren va chay Doc\Database\00_CapNhat_TatCa.sql; khong chay file chot version rieng le.',
        16,1
    );
    RETURN;
END;

PRINT N'KIEM TRA SCHEMA MAIN: DAT';

PRINT N'05_kiem_tra_main.sql: OK - schema main dat yeu cau.';

EXEC sys.sp_set_session_context @key = N'QLPM_MAIN_VERIFIED',
@value = 79;
GO



